/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20241010-4","meetingId":"r06-c-settlement","date":"2024年10月10日","dateIso":"2024-10-10","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ６時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"おはようあります。３３９ページ、踏切への視覚障害者誘導用ブロックの整備、３５３ページ、公園・児童遊園維持管理費から伺ってまいります。公園・児童遊園の維持管理費について伺います。令和５年度も大変暑い夏だったと記憶しております。区が取り組んだ熱中症対策について、お聞かせください。","respondent":"大友公園課長","answer":"公園における熱中症対策といたしましては、日陰をできるだけつくりたいということで、パーゴラに葦簾を設置しまして暑さ対策をしています。葦簾に加えまして、ミストの設置、稼働も併せて行わせていただいているところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"パーゴラへの葦簾は、私も見かけております。随分涼しさが変わるなと実感しています。今年の夏も大変暑くなっておりました。そこで、都内の各地で公園での花火が解禁となっておりますが区内の公園で花火が禁止されている理由を伺います。","respondent":"大友公園課長","answer":"品川区立公園条例におきまして、公園の管理に支障がある行為をすることを禁止事項としているというところにおきまして、火災の危険性であったり、近隣に対する煙や音の影響などから禁止しているものです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"これまで花火については、子育て世帯からも様々要望をいただいていますが、公園課は特に苦情も多く大変難しい判断になるだろうと思ってきました。例えば、２日間と限定した千代田区は、１,０００人が殺到したとの記事も見ております。公園で花火ができるようにしてもらいたいと考えていますが、区のお考えと、また、難しさもあると思います。その辺りをお聞かせください。","respondent":"大友公園課長","answer":"区といたしましても、他区の状況も踏まえまして、来年の夏に向けて検討を進めてまいりたいと考えています。使用できる公園や場所、時間帯など、一定のルールを設けて試行という形を考えていくことになるかと考えています。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"他区の状況をお伺いしましたけれども、時間帯ですとか、また、手持ちしか駄目だという花火の種類などのルールですとか、様々な事例が出てきておりますので、ぜひご検討いただきたいと思います。そこで、２点伺いたいのですが、まず、犬を連れて入れる公園が、区内に幾つあるのか、そしてまた、入れる公園内で入れない区域のルールなどがあればお聞かせください。","respondent":"大友公園課長","answer":"犬を連れて入ることができる公園、また、児童遊園の数は、計２０か所となっています。各公園とも園路部分のみに入ることが可能となっておりまして、植物が生えている植栽帯や芝生、花壇などへの立入りはできないという形のルールで運用させていただいてあります。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"区民の方が知らないことで、先ほどからの質問につながるのですが、なぜペットが公園に入っているのだというふうな苦情も入ってくると伺っております。苦情を減らすという観点からも、周知の仕方をぜひご検討いただきたいと思いますので、よろしくお願いいたします。実際に使う方が現地で困っていることについて把握をする必要があると思いますが、どのような整備をされたのか伺います。","respondent":"森道路課長","answer":"踏切手前部の点字ブロックの設置につきましては、苗木原踏切ですけれども、令和４年度から当事者の方とお話をさせていただきまして、昨年度、実際に現地で、立ち会っていただいて、どういった部分で困っているかを確認したところです。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"１点伺いたいのが、事故に遭われた方の動画を実際に見ておりまして、踏切内に入って警報音が鳴って、立ち止まってしまって、引き返そうとしてしまわれたと記録されております。視覚障害者の方々の意見を聞きながら、ぜひ歩道の延長沿いで踏切の中にも点字ブロックをつけていただくご検討をお願いしたいのですが、いかがでしょうか。","respondent":"森道路課長","answer":"国のガイドラインでは、手前部につけるものと、中につけるものと形状を変えるというふうにされておりまして、基本的には、鉄道事業者のほうで中に設置していただくように、今、協議を進めているところです。","id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"中に入ってしまったかどうかということも大変分かりづらいというのは、本当に今、おっしゃっていただいたとおりであると思います。ぜひとも引き続きご準備、そして整備をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３３９ページの、今、西村委員からありましたけれども、踏切への視覚障害者誘導用ブロックの整備、３５９ページの住宅・建築物耐震化支援事業について、また、そこに関連して、耐風診断についてお伺いしてまいります。初めに、視覚障害者誘導用ブロックの整備について質問いたします。","respondent":"森道路課長","answer":"区内の踏切は、東急電鉄が一番多いところですけれども、ＪＲと京急電鉄にもあります。ＪＲと京急電鉄につきましては、今年度、これから協議を進めていきまして、しっかりと踏切手前部の整備を進めていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ踏切手前部の残り部分と、またさらに、先ほどもありましたとおりで、踏切道内の部分についても早急に進めていただければと思います。道路課では、昨年の夏頃に、先ほどもありましたが、実証実験として、苗木原踏切を視覚障害者団体に実際に渡ってもらい、現場でアンケートをとったということでお聞きしておりますが、どういったお声があったのか、お聞きできればと思います。","respondent":"森道路課長","answer":"昨年度の意見交換の中では、点字ブロックだけではなくて、例えば、音声案内ですとか、そういったものも組み合わせて行ってほしいというようなお話であったり、今、ガイドラインは統一的なものが示されておりますけれども、当時は、国や都と。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私も視覚障害者団体と、また、地域の視覚障害者の方から踏切道内の中に入ったときに、両幅に縁石があると安心して素早く進むことができるということでお話を受けました。危険な箇所で視界が全くなくなるというのは本当に恐怖です。道路課でそういった現場の声をお聞きしているようであれば、その現場の声を大事にして力強く進めていただきたいと思いますが、その上で区のお考えをお聞きしたいと思います。","respondent":"森道路課長","answer":"音声誘導につきましても、点字ブロックを活用した音声誘導という事業を本年度から進めておりますけれども、それについても障害者支援課と一緒に、当事者の方の意見を聞きながら進めているところです。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"踏切内での端から端までを一直線で結ぶ点字ブロックが対策として主流となっていますが、主な用途は違うとしても、縁石も考慮していただき、現場の声を大事にして、事故が起こる前に、またさらに視覚障害者の不安を軽減していけるように、より一層、鉄道各会社への働きかけ、また、その整備について、踏切内も含めて一体的に進むように求めたいと思いますが、各鉄道事業者と区との話合いや。","respondent":"森道路課長","answer":"鉄道事業者も、これを目標に設置していくというふうに聞いておりますので、引き続き協議を進めていきたいと考えています。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"特に危ないと危険視されているところを重点的に、そこから進めていただければと思いますが、またもう１点で、特に旗の台駅の東口にある踏切は怖いというお声も聞いています。こういった場所も考慮して、さらに進めていただければと思います。続いて、住宅・建築物耐震化支援事業について質問いたします。ここについて、耐風診断の区の認識をお聞きできればと思います。","respondent":"森建築課長","answer":"令和元年に起きました台風の影響で、千葉県で大きな被害が出ているということは認識しております。区内でも被害が出ておりまして、屋根の耐風診断というもの、国の補助もあるということは認識しています。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"本日もよろしくお願いいたします。私からは、３３３ページ、交通安全啓発費について、３５７ページ、おもてなしトイレ整備費について、３６７ページ、防災訓練経費、また、３６９ページ、避難行動要支援者経費について順不同で質問をします。最初に、おもてなしトイレ整備費についてお伺いします。品川区でも、令和９年度までに洋式化が完了すると議事録でも確認させていただきました。","respondent":"大友公園課長","answer":"令和６年度、１０か所の実施を予定しておりまして、１０５か所、８１％の洋式化が完了する予定になってあります。毎年１０か所程度の洋式化を進めまして、令和９年度に全１２９か所の洋式化を完了させるという考えです。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"確認","question":"進捗について確認することができました。実は、最近、区民からの相談で一番多いのが公共トイレについてのご相談です。女性の視点、防犯の視点を取り入れてほしい。誰しもがトイレだと分かって、そして利用しやすい、そのようなトイレを品川区でも実現してほしいというようなお声をいただいております。このような区民の声を受けて、区の認識、また、今後のトイレ整備についての見解をお聞かせください。","respondent":"大友公園課長","answer":"今、委員からお話がありましたように、渋谷区が実施しているようなデザイントイレであったり、利用しやすいトイレというような改修に向けましては、公園の改修のタイミングに合わせたトイレの改修を行っていきたいと考えておりまして。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"渋谷区のもの全てがいいというものではなく、デザインが変わり利用しやすくなった、そして観光客からの喜びの声などがある一方で、維持費がかかる、また、故障の問題、トイレと分かりにくいなどの課題もあるというふうに伺っております。ぜひこのような事例も研究していただき、誰もが使いやすいトイレの整備を進めていただきたい。こちらは重ねての要望とさせていただき、次の質問とします。","respondent":"山下交通安全担当課長","answer":"これは警視庁からの暫定値でいただいているところですけれども、昨年は、７月１日の法改正後１２月末まで、０件でございました。１件も発生していないところでしたけれども、本年に入りまして、８月末現在、８件、電動キックボードが関与する事故が発生しているです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"８件起きているということなので、軽症であっても、ヘルメット等を着用していない場合は、予後が大変になるとか、身体に影響が出る事故につながるというふうに思っております。もう１点、併せてヘルメットの着用率についてです。警視庁のヘルメット着用率の調査も見させていただきました。その点について、ヘルメット着用率、上昇率等わかりましたら、教えてください。","respondent":"山下交通安全担当課長","answer":"こちらは警視庁の定点調査、２か月ほど調査したところの結果になっておりますが、いずれにしましても、区のヘルメット助成の影響もあるかと思いますけれども、徐々に着用率は上昇してきているところであると認識しております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"若い世代の方々が電動キックボードによく乗っていると思います。その点についても改めて質問しますので、この後お答えください。ヘルメットを着用しない理由を見てみますと、着用が面倒、次いで、努力義務であり義務ではないから、その次に、駐車場また移動先にヘルメットの保管場所がないというものが回答の理由として出ております。その点についてもご見解をお聞かせいただければと思います。","respondent":"山下交通安全担当課長","answer":"ヘルメットの着用については、区内でいいますと、ＬＵＵＰなどの事業者がいるのですけれども、そちらとも連絡をとることもありますので、そういった機会を捉えて、今後のヘルメットの着用率向上に向けた対策をとるようなことも申入れしてまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう１点、こちらは要望なのですけれども、今回、品川区が打ち出しているもの、自転車ヘルメット購入助成というふうになっていますが、課長に確認したところ、ＬＵＵＰの電動キックボードに対しても、このヘルメット助成が活用できるということでした。こちらは要望とします。防災訓練に障害がある方も参加できるようにとの要望を以前から求めておりました。現状と課題についてお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"今後、まだ訓練がありますので、そこを周知するほか、職員に対してもしっかり周知をして対応できるように進めてまいりたいと感じております。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"障害者団体の方へ、そういう訓練へ参加できるということをお伝えしてほしいとご要望したところ、早速実施をしてくださったということで評価をします。他区の事例等を確認させていただきました。ただ一方で、障害がある方がメインで参加できるような防災訓練を行っている自治体もあります。このような活動を品川区でもぜひ進めていただきたいと思っているので、その点について見解をお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"一方で、支援する側の訓練としましては、例えば、しながわ防災学校等で車椅子の体験をやったりだとか、障害者を車椅子で移動させるような訓練もやったりできますので、そういったことも広報していければと考えています。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点については、ぜひ検討していただきたいと思います。最後に、個別避難計画は福祉部を中心に進めていると思いますが、具体的な避難支援にどのように活用しているのでしょうか。時間が短いので、答えられる範囲でお答えください。","respondent":"平原防災課長","answer":"避難行動要支援者につきましては、個別避難計画ではなくて、避難行動要支援者名簿を作成し、同意のあった方について平常時から情報を提供しており、その提供のあったものをベースに、地域において、ふだんからどのような方がいるのか、そういったところを把握していただいて。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この点について、本当に災害医療というところとか、障害がある方の防災の観点はすごく大切だと思っているので、この点については、ぜひ総括のところでも改めて質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"３６５ページ、区営住宅管理費、３５１ページ、都市再開発費について伺います。現在、区営住宅に入居している方にお話を伺うことができました。質問なのですけれども、令和５年度の区営住宅入居者のうち、保証会社を使っている方は何％ぐらいいるのか、もし分かればお伺いしたいと思います。併せて、改めて区営住宅でも入居の際の保証人を不要とするよう求めますけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"引き続き、区営住宅では保証人は必要というふうに考えておりまして、適切な納付の指導、そして寄り添った対応をしていきたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し聞いたことに答えていない気がするのですが、丁寧にやっているということですよね。ということで、連帯保証人を不要とするということは、現在、１３か月分の家賃を払っている先ほど紹介した方の負担軽減にもなりますし、セーフティネットの中核としての公営住宅の役割を果たすことにつながるのだとも思いますので、改めて、区営住宅の保証人不要へ改正を求めますけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"保証人に対するご意見をいただいたところです。現在は、区営住宅の入居の要件は、保証人を立てることを要件としております。しっかりと引き続き寄り添った対応しつつ、今後も入居要件としては、保証人を置くという形で現在は考えているところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"公営住宅の役割を果たすためにということもありますので、これは品川区、変えないというのは、私は問題になるのではないかと思いますので、変えていただきたいと強く申し上げたいと思います。伺いたいのが、小山三丁目第二地区の大きな権利を持つ方から、区長宛に、私はこの再開発に不同意ですという通告書が届いているかと思うのですけれども、それは間違いないでしょうか。","respondent":"中道都市開発課長","answer":"不同意の件につきましては、区のほうにも提出されていることは確認しております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そうなのです。同時に、面積要件もあって、地区内の権利を持っているうちの３分の２以上の面積も同意していないと組合設立が認められないという法律になっておりますけれども、先ほどの、不同意と言った方の権利は、かなり大きいと私は思うのですけれども、今の要件に沿って、それぞれどれぐらいを占めているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"今、準備組合のほうで、同意について地権者の方に対して個別面談等を行っているということは聞いております。法的要件は、土地、借地権等の３分の２以上というところで、現在、まだその３分の２に到達していないということは報告を受けています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そうなのですよね。それで、私が伺ったのは、この不同意を出された方が、かなり大きな面積の地権者なのです。その方が、先ほど言った認可要件に照らしてどれぐらいの位置を、割合を占めている方なのでしょうかということを伺いたいのと、それと、その方がなぜこの再開発に不同意なのかという理由です、どのように捉えているのか、区としての認識を伺います。","respondent":"中道都市開発課長","answer":"一個人の全体に対する割合というところは、今、手持ちに資料がないのでお答えできない状況です。その方が、いわゆる再開発に不同意ですが、今、自宅の庭に大きな家がある、そういった風情のある庭は維持していきたいというようなことは聞いております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"それともう１つ、大崎西口駅前地区も大きな反対運動が起きておりますが、こちらはまだ都市計画前の段階で、都市計画手続に踏み出せないという状況なのです。日に日にエスカレートする再開発準備組合の横暴なやり方に対し、行政が適切に指導することを求めます」というように書いております。これ、適切な指導をすべきだったのではないですか。これ、やるべきだったのではないでしょうか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"今おっしゃられた件ですけれども、私も報告を受けておりますが、やはり一時期、声が大きい場面はございましたが、双方適正に意見交換を交わしているというふうな認識です。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは、３５７ページ、Ｐａｒｋ－ＰＦＩ導入に向けた事業化検討、３６７ページ、防災関係組織経費に関連して防災訓練、防災普及教育、マンション防災について、そして３３９ページ、無電柱化推進事業についてお伺いいたします。","respondent":"大友公園課長","answer":"事業の実施に関して理解を得たです。現在、事業者の公募開始に向けた準備を進めている段階となってございまして、今後、早い時期に公募指針を公表いたしまして、事業者の選定および基本協定の締結に向けた手続に入りたいと考えているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうすると、私が見ているのは今年の２月２７日の日付が書いてあるスケジュール案なのですけれども、少し遅れてしまうのでしょうか、その辺りの確認と、公募に当たりまして、やはり昨今、建設関係の人件費、資材費の高騰、そして働き方改革の影響などがありまして、かなり不安定な状況にあると思うのですけれども、このスケジュールどおりに令和７年度の工事の完成、そして開業ができるのかどうか、その辺り。","respondent":"大友公園課長","answer":"年度内のスケジュールにつきましてですけれども、まず、こちらは、公募を実施するに当たっての地域調整が最近ついたというところ、また、公募指針を決定していくに当たりまして、慎重に公募指針の内容を詰めていくというところで実施をしているところで。","id":"exchange-029"},{"speaker":"筒井委員","kind":"提案","question":"よろしくお願いします。ですから、例えば、マインクラフトでのバーチャル空間での防災訓練、被災体験を実際にしていただいて、どうやって逃げたらよいのかとかということを楽しみながらやっていただき、そして総合防災訓練でリアルなものを体験していただく。そうしたことも今後必要になっていくのかなと思っているのですけれども、その辺り、区のお考えはいかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"委員ご質問のありましたプログラミング等を活用した今後の新たな防災訓練は、少しまだこちらとしても検討はしていなかったところですが、例えば、ＶＲを使った地震時の仮想空間における対応ですとか、こういったものは、しながわ防災学校でも使えますし、また。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"恩着せがましいとか、そういうことではなくて、やはり品川区民の税金から、交付金でこうしたことが行われましたと、品川区の行政として、マンション防災をしっかりと考えていますよということもお伝えするためにも、品川区によるものということが分かるような貼り紙を掲示してくださいとか、そのチェアに、今後、品川区のロゴマークを印刷できるのかどうか分かりませんが。","respondent":"平原防災課長","answer":"こちらにつきましては、マンションの管理組合が行うべきマンション防災の取組を、区が逆に負担するというような観点ではなくて、このチェアを配ることによりまして、今後、様々必要なマンション防災について。","id":"exchange-031"},{"speaker":"筒井委員","kind":"意見","question":"ぜひ今後のお伝えの仕方として、やはりマンション、エレベーター全基に防災チェアを導入していくべきかなと思っているので、その辺り、今後、防災意識の向上ということをお伝えするときに、エレベーターチェア、防災チェアを管理組合ご自身でしっかりと準備してくださいと、対応してくださいということをお伝えしていってほしいなと考えていますので、その辺り。","respondent":"平原防災課長","answer":"先ほどございましたけれども、マンションのチェアですが、１基だけあってもどうすることもできないものですので、管理組合としては何をしなければならないのか。そのチェアの使い方、そういったところを居住者にどうお知らせするのか。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後、引き続き、広報しながわなど、周知の点も工夫して、どんどん進めていっていただきたいと存じます。よろしくお願いします。無電柱化なのですけれど、先日の私の一般質問の際、区道の無電柱化率は約７.２％ということでしたけれども、区の推進計画ですと、２０２９年度までで、２０２４年度が中間年度です。２０２９年度までに、これ、１００％達成可能なのかどうかをお聞かせください。","respondent":"森道路課長","answer":"今、３路線動いておりますけれども、東京都とも新たな会議体も立ち上がりまして、それぞれ進めていきたいというふうに考えております。引き続き、いろいろな事業者と協力しながらやっていきたいと思います。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"現実的には、メリハリをつけて進めていくしかないと思っているのですけれども、新しい技術の活用などを行っていただき、ぜひ区道も加速していっていただきたいと存じます。ぜひよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"３６７ページの防災関係組織経費、３３９ページ、道路バリアフリー整備費から質問をいたします。防災のことなのですけれども、首都直下地震が発生し、品川区において停電した場合に、どれぐらいの日数で普段通りに電気を使えるようになるか、改めて教えてください。停電時に避難所などで使えるポータブル電源は、区で何台所有していて、どういった施設に配置をしているか教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"避難者への支援といたしまして、各避難所に１台ずつ。区有施設に１０台、合計６２台のソーラーパネル付きのポータルポータブル蓄電池、スーツケースのような形をしていますが、そういったものを備蓄しています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"品川区では、２０２２年１０月に、このEcoFlow Technology Japan株式会社からの寄贈で、ソーラーパネルを５つ、あと、ポータブル電源も５台ずつ寄贈いただいていることを確認しました。この寄贈分については、どのようなきっかけで寄贈に至ったのかを教えていただきたいと思います。現在、区として、どこで保管をしているか、これまでどのような場で活用してきたかを教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"寄贈していただいた蓄電池等につきましては、先ほどご案内した中の区内の５つの協議会で備蓄しているものです。こちらは、各協議会で、毎年１回、訓練を実施しています。そちらで実際にその蓄電池を使ってみたり、訓練の際に点検や充電などを行っている、そういう状況です。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"この寄贈いただいた分も、きちんと年に１回、訓練で使用できている、活用できているということは確認がとれました。日頃から使うことで災害発生時に備えられると思うのですけれども、その訓練のときに、ソーラーパネルからも、充電はされたかという点をお聞かせください。","respondent":"羽鳥防災体制整備担当課長","answer":"ソーラーパネルでの充電を実施したかどうかですけれど、実際にソーラーパネルで蓄電池を充電するには、日照条件がよいところで、屋外で、大体１０時間近く置いておく必要があります。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。訓練でも、実際に起きたときを想定してやっていくものだと思いますので、例えば、どこにパネルを設置するかとか、そういった確認だけでもしていただきたいというふうに思いました。品川区では、在宅避難者がほとんどということですが、各家庭でもポータブル電源や自然エネルギーで蓄電できるものを用意したほうがいいか、どういうふうにお考えでしょうか。","respondent":"平原防災課長","answer":"現在、災害情報をとっていただくためには、電子機器は非常に重要ですので、各ご家庭でポータブル電源を用意いただくということは非常に重要なことかと思ってあります。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"各家庭での電源は大変重要ということで、区民への電気啓発は、訓練にて実際に触れることでポータブル電源の備蓄の普及啓発に活用できると思うのですけれども、EcoFlow Technology Japan株式会社のものに限らず、ポータブル電源について、訓練や防災イベントなどで、来場者、区民が触れる機会などは用意していらっしゃいますでしょうか。","respondent":"平原防災課長","answer":"防災用品のあっ旋という形でもご紹介していますので、さらなる周知も含めまして、今後とも広めてまいりたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"直接事業者が把握するということで、分かりました。次に、道路バリアフリー整備費から１点だけお伺いします。これは以前からいただいておりますので、皆様も把握していることかもしれないのですけれども、こちらは傾斜をならすことはできるのでしょうか。鉄道会社への相談実績だったり、調査だったり、されてきたことがあれば教えてください。","respondent":"森道路課長","answer":"ご指摘の戸越銀座１号踏切ですけれども、確かに坂がきつくて上りづらいというところは、こちらも認識しています。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"私からは、３６７ページ、防災関係組織経費、３６９ページ、応急活動対策費についてお伺いいたします。ポイントは、避難者から直接話を伺うことです。区は、９月に石川県輪島市へ、毛布、土のう袋、携帯トイレなどの支援物資を緊急輸送しましたが、被害が度重なる能登地方や他国の防災対策の事例から、どのような教訓を得て今後の品川区の防災対策へと生かしていくのでしょうか。","respondent":"平原防災課長","answer":"災害対応に当たりまして、民間支援団体との協働ですけれども、品川区でも支援いただくＮＰＯ法人と協定を締結させていただいてございまして、例えば、この３月に行った品川区防災フェアなどにも出展いただいて、日常的な関係を構築して、災害時の運用を決めているところです。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"災害と心のケアについてお伺いいたします。災害時にどのような心の被害が生じるのかを知ることで、自分自身で対処できるスキルを身につけてほしいと考えますが、心に備えをする必要性について、区のご見解をお聞かせください。優先順位があるかと思うのですが、女性の視点からの備蓄品として、今後、心のケアの観点からの検討もお願いしたいと思いますが、区のお考えをお聞かせください。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"そのような中で、どういう対処をしていくのか、災害後の心の変化にどう対応するのか、そういったところを皆様に提案させていただいているところです。先ほどご提案いただきました化粧品につきましても、どのような形で、区が独自で備蓄をするのか、民間企業と協力をしていくのか、そういったところも含めて、様々検討してまいりたいというふうに考えてあります。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３６５ページ、住宅運営費、３４７ページ、地域交通検討経費についてお伺いいたします。住宅運営費について、令和５年度の区営住宅・区民住宅の団地数、戸数、入居者数などをお知らせください。","respondent":"川原住宅課長","answer":"区営住宅は１３団地４３９戸、区民住宅は８団地７４１戸です。入居者数につきましては、まず、区営住宅につきましては１６名となっています。区民住宅につきましては４０名です。","id":"exchange-043"},{"speaker":"えのした委員","kind":"提案","question":"多くの区民の方が住まわれていることの確認がとれました。そこでお伺いいたします。予算特別委員会でも質問させていただき、大変評価をしております。通常時でも、椅子として利用できるので、高齢者も増えていることから、私も自宅のマンションの理事長に、品川区のよい取組ですと、募集チラシを渡して提案をしました。区のご見解をお伺いします。","respondent":"川原住宅課長","answer":"現在、エレベーターがある団地については、区営住宅は１３団地中７団地７台、区民住宅は８団地中６団地１４台、計２１台のエレベーターがございまして、うち区民住宅の１台のエレベーターについては。","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問・要望","question":"エレベーター２１台、前向きにご検討ということで、確認がとれました。私も視察に伺ったところ、区営住宅、南大井五丁目、西大井第三ですか、あと、区民住宅ではファミーユ旗の台、こちらは比較的築年数が古い建物ですが、築年数が新しい高層階のファミーユと比較すると、エレベーターのかごのサイズが大小あり、様々形も違うと思います。","respondent":"櫻木地域交通政策課長","answer":"グリーンスローモビリティについてですが、１０月５日まで試験運行という形で、１０月６日から区民の皆様にご利用いただくような形で運行を開始しました。実施としましては、火曜日、木曜日、土曜日、日曜日という形で運行しています。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問","question":"私も試乗会に参加させていただきましたが、地域の活性化、また、観光資源、脱炭素、ゼロカーボンシティを目指した取組だと理解しております。そこでお伺いします。少しこれ、細かいことだと思いますが、車のナンバーが横浜ナンバーだったことが気になりまして、なぜご当地の品川ナンバーではないのか、ご説明をお願いいたします。","respondent":"櫻木地域交通政策課長","answer":"今回、グリーンスローモビリティをやらせていただくということで、試行運行ですので、今回は京急電鉄にご協力いただきまして、車両をお借りするということで、京急電鉄が登録されている車両が横浜であったです。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認がとれました。先月は、会派の勉強会で、Community Mobility株式会社から、ＡＩオンデマンド交通について、他自治体での取組等についてもお話を伺いました。品川区内でも、地域の実情に即した利用者の利便性を高める取組を要望しておりますが、こちらについてご見解をお伺いいたします。","respondent":"櫻木地域交通政策課長","answer":"今、委員ご指摘いただきましたとおり、品川区内、利便性が高い状況とはいえども、各地区を見ると、なかなか交通課題が残っている地区もある状況ですので、それぞれの地区に応じた取組を進めてまいりたいと考えています。","id":"exchange-047"},{"speaker":"塚本委員","kind":"確認","question":"私からは、３３５ページ、道路擁壁点検調査委託、３６５ページ、空き家等対策事業、３６９ページ、しながわ防災体験館運営費の３点でお伺いしたいと思います。この擁壁については、区道に面してはいますけれども、ＪＲの土地であるということもあります。いわゆる道路擁壁点検調査の対象になっているのか、安全確認等は区として行っているのか、ここについてお伺いしたいと思います。","respondent":"森道路課長","answer":"ご指摘の擁壁につきましては、ＪＲの管理でございまして、今回の擁壁点検の中では対象にはしてございません。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"そうなのですね。ＪＲで管理しているということではありますけれども、やはり一定の安全性の確保や、浸水被害というほどではないかもしれないですけれども、水が出ることによって区道にいろいろな影響があることについて、区として、どういった形での安全の確保というか、区民のこういった不安に対してのお答えをしていくのかをお伺いしたいと思います。","respondent":"森道路課長","answer":"現在、１６３号線整備について、ＪＲと定期的に打合せを行っていますけれども、その中でも、今ご指摘の浸水のお話であったりとか、擁壁の安全確認について、そういったものについて、折を見てご教示いただきながら、区としても安全性について確認をしていきたいと考えています。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"ＪＲが主になるというところは、致し方ないところなのかなと思うのですけれども、ぜひ情報共有、また、区からいろいろお伝えできるところは伝えていって、現状で、基本的に今、区として、あの擁壁の安全性等について、どの程度のもの、どういうものだというふうに認識しているのか、今言える範囲のことになってしまうかもしれませんけれども、最後にお伺いしたいと思います。","respondent":"森道路課長","answer":"当該擁壁について、ＪＲに直接的にこの擁壁についてどうですかというお話をお聞きしたことは近年ないのですけれども、定期的な社内基準に基づいた擁壁の点検を行っているということは聞いておりますので、一定程度、安全性は確保されているのだろうと考えていますけれども、今。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。ありがとうございました。この事業がどういったものかということをお伺いするとともに、その事業において、これは民間事業者なども協力をいただきながら進めている事業かと思いますけれども、区の職員は、この空き家適正管理促進の中でどのような関わり方をされているのか教えていただきたいと思います。","respondent":"川原住宅課長","answer":"区の職員が実施している事業といたしましては、空き家の除却の解決に向けるための弁護士への相談委託、あとは、持ち主が不明の場合が多々ありますので、そういった場合の相続人の調査を司法書士に依頼をしたりですとか、あとは、調査員とはまた別に。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"結構区の方がやられている部分がある。その辺のところをもう少し民間事業者と協力して、今も協力されている部分があるかと思うのですけれども。それに対しての対応等もいろいろと出てくるのだろうなと思うのですけれども、そういった中で今後の民間事業者との協力体制について、今は区の職員が関わっている部分の負担軽減みたいな話とかは、どのようにお考えなのかお伺いしたいと思います。","respondent":"川原住宅課長","answer":"こちらの認定は、もちろん区の職員が関わるべきことではあるのですが、認定後の現地の対応であるとか調査といったところは、所有者の許可が下りれば民間への委託等もできる予定ですので、そういったところは、引き続き、区が積極的に所有者の方に管理促進を図りながら。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問","question":"ということでいくと、区の職員でなければできない、でなければ駄目なところといいますか、職員でないとできない部分が最後は残るというところがあるのでしょうか、お伺いします。","respondent":"川原住宅課長","answer":"区の職員が行うべき空き家の認定の業務は、国のガイドラインに準じて区のガイドラインを策定した上で、そこの認定業務が発生するところです。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこについて、区の職員として関わるべきというか、区の職員がやらざるを得ないところがあるということであれば、課長にお伺いしても難しいかもしれませんけれども、現在の体制強化といいますか、職員の人員増員、しっかりこの条例改正に対応できる、こういったことも含めて体制の強化を行い、効果的に区内の空き家の適正管理を進めていただきたいと思いますけれども、最後に一言お願いします。","respondent":"川原住宅課長","answer":"年々数は増えている状況ですので、そういった適切な空き家の管理というところでは、区の職員のマンパワーも非常に重要です。しっかりとその部分も促してまいりたいというふうに考えてあります。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"しながわ防災体験館運営費というところで、しながわ防災体験館は、２０１６年３月１１日オープンし、これまでたくさんの方が訪れています。こういった報告書で、第二庁舎のことが範囲となっている中で、この防災体験館についての今後について、現在、どのように担当の防災課としては捉えていらっしゃるのか、お伺いしたいと思います。","respondent":"平原防災課長","answer":"しながわ防災体験館ですけれども、今後といいましょうか、そういった検討につきましては、様々な新庁舎あるいは庁舎跡地の全庁的な検討の中で考えていくべきというふうに考えてございまして、防災課といたしましては、個別に何か検討している、そういったことはございません。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"そういった中で、近年、熱中症といったものも、もしかしたら入るかもしれませんけれども、風水害の被害、そういった気候変動、災害のリスクといいますか、そういうものが非常に高まっているということで、そういった風水害についての体験館でのいろいろな展示なり、体験なり、研修なりといったことを、もっとやっていってもいいのではないのではないかなというふうに思いますけれども。","respondent":"平原防災課長","answer":"風水害は実際にかなり頻発していますので、今後ともそういったところはしっかりと私どもも考えながら普及啓発に努めてまいりたいと考えています。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"跡地検討がなされる中で、この防災体験館、今後どうなっていくかということについて、いずれ検討、そういった議論が出てくるかなというふうに想定いたします。そのときが、よい契機でもあると思いますので、風水害の体験とか、防災体験館のアップグレードというものをぜひ検討して進めていただきたいと思いますが、最後によろしくお願いします。","respondent":"平原防災課長","answer":"災害に備える意味で防災普及啓発は非常に重要なものだと思ってありますので、体験館も含めまして、今後ともしっかりと対応してまいりたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は、３６６ページ、防災費、３５７ページ、子どもたちのアイデアを活かした公園づくり、同じく３５７ページ、公衆便所費についてお伺いいたします。令和６年第２回定例会、第７３号議案の資料を見ますと、６００台購入ということでしたが、現在、反響はどれくらいあり、どの程度設置が進んでいるのかといった進捗状況、椅子としての強度はどれぐらいでしょうか。","respondent":"平原防災課長","answer":"先ほどのご質問の答弁でもございましたとおり、今後物の入替えなども含めた形でのマンション防災を管理組合でご検討いただく中で、そういったものもやらなければならないのだといったところを認識いただくことが重要かなというふうに考えてあります。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、３５７ページ、子どもたちのアイデアを活かした公園づくりについてお伺いします。平成２０年度から取り組み、令和３年にオープンした大井坂下公園で６か所になると思いますが、現在、西五反田公園の工事の進捗と今後の予定をお聞かせください。子どもたちのアイデアを聞くワークショップなどは定期的に行っているのでしょうか、併せてお聞かせいただければと思います。","respondent":"大友公園課長","answer":"ワークショップ等々の定期開催というところにつきましては、公園の大改修に応じて、そのアイデアが少なくなってきた段階等々で実施をしていますが、最近でありますと、子供の森公園の改修に合わせて。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、３５７ページ、公衆便所費から、大井町駅前公衆トイレについてお伺いします。２０２０年の東京オリンピック・パラリンピックに向けて、おもてなしトイレ事業として改築されたこちらのトイレは、誰でもトイレを含む特色あるタワー型個室トイレが６棟建っていますが、こちらの現在の使用率は把握されていますでしょうか。どのように管理をしているのか、お聞かせください。","respondent":"大友公園課長","answer":"実際の使用数について、何名の方がどのような目的で使ったというカウントはしていないというところにはなってありますけれども、こちら、管理等々につきましては、清掃委託等々を実施しているところでございまして、利用頻度が多いトイレということで、基本的には。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"提案","question":"きれいに維持するため、１日に何回かお掃除に入られているということで、ありがとうあります。過去の議事録を見ますと、犯罪抑止の提案をしている議員はおりましたが、その後、犯罪抑止の取組はどのようになっていますでしょうか。せっかくつくったので、衛生面も含め、ここにあってよかった、使いやすかったと大井町を利用する方に思っていただきたいのですが、何か計画などがあればお願いします。","respondent":"大友公園課長","answer":"こちらは、委員ご指摘のとおり、過去、犯罪等々が発生したというところもあり、その後、防犯カメラであったり、そういうような対策等々の中で、また、維持管理の中で清潔を保つことによって犯罪が起きないというところを特に意識しておりまして。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"意見","question":"ご答弁ありがとうあります。ごみの少ないきれいなまちは犯罪が少ないという話も聞きますので、なるほどと思いました。つくりっ放しではなく、その後もしっかり調査して、改良や次の計画に役立てるということが大切だと思いますので、私も他区の工夫などを探していきます。引き続き、前向きに取り組んでいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、３５７ページのＰａｒｋ－ＰＦＩ導入に向けた事業化検討、３５１ページの大井町駅周辺地区再開発事業、３６７ページの防災訓練経費、３６９ページの防災普及教育費、３７１ページの防災情報配信経費について伺います。防災訓練について伺います。９月２９日、西大井広場公園で開催された大井第三地区の総合防災訓練に伺いました。","respondent":"伊藤災害対策担当課長","answer":"一方で、訓練参加者が限られてしまうというような課題があるのではというような意見も受けているような状況です。まだ１か所でしか実施してございませんので、今後できるものはすぐに改善、また、この経過を踏まえて改善できるものは改善していきたいと考えております。","id":"exchange-063"},{"speaker":"山本委員","kind":"質問・要望","question":"例えば、ゲームの内容などは、創意工夫でさらによいものにしていただきたいと考えます。どうぞよろしくお願いいたします。入場者数はいかがだったでしょうか。","respondent":"伊藤災害対策担当課長","answer":"今回の訓練につきましては５０６人で、昨年が４７７名でございましたので、若干の増加が見られた状況です。","id":"exchange-064"},{"speaker":"山本委員","kind":"質問・要望","question":"初めての方に多く来てもらい、また、家族連れの若い方々に多く来てもらえたこともよいですね。周知の方法の効果ですね。１０月６日のひらさん広場で行われた荏原第三地区の総合防災訓練も伺いました。従来の訓練もよいのですが、やはり新しい防災訓練を増やしていただきたいと考えます。今年度もまだまだありますし、少し早いですが、今年の５地区からの拡大の検討を要望します。ご見解を伺います。","respondent":"伊藤災害対策担当課長","answer":"今後も各地区と話合いを重ねまして、区として、その地区、地域に合ったような支援を行いまして、同じ地区内にあるマンションや事業所なども含めまして、より多くの地域の方々がつながりを広められるよう対応してまいりたいと考えています。","id":"exchange-065"},{"speaker":"山本委員","kind":"質問・要望","question":"災害は発生までの事前の準備が重要です。は参加していただくことです。先ほど、周知については伺いました。その情報が多くの区民の皆様に届くよう、区全体での情報発信の整備、開発の検討を要望し、次に進みます。続いて、防災の普及啓発費に関連して、携帯トイレ全戸配布について伺います。予算特別委員会で質問し、要望させていただきました追加購入を促すためのチラシ等は同封できましたでしょうか。","respondent":"平原防災課長","answer":"今回の全戸配布につきましては、防災用品のあっ旋チラシにつきましては同封してございません。","id":"exchange-066"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。残念ですが、チラシの同封がない旨、承知いたしました。携帯トイレの配布は３日分相当ですが、災害対策には７日分の備蓄が好ましいことから、残りの４日分は自助での購入を促すということだと理解しております。残りの追加購入はどのように促すお考えでしょうか。","respondent":"平原防災課長","answer":"そういった上で、防災課が別に行っております防災用品のあっ旋につきまして、様々な機会を捉えて周知してまいりたいというふうに考えてあります。","id":"exchange-067"},{"speaker":"山本委員","kind":"質問・要望","question":"分かりました。せっかく、区民の皆様へ配布する機会ということで、できるだけ有効に使っていただきたいと思いますが、迅速に送付するという時間との兼ね合いで難しい点もあったかと思います。次に、今年度実施するエレベーター用防災チェアの無償配布について伺います。今回、対象となるマンションは何棟でしょうか。申請方式となっておりますが、現状、何棟の申込みがありますでしょうか。","respondent":"平原防災課長","answer":"本事業の対象となるマンションにつきましては、約３,２００棟です。申込みの実績ですが、本年１０月１日時点で、配布済みの３７件を含めまして９５件となっています。","id":"exchange-068"},{"speaker":"山本委員","kind":"質問・要望","question":"多くのマンションに迅速に利用を促していただきたいと考えます。周知方法はどうしていますでしょうか。周知方法に関する現状の認識、今後のやり方をお教えください。","respondent":"平原防災課長","answer":"周知につきましては、広報しながわ、区ホームページなど、区が持っております全ての広報媒体を活用して周知しています。今後も継続的に周知をしてまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"山本委員","kind":"質問","question":"分かりました。現在、そのような情報発信のリストや手法はあるのでしょうか。区のご認識および手法の有無を伺います。今回申込みのあったマンション管理組合に、申込時に住所やメールアドレス等の情報を記載いただくのでしょうか。その後、各種情報を郵送やメールで送れるような情報利用の事前承諾をいただいておりますでしょうか。","respondent":"平原防災課長","answer":"これらの情報をほかの用途に活用する承諾は得てございません。","id":"exchange-070"},{"speaker":"山本委員","kind":"質問・要望","question":"現在の状況について理解いたしました。せっかく申込みをいただいて、マンションの住所やメールアドレスを得ることができているので、今後、情報を送付できるように手当てしてはいかがでしょうか。マンション管理組合に対して、平時の防災対策に関する情報発信を効率的に効果的に実施できるよう、リスト化、ネットワーク化を考えていただきたいと思います。これはご見解を伺います。","respondent":"平原防災課長","answer":"マンション防災を進めるに当たりましては、エレベーター用防災チェアの申請を行っていただいたマンションは非常に関心が高いというふうに考えられるところです。このため、区からの情報発信でありますとか、そのための収集につきまして検討が必要かなというふうに考えてあります。","id":"exchange-071"},{"speaker":"山本委員","kind":"質問","question":"防災の情報発信の仕組みについて伺います。災害発生時、いかに区民の皆様に情報を伝えるかが大きな課題であると感じています。現在の区が考える手法についてお教えください。","respondent":"羽鳥防災体制整備担当課長","answer":"災害時の情報発信についてです。災害時の対応は、平時からの取組の延長にあるべきというふうに考えてあります。","id":"exchange-072"},{"speaker":"山本委員","kind":"質問","question":"理解いたしました。戦略広報課にお聞きしたところ、Ｘが約３万５,０００人、ＬＩＮＥが約５万７,０００人、しなメールが約６,７００人、重複する人もいるでしょう。もっと多くの方々に発信できるツールの必要があると感じていますでしょうか、新たな方策を検討していますでしょうか、他区事例を研究していますでしょうか、お聞かせください。","respondent":"羽鳥防災体制整備担当課長","answer":"委員からご指摘ありましたとおり、各情報発信媒体の登録者数に関しましては、引き続きの課題であるというふうに認識しています。そのほか、例えば防災情報を中心とした情報発信の方法などないか、他区の事例も参考にしながら研究しています。","id":"exchange-073"},{"speaker":"山本委員","kind":"質問・要望","question":"平時の啓発ももちろん大事であると考えます。それらも踏まえると、これまでも他の委員の方々がご要望しておりますが、やはり大田区や渋谷区などで導入されている防災アプリは有効ではないでしょうか。ご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃられましたとおり、他区では、防災アプリや防災ポータルサイトの導入を防災課としても確認しています。このような事例を参考にしながら、新たな情報発信の方法について引き続き検討してまいります。","id":"exchange-074"},{"speaker":"山本委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。なお、アプリの導入だけでなく、これをいかに広く普及させるかが大事です。防災アプリと、そのような効果的な導入方法の検討を要望し、次の質問に進みます。次に、災害時の情報発信の中で、都と区の災害関連情報の連携について伺います。目黒川氾濫注意に関する情報発信と、全般的な都と区の情報発信について、ご見解を伺います。","respondent":"平原防災課長","answer":"ご指摘の目黒川の水位情報、荏原調節地の流入情報につきましても、区のシステムに連携できるものは連携いたしまして、直ちにはできないものにつきましては、例えばリンクを張るなど、区民にとって分かりやすくお示しできるように努めてまいりたいというふうに考えてあります。","id":"exchange-075"},{"speaker":"山本委員","kind":"質問","question":"ぜひ区民目線での情報発信をお願いいたします。次に、大井町駅周辺地区再開発事業について伺います。１０月８日にＪＲ東日本から、大井町駅周辺広町地区再開発のまちづくりについてのプレスリリースがありました。７２時間帯在可能な備蓄を行うとのことでした。事業者との連携、とてもよい取組だと考えます。ＪＲとの協議状況と、３,０００人の帰宅困難者受入れの場所についてお教えください。","respondent":"羽鳥防災体制整備担当課長","answer":"区といたしましては、現在、ＪＲ東日本と３,０００人の帰宅困難者の受入れについて協議を進めているところです。具体的に、避難スペース、備蓄スペースをどこにするのか、そういったところを今、協議を行っているという状況です。","id":"exchange-076"},{"speaker":"山本委員","kind":"質問","question":"分かりました。帰宅困難者の受入れは、今回のスペース確保で十分となるとの認識でしょうか。ご認識と今後の対策の見通しについてお教えください。新庁舎がその機能を果たす場合は、それも併せてお教えください。","respondent":"羽鳥防災体制整備担当課長","answer":"開発により今後増加が見込まれるため、エリア防災計画の見直しを行う中で、今後の対策について引き続き検討していきたいと考えています。新庁舎における帰宅困難者の受入れについては、現在、新庁舎整備課と調整しています。","id":"exchange-077"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。まだまだ不足している現状について理解いたしました。区では、しながわ中央公園を含めた庁舎跡地の活用方法を現在検討しています。ここに大規模な帰宅困難者受入れスペースを確保することが有効であると考えます。ご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"庁舎の跡地など区有施設や民間事業者の協力も得ながら、引き続き、一時滞在施設の確保に努めてまいりたいと考えています。","id":"exchange-078"},{"speaker":"山本委員","kind":"質問・要望","question":"激甚化する災害の備えとして、以前よりその必要性は高まっていると感じます。庁舎跡地へ防災機能を高める多目的アリーナの建設検討を要望いたします。次に、Ｐａｒｋ－ＰＦＩ導入について伺います。これまでもほかの委員からご質問がございまして、いろいろと確認が済みました。私からは１点、区の方針の公募への反映についてお伺いいたします。ご見解をお知らせください。","respondent":"大友公園課長","answer":"公募指針に記載する要件は、できるだけ少ないほうが民間の活力を活用した自由な提案を受けられると考えておりますけれども、区が公園に求めている考えがありますので、一定、区としての考えを公募指針に反映させるべきものと考えています。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問","question":"３６７ページ、防災関係組織経費に関して、避難所運営マニュアルの改訂、キッチンカーとの災害協定について伺います。このほど避難所運営マニュアルについて、各避難所や標準版の改訂が進められたと伺いました。そこで、内容について、どのように地域に示されるのか伺います。改訂によって避難所環境がどのように改善するのか、それぞれお答えください。","respondent":"平原防災課長","answer":"今回は、ご議論いただくという内容ではなくて、そのことは措置してくださいという形で、もう議論は終わったというような段階で、お示しするものは示していくというようなところが今回の変更点でございまして、これまで課題となっていたところを大きく前進させようという意図です。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして同時に、こうした理解を深めれば深めるほど、避難所運営について議論が進めば進むほど、実際にもっと人手が必要だという話をよく伺います。こうした地域の方々の力を集めて発揮させるためにも、この改訂されたマニュアルを示して、人手が必要なことを率直に伝えて、協力もいただきたいということを募っていただいて、そういう場が必要ではないかと思いますけれども、いかがでしょうか。","respondent":"平原防災課長","answer":"地域の力を結集するという意味では、品川区の災害対策基本条例でも、地域の総力を挙げて災害対策を行うとございまして、方向としては、そのとおりかなというふうに思うのですけれども、地域全体を考えたときには、避難所だけではなくて、エリア全体のお話もありますので。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"方向性は同じだと、どういうところで研究していきたいというところですけれども、もう少し突っ込んで伺いますと、実際に発災して震災が起きて、能登では地震と大雨と二重の苦しみがあるもとで、避難所の運営について、いろいろな要望が出るのですけれども、やはり人手が足りないと、その人手も被災者同士ですから、そんなに、急に言われてもという戸惑いの中で。","respondent":"平原防災課長","answer":"このため、例えば午前中にもございましたけれども、地区総合防災訓練への参加者の拡大でありますとか、様々な取組をさせていただいておりまして、災害時の助け合いの考え方自体をまずは広めていく、その中に避難所のお手伝い、そういったところもあるのだと。","id":"exchange-082"},{"speaker":"中塚委員","kind":"提案","question":"ぜひ地域の力が発揮できるように、その仕組みづくりをよろしくお願いしたいと思います。報道では、江戸川区や葛飾区で協定が結ばれたと伺っております。そこでまず、キッチンカーとの災害協定について、２３区の状況を伺いたいと思います。そして、品川区もキッチンカーとの災害協定を結んで、災害時の食事の提供について、避難所の環境改善を進めていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"品川区においても、これまで炊き出しの協定は締結してございましたが、今後、キッチンカーをどういうふうな形で運用できるのかも含めまして、しっかりと研究させていただいて、災害時の温かい食の提供といったものを考えてまいりたいというふうに考えているところです。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つ伺いたいのが、実際の被災地で、なぜこれがうまくいかないのかと。どういう仕組みを作ることが教訓なのかと、区の見解も伺いたいと思います。発災直後は、プッシュ型の支援も必要です。中長期型になれば、１日３回の食事をどうするかということになります。ぜひ積極的にキッチンカーとの災害協定について検討していただくことを改めて求めますけれども、いかがでしょうか。","respondent":"平原防災課長","answer":"ただ、それとは別に、協定自体はまた考えるところもありますので、そちらのところは、何かお話がございましたら、こちらのほうでしっかりと考えていきたいというふうに思ってあります。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"何か話がございましたらとおっしゃいますけれども、今、実際に区役所の前でキッチンカーが始まっているわけですから、ぜひ区からも働きかけていただいて、つまり、実際、震災が起きたときに、何台のキッチンカーが、どこにどのように配置をするのか、ぶっつけ本番ではなく、事前に協定を結んで計画を持って食事の支援を強めていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"こしば委員","kind":"質問・要望","question":"よろしくお願いします。私からは、３３３ページ、駅周辺放置自転車対策事業に関連しまして、西大井駅周辺の放置自転車についてお聞きします。品川区の放置自転車についてお伺いいたします。放置自転車が多発する傾向のある地域、地理的な特徴についてまず教えていただきたいと思います。","respondent":"山下交通安全担当課長","answer":"放置自転車が多発する場所についてのご質問ですけれども、やはり乗降が多い駅、五反田駅ですとか、大井町駅、また武蔵小山駅、こういったところが多く発生しているところでございまして、撤去活動等を強化しています。","id":"exchange-086"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、これまでも駅周辺の放置自転車がまちや歩行者への悪影響をおよぼしていることを地域の方からもお聞きしており、また私自身も強く感じておりました。特に立会道路沿いへ道を渡りました先にあります区営の３階建ての駐輪場があります。品川区では、この放置自転車に対する対策を講じておりますが、西大井駅周辺の放置自転車の対策として取り組まれていることを教えていただけますでしょうか。","respondent":"山下交通安全担当課長","answer":"西大井周辺の放置自転車対策ですけれども、現在は、駐輪場の利便性の向上に向けた整備ですとか、撤去活動、それに加えまして、指導・警告活動を実施しています。","id":"exchange-087"},{"speaker":"こしば委員","kind":"質問","question":"今年９月までに、４５日間撤去の取組を行ったと。これまでに約１５０台の撤去があったことをお聞きしました。それは駅前の正面にありますジェイタワーです。区の放置自転車に対しての取組としまして、近隣のマンションの敷地内に自転車がたくさん放置されてしまっているような場合、品川区として何か対策はあるのでしょうか。マンションと連携した取組、対策についてありましたら、お伺いいたします。","respondent":"山下交通安全担当課長","answer":"以前に比べますと若干減ってきているのかなという認識ではいたのですけれども、まだまだ、そういった放置自転車がありますので、今後も引き続き徹底してまいりたいと考えております。","id":"exchange-088"},{"speaker":"こしば委員","kind":"質問・要望","question":"確かに管理責任者が第一ではありますけれども、ぜひマンションの、管理責任者との間の中で連携を行っていただきたいです。３階建ての駐輪場のそばに、今度新しくレンタルシェアサイクルポートが新設されました。レンタルサイクルが設置されまして、まだ間もないものですが、この設置によりまして、変化だとか、また、気づきがありましたら、ぜひ教えていただければと思います。","respondent":"櫻木地域交通政策課長","answer":"西大井駅の公園のほうに、シェアサイクルポートを最近設置させていただきまして、利用は比較的順調ということで、いつも借り出されているような状況だと認識しております。","id":"exchange-089"},{"speaker":"こしば委員","kind":"確認","question":"稼働率も高めであると推察いたしました。このレンタルシェアサイクルによって、放置自転車が減ったという認識ですでしょうか。その辺り、確認させていただければと思います。","respondent":"山下交通安全担当課長","answer":"先ほど少し申し忘れてしまいましたが、ちょっとした短時間の駐輪、放置自転車の対策としまして、西大井駅で今、２時間以内の短時間の利用であれば、当日利用の方の場所を無料で使えるということを試験的に実施しておりますので。","id":"exchange-090"},{"speaker":"こしば委員","kind":"提案","question":"２時間以内利用料ということで無料の試行実施をされているです。新たな駐輪場の設置について、少し提案を含めて質問させていただきたいのですけれども、今度は西大井の広場の南側、光学通り沿いに広場に入る入口があるのですけれども、そのすぐそばに駐輪場があります。こちらは、およそ何台ぐらい駐輪ができるのか教えていただければと思います。","respondent":"大友公園課長","answer":"西大井広場の南側、光学通りに面したところの駐輪場の台数ですけれども、公園利用者を対象としたものですが、２０台、収納を想定した駐輪場となっています。","id":"exchange-091"},{"speaker":"こしば委員","kind":"質問","question":"パッと見、多分２０台以上はとめられるような感覚があって、私の中では、多分５０台ぐらいとめられるのではないかなと思ったのですが、そこはまた改めてお聞きしたいと思います。平日を含めて、こういった駐輪場の整理は、区のほうでどのように取り組んでおられるのか教えてください。","respondent":"大友公園課長","answer":"台数の補足から説明をさせていただきたいと思います。","id":"exchange-092"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひこの整理に取り組んでいただきたいと思いますし、先ほど少し答弁、最後のほうがお聞きできなかったのですけれども、自転車のスタンドもぜひ設置していただければと思います。やはりそういったことで放置自転車の対策にもなってくると思いますので、その辺りを改めてお考えを教えていただければと思います。","respondent":"大友公園課長","answer":"整列してとめるより台数を増やす２段ラックとかもあるかと思うのですけれども、白線などいろいろな対策も含めまして検討を進めてまいりたいと考えています。","id":"exchange-093"},{"speaker":"こしば委員","kind":"質問・要望","question":"その辺り、ぜひ、西大井の駅前の中で、ここにも西大井広場の南側にも駐輪場があるということを、ぜひ周知していただきたいと思いますし、臨機応変に、公園利用者の方のみというふうに限定はされてきたかもしれませんけれども、その辺りもぜひ幅広く考えていただきまして、放置自転車の対策に取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"確認","question":"私からは、３５７ページのしながわ水族館運営費と、３４７ページのコミュニティバス試行運行実施経費でお願いします。春先、私も見に行きまして、展示の内容を確認してまいりました。それが非常にお客さんにとってはシャッターチャンスになったり、見ていて楽しめるというところだと思うのですけれども、現在の展示の状況、おもちゃみたいなものがなかったので、今どうなっているか教えてください。","respondent":"大友公園課長","answer":"それをランダムに日替わりとか、週替わりで入れ替えて実施しているところになります。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"様々工夫されているようで非常に安心しました。ただ、私が直近に聞いた話だと、ランダムに入れているのですけれども、１個しか入っていなかったりする日があるみたいで、できれば何個かあるほうが、より動きが活発になって、見ている方が楽しめるかなと思うのですけれども、その点は、現状どうなっていますでしょうか。","respondent":"大友公園課長","answer":"私の記憶にあるの話でお答えすると、複数入っているときは、布と何かという形で入れていたと記憶しております。今後、複数の導入等ができないか検討してまいりたいと考えております。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ここから派生して、リニューアルについても質問します。イルカのショーや展示がなくなるということで、予算特別委員会のときにお伺いしたときに、理由として、飼育環境が手狭になっているとか、あと、ほかの水族館もイルカのショーをやるということで希少性が薄れている。様々な団体とか、哺乳類の飼育事情もあるというようなことをお伺いしたのですけれども、そういった認識で間違いないでしょうか。","respondent":"大友公園課長","answer":"イルカの展示とイルカショーの廃止につきましては、今、委員のほうからご説明いただいたところが主な方向性です。そのとおりです。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"まだ文献を、私、調べ切れていないのですけれども、上野動物園のツイッターの投稿によると、江戸時代、野生のカワウソが２３区に生息していたというふうに投稿がありまして、つまり、品川区も例外ではないのかなというふうに思っておりまして、これ、坂本龍馬とも重なりますけれども、動物、カワウソがいたまち品川ということで、品川カワウソということで、関連してイベントができるのではないかなと思って。","respondent":"大友公園課長","answer":"そちらに東京湾にこだわりを持った展示、また、近隣の水族館にはない水中感あふれる美しい展示というところが方向性として示されているところです。現在、この方向性に基づいた検討をしています。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"令和７年ということで、まだまだ時間がかかる。そして、区民からは、荏原ですとか大崎ルートの要望もあるということで、さらにそれもどうなるか、運行されても時間がかかるかなという状況だと思います。具体的には、例えば、少し大きめの乗用車、ハイエースとか、それぐらいのクラスのものを使用してたくさん走らせる、そういったことも検討していただければなと思うのですが、その点、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"ハイエース、いわゆるコミュータータイプも新しい交通モードとして可能性としてはあるのかなと思っていますが、いずれにしろ総合的に考えて検討してまいりたいと考えています。","id":"exchange-099"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ総合的に前向きに考えていただきたいと思います。昨今、やはり民間のバスの本数が減少しているということで、区民の方から苦情といいますか、要望を聞いております。交通難民を増やさないためにも、ぜひ区が主体となって交通整備をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３４９ページ、避難道路機能強化事業、３６５ページ、区営住宅管理費、この２点をお伺いしたいと思います。避難道路機能強化事業、これは広域避難場所、大井競馬場とか、しながわ区民公園に至る滝王子通りを安全な避難道路とするために、現況の幅員７.２ｍから１０ｍに拡幅するという機能強化を図る事業と認識しております。その後どうなっているのか、その辺をお聞きしたいと思います。","respondent":"高梨都市計画課長、川原住宅課長","answer":"現在のところ、優先して整備する路線としては位置づけがされていないところですし、ご存じのとおり、東海道本線をくぐる都市計画道路として技術的な課題も多く残っている部分となっていますが、長期的には。区営住宅、今後の修繕や建て替えの在り方ですが、図書館や保育園、施設が併設しているものですので。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"それぞれご答弁ありがとうございました。あそこは大変に広くとっておりますので、隧道の下、いわゆるＪＲの線路の下のところの拡幅が可能であれば十分にとれるところなので、ＪＲとの協議が整えば、３１号線という考え方はありますけれども、そこだけの避難経路としての改善はできるのではないかと考えるところですが、いかがでしょうか。","respondent":"森道路課長","answer":"そういった部分も含めて、引き続き、どういったところが安全かということは検討していきたいと思います。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３５９ページの私道整備事業について、３６９ページの消防団運営費に関わって、けがをしたときの補償について、３４０ページの河川費と、３５１ページ、都市開発費に関わって、目黒川での気泡発生とリニア中央新幹線について伺います。２.５ｍ以下の私道も、住民の負担なしで私道整備ができるようにしていただきたいと思いますが、いかがでしょうか。その割合を伺います。","respondent":"森建築課長","answer":"幅員が大きいところにつきましては、第三者の方の自動車等も通りますので、傷みが大きいということで１００％助成、２.５ｍを切るところにつきましては１割負担していただくというところで、現在、実施しております。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"９件中２件が１割負担をしているということで、やはりその割合でいくと、２割いかない、１割強というところだと思います。やはりそうした危険な状況が生み出されてしまっているということですので、ぜひこうしたところで２.５ｍ以下の私道でも負担がないように整備できるようにしていただきたいと改めて求めたいと思いますが、いかがでしょうか。そして、この幅の要件をつけた理由を伺いたいと思います。","respondent":"森建築課長","answer":"２３区の中でも、品川区がやっている助成は、そこまで問題がない状況ですので、受益者負担として１割負担していただきたいというふうに考えてあります。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"２３区の中でもいろいろあるという話ですけれども、その中には要件なしで私道整備助成を受けられるところもあります。立っていると、しばらくすれば人が必ず通るというようなところでもありますので、ぜひそうしたところも、ほかの市道も負担なしで整備できるようにしていただきたいと、これは要望しておきたいと思います。次に、消防団について伺います。これはどういうときに利用できる制度なのか伺います。","respondent":"伊藤災害対策担当課長","answer":"例えば、入院をして７日以上でないと支払われないといったようなものになりますので、そこはしっかりと医師の診断を基に、補償があるのかということは、随時、報告を受ける消防署と連携をして進めていきたいと考えております。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"私のところには、補償が事実上使えないという声が届いています。明後日、１２日には全国大会に品川区からも参加するということも、昨日ちょうど見ました。１７分団ともなればもっといると思います。この補償について、近年の利用実績を伺います。安心して活動ができるように、消防団の活動でけがをした際には補償が利用できるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"一方で、こちらは、もともとは１４日入院しないと支払えないような状況でございましたので、ある程度緩和はされたということですけれども、引き続き、消防庁ならびに消防署と連携をしまして、こういったご意見があるということを共有してまいりたいと感じております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"３年トータルでいくと、そうすると、３消防団１２人の方が受けているということかと思います。しかも、それが入院等を伴ってということで、なかなか大きなけがだというふうに思います。ぜひそうした面でも、区としても利用できるようにしていただきたいと思います。なので、先ほど紹介した肉離れですとか腰痛の場合にも、これは対象になるというふうに思うのですが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"障害につきましては、先ほど訓練中のけがも対象とはなりますが、やはり診断面で、今の状況であれば、７日以上の入院が必要だというようなことになっておりますので、そこのことはご了承いただけるとともに、また、この情報については共有をさせていただきたいと存じます。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"私もさらに研究をしていきたいと思いますけれども、もし７日の入院の要件が必ず必要だということであれば、それもぜひ緩和をしていっていただきたいというふうに思います。次に、リニア新幹線について伺います。事実上の河川管理者である区も認識していると聞いていますが、この気泡の発生を確認したのはいつなのか、現在も気泡は発生しているのか伺います。","respondent":"北原河川下水道課長","answer":"８月５日にＪＲ東海より、８月２日から御嶽橋下流付近にて、目黒川の水面に気泡が発生しているという報告を受けまして、区としても把握に努めております。今月７日にも確認をしています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"今月７日にも確認をしているということですので、８月２日から出続けているのかというふうに思います。私も９月１７日に現場を見に行きました。９月２７日の夜にも現場を見たところ、御獄橋の下付近で多く気泡が発生していることを確認しました。この酸欠空気は、人が吸えば数分で死亡に至るという危険なものです。目黒川で発生している気泡の成分調査をすべきだと思いますが、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"ＪＲ東海より、リニアの原因ということではなく、実質的な判断で気泡の成分調査を実施中というふうに聞いておりまして、区としても状況を注視してまいりたいと思います。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＪＲ東海が成分調査をする方向だということで、これ、水面だから発生が分かったわけですけれども、地下室などに酸欠空気がたまっていれば、そこでも被害が出る可能性があります。そうしたことも含めて、しっかり調査をして明らかにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。３５１ページ、五反田駅周辺地区コーディネート業務委託、３４７ページ、地域交通検討経費、そして３５３ページ、公園・児童遊園維持管理費について。初めに、公園・児童遊園維持管理費についてです。以前お話をしましたが、区民公園内のバーベキュー場の喫煙所についてお伺いします。改めて、この件について、どのような認識なのか教えてください。","respondent":"大友公園課長","answer":"開放について、一定の時間、かなりお時間をいただいているところはあるのですけれども、周辺や利用者の方々の意見も聞きながら、検討をさらに進めてまいりたいと考えているところです。","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ検討をよろしくお願いします。五反田駅周辺地区コーディネートでありますが、これは平成２０年ぐらいからずっとやられていると思います。今回の令和５年度のコーディネートについて、どのようなことをやられたのか教えてください。","respondent":"中道都市開発課長","answer":"現在、五反田駅の東口に、準備組合があります。そういったところで、商店街または町会、または、その地域の関係者の方々と、五反田駅の周辺のまちづくりの方向性について意見交換を交わしています。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問","question":"東五反田のほうでやっているということですが、五反田地域は、本当にこの間、大きくまちも変わって、人も変わってきています。そのような中で、五反田駅の周辺にぎわいゾーンまちづくりビジョンが、平成２３年辺りに策定されて、この間、そのビジョンに合わせていろいろなまちづくりを行ってきたと思います。どのような対策を打ってきたのか教えてください。","respondent":"中道都市開発課長","answer":"やはり時代の流れというものがございまして、また違う地区で、五反田で様々なまちづくりの機運が、上がってあります。ですので、今、コーディネートという形で、地域の方々と意見を交わして、こういった周辺のまちづくりをどうしていくかということを、検討しています。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"ということは、ＴＯＣのことについては、区は一切把握をしていなかったということでよろしいのですか。その点を教えてください。","respondent":"中道都市開発課長","answer":"でも、一方で、そこは民間会社の経営判断というところで、区としては、それを中止するというところとか、より進めてほしいとかという、そこの強制力はないところですので、区としては、再開するのであれば、またさらに五反田ににぎわいをもたらしてほしいというところで。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほどお話を聞いたら、東五反田のほうをやっているよということなので、ある意味、そこの大崎からの部分で東五反田のほうをやっているのかなと、だから大崎駅に入っているのかなというふうに思うのだけれども、これだけ今、五反田バレーだったり、いろいろ五反田でも大きな動きがある中で、区として、五反田駅周辺も含めて、五反田のまちをどのように考えているのか、どのような位置づけなのか。","respondent":"中道都市開発課長","answer":"一方で、委員の言われたように、大崎もそうですけれども、五反田のほうにもまちづくりの機運が盛り上がってきたということも、区は認識していますので、やはり地域の機運のもとに、また、予算の見せ方も、また検討していきたいというふうに考えてあります。","id":"exchange-115"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ビジョンができてからもう十数年たっていますので、この間、まちが全然違うわけです。地域交通のところですけれども、時間がないので要望だけ言います。私もずっとコミュニティバスをやってほしいというふうに言ってきたけれども、今、時代がこう変わってきた、いろいろなものが出てきた、これはやはり１つにまとめて、区がどういうふうに地域の交通を考えていくのかということを考えるべきだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３６７ページ、防災訓練経費から入りたいと考えています。それには、きちんと森林環境譲与税を活用しましたという、そういうものを貼っておくとか、一般区民の方々のところに、そういうものがいくようになれば、私はこれが１つの普及啓発になると思っていて、こういうことも考えていただいて、森林環境譲与税を使っていただきたいなと思って、その住宅改修のところで入れ込んでほしいなと考えています。","respondent":"伊藤災害対策担当課長、川原住宅課長、山下交通安全担当課長","answer":"今回、新たなコンテンツを導入しました訓練としまして、５か所での実施を考えてあります。エコの高断熱浴槽であるとか、貯水型の便器、その辺りの水回り等が多いところですので、今後研究をしてまいりたいと思います。あの古い建物の所有者が建設局という話もございましたが、そちらのほうで今後どういうふうにそこを整備していくのかというところも踏まえて。","id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひ駐輪場は企画等で考えていただければと考えていますので、全体を見渡してやっていただければと思います。子どもたちは、やろうと思えば、いろいろ誘ってやれると思いますので、防災訓練はぜひよろしくお願いします。森林環境譲与税は、具体的に提案をしますので、よろしくお願いします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、３６５ページ、空き家対策事業についてと、時間がありましたら、３４７ページのコミュニティバス、地域公共交通会議経費に関してお伺いしたいと思います。それと併せて、いわゆる空き家、先ほど、空き家が全体で５４０件というふうに伺っておりますが、そのうちのいわゆる管理が行き届いていない不適正管理状態にある空き家がどれぐらいあるのかをお聞かせいただきたいと思います。","respondent":"川原住宅課長","answer":"期限までの措置、除却、自らの申請を行わないと次のステップに進むような状態で、現在進行形で動いているところでございまして、もう１つの特定空き家等に関しては、６月の空き家の審議会でもお諮りしていた案件なのですけれども、現在。","id":"exchange-119"},{"speaker":"田中委員","kind":"確認","question":"そういう前提に立って、そこから今後の手続の中で、管理不全空き家等にどれぐらいその対象が入ってくるのかというところが、それは空き家対策の一環としての、また一人一人の地権者と言っていいのかあれですけれども、管理の上で、厳正な審査はあるのでしょうけれども、軽減という視点からいうと、もう一気に対象にしてもよいのだろうというふうな思いがありますが、その点について。","respondent":"川原住宅課長","answer":"そのような措置をしないと、なかなか動いてくださらないといった状況のものを幾つかピックアップしていますので、まずは少しずつ対応を行うことによって、やはり区の職員のマンパワーも必要ですので、そういったところも見ながら検討してまいりたいというふうに考えてあります。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、時間がないのですが、地域公共交通会議に関してです。コミュニティバスに関して地域でアンケートをしている中で、多くの方は、料金を下げてほしいという、あと、新しい停留所をつくってほしいという声があります。なので、本当の意味で、この会議が地域の声を反映した会議体になっているのかというのは、私は大いなる疑問を感じておりますが、僅かですが、ご感想をお聞かせいただきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"大井第三地区の代表としてご意見を聴取させていただきまして、今後もう少し幅広く意見を聞けるような形で考えていきたいと考えています。","id":"exchange-121"},{"speaker":"吉田委員","kind":"質問","question":"私からは、３３３ページの交通安全啓発費か、３３９ページの道路バリアフリー整備費か、どちらかに関係する質問になると思います。それからもう１つが、３４３ページ、治水対策推進助成事業について伺います。最初に、交通安全のほうです。視覚障害者のための音声信号機設置についてです。区として、音響信号機の設置を進める手順をまず伺います。","respondent":"山下交通安全担当課長","answer":"私のほうにも要望は結構来ておりますので、その都度、警察署と話をした上で進めているところですが、基本的には、利用する方と直接警察官が話をして、設置の方向に向けた、利用する時間ですとか、そういったものを検討していきたいというところもありますので、直接。","id":"exchange-122"},{"speaker":"吉田委員","kind":"提案","question":"いつも音響式信号機についてはご意見をいただいているのですけれども、今回いただいたきっかけが、たしか、視覚障害者の移動の自由を確保するためのアプリ導入の提案があって、それを知った知り合いの視覚障害者の方から、アプリ導入も結構だけれども、その前に、点字ブロックや音声式信号を十分整備してほしいというご意見をいただいたので、今日の質問となりました。もう一度確認させてください。","respondent":"山下交通安全担当課長","answer":"ぜひ私のところに言っていただければ、警察署のほうには、私も警察官ですので、積極的にご意見、ご要望は伝えていきたいと考えています。","id":"exchange-123"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。場合によっては、私も同行するかもしれませんが、その節はよろしくお願いいたします。それで、音響式信号機については、警察としても、自分たちの管轄、所管というか、理解しているのですけれども、手話通訳者の手配については、自分たちの問題として認識していないように思える事例があったのですが、手話通訳者の手配についても、同様に考えてよろしいのでしょうか、確認させてください。","respondent":"山下交通安全担当課長","answer":"もしどうしても手配が必要であれば、後日聴取するという形にもなりますが、当日は、ある程度、一定の基礎的なところだけお話を聞いて、後日また手話の方と一緒にお話を深くまで聞いていくというような段取りでやっているというふうに認識しています。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"聴覚障害者の方ですから、「電話して」ということが言えないではないですか。その点について、ぜひしっかり、課長は、今、分かってくださったと思うのですけれども、どういう形で連絡しても、きちんと聴覚障害者の困難さも理解したような対応を、ぜひ警察の中に広めていっていただきたいと思うのですが、いかがでしょうか。","respondent":"山下交通安全担当課長","answer":"貴重なご意見ですので、私も警察署に立ち寄ったときですとか、また、警察署に戻ったときにでも、そういった話はぜひ広めていきたいと考えていますし、私もそういう警察官が育つような環境で、しっかり部下を指導できるような人間になっていきたいと考えています。","id":"exchange-125"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、はっきり言って、電話ですけれども、相当文句を言いました。これは強く要望しておきます。もう１つが、治水対策推進助成事業です。雨水タンク助成事業がここに含まれると伺いました。タンク助成の２０２３年度の実績を伺います。","respondent":"北原河川下水道課長","answer":"令和５年度の実績については、２件になります。","id":"exchange-126"},{"speaker":"吉田委員","kind":"質問・要望","question":"２件ですか。この実績が少ない理由として、チラシの書き方がまずいのではないのかということと、それから、チラシをどこに置いてあるのですかということを伺ってきたと思います。チラシにまた詳しく書くと、今度、情報が多すぎて読まないというご意見は必ず来るし、私もそう思うのです。そういうことは考えられないのでしょうか。ぜひそれは検討していただきたいのですけれども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"ただ、どういった形がよいのかというところもありますので、いただいたご意見も踏まえて、よりよいチラシについても研究をして改善をしていきたいと考えております。","id":"exchange-127"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことと、それから、浸水被害の抑制が一番分かりにくいと思うのです。だから、それを川に流れ込ませないために、雨水は地中に浸透させるような庭の水やりが役に立つのですよという、そういうことを簡単にというか、少し詳細に説明するような形を、もう少し別の形で考えていただきたいと思うのですが、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"エコルとごしで、昨年度から展示を２週間程度やったり、様々な取組をやっておりますので、今後も皆さんに、こういった助成金を使っていただけるように、きちんと広報をやってまいりたいと思っています。","id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"目黒生活者ネットワークの議員に聞いたところ、目黒にも助成制度はあるのだけれども、２００ｌ以上と、大きいから少し使いにくいのです。表現も、私の要望がだんだん浸透してきているようなので、もう一声、ぜひこれが目黒川の合流改善にもつながるのだと、みんなが取り組めば、そういうことにつながるのだということを、もう少し分かりやすく表現をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"若林委員","kind":"確認","question":"実績は３件というふうに事務事業評価シートで確認済みですので、少し項目がたくさんになりますが、この目的、相談者、どのような方が相談を、それから相談を受ける側はどういう、どのような相談内容であったか、また、相談会場、場所はどのようなところでやったか、それから決算状況、最後に、相談の結果の成果、こういった点をまずお聞きいたします。","respondent":"川原住宅課長","answer":"令和５年度の居住支援相談会の内容についてご説明いたします。年間２回実施した中で、実績は３件で少ない形ではあったのですけれども、高齢者の方が２名、障害者の方が１名いらっしゃいました。","id":"exchange-130"},{"speaker":"若林委員","kind":"質問","question":"令和６年度、今年度も同様２回の予算が組まれております。そこで、今、様々、成果も含めてお聞きしましたけれども、昨年度から今年度、実施している中で、今年度は、２回、いつ行われるのかということが１つと、それから、昨年度経験して、何か今年度、これから工夫をしようとしていることがあるのかどうかについてお聞きします。","respondent":"川原住宅課長","answer":"今年度の居住支援相談会の実施の予定です。年内に１回を予定してございまして、あとは翌年、令和７年に１回、２月までにはもう１回実施をしたいというふうに考えているところです。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問","question":"当初予算では、昨年同様の予算の措置といいますか、内容というふうに私は認識をしておりまして、今のような工夫は、大変ありがたい、喜ばしいことだとは思うのですが、一方で、例えば、今のお話だと、当初予算とは違う予算的にも必要なのかなというふうに認識いたしましたので、予算的にきちんと、これから今年度、年２回やられるということなのですが、着実にその工夫を実行する、また、成果を生み出す。","respondent":"川原住宅課長","answer":"この介護事業者は、区内で初となる居住支援法人の申請を都に働きかけてくださっているところですので、これで今まで区内でいなかった初の居住支援法人ということに、年度内に認定が行われれば、来年度さらに居住支援の強化というところで。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"速やかな予算措置を行っていただきたいというふうに要望します。そこで、今年の予算特別委員会で、今年度、予算が組めなかったということについては、もうお話を伺っていますので、そこは蒸し返さないで、今後、予算が組めなかったことについての原因の解消をどのような方策を考えておられるのか、また、来年度に向けて、どのような予算を組み浚渫を行うのか、ここは確認します。","respondent":"北原河川下水道課長","answer":"来年度につきましては、東京都で浚渫を実施するというふうに聞いておりますので、我々のほうも支障物処理と浚渫をやっていくというふうに考えてあります。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"３５１ページの大井町駅周辺地区再開発事業についてお聞きします。２０２６年３月に「まちびらき」があって、いよいよ創業という形になるようです。すばらしいなと思うのです。令和２年には方針という形で策定されているのです。ＪＲが話合いの中に。ですから、途中、変わっているのですよね。ここの中には庁舎の建て替えも入っていますので、その辺をお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"区とＪＲ東日本によって土地区画整理事業を行うことで、駅近くの交通の利便性を生かした部分につきましては、多様なニーズに対応すべく、商業、ホテル、業務、住宅といった多機能な拠点整備を形成して、そこに対して新たなにぎわいを創出していきたいです。","id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"分担とは何ですか。どういう分担になるのでしょうか。このプレス発表を見たときに、「ああ、やられてしまったな」という感じはしているのです。なぜかというと、やはりそれ以上のまちづくり、ＪＲの、民間の力以上のことをやはり品川区は目指すべきではないかと思うのです。そうすると、今までの考えてきたことをもう少し広げていかないと、非常に難しいような状況だと思いますが、その辺はいかがでしょうか。","respondent":"中道都市開発課長","answer":"現在、区としましては、地域の町会、商店街、また、阪急、イトーヨーカドー、ＮＰＯまちづくり大井など、そういった方々と検討会を行ってあります。こういった新たなにぎわいを、既存の市街地にいかに波及させるか。","id":"exchange-135"},{"speaker":"西本委員","kind":"意見","question":"もう少し希望のあるというか、希望はあるのですけれども、もう少し広がりのある、将来、では、どうするのだというところがもう少し欲しいなというふうに感じました。片やＪＲの再開発もあり、そして、いろいろな縛りもあり、では、このにぎわいゾーン、今、いろいろ検討されておりますけれども、どういう方向に持っていこうとするのかをぜひお聞かせください。","respondent":"泉広町事業調整担当課長","answer":"今ございましたように、庁舎の跡地につきましては、昨年度から庁舎跡地等活用検討委員会、公募区民の方々と考えてまいりまして、活用のテーマですとか、活用に当たって重視する視点、そのようなところを導き出されてきたというところになってあります。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"ですから、先ほど言っているように、このＪＲの再開発とどうリンクしていくのですかという話です。にぎわいゾーンでいろいろやっているよということは分かっています。もっと広い意味で進めていかないと、せっかく再開発しているのが、少し違うものになりはしないかということを言っているので、そこのコラボレーションの仕方とか、考え方をお聞かせください。","respondent":"泉広町事業調整担当課長","answer":"したがいまして、跡地の活用につきましても、ＪＲの開発をしっかりと踏まえまして、どういったところが適切かというところを、引き続き段階的に検討してまいりたいと考えています。","id":"exchange-137"},{"speaker":"西本委員","kind":"意見","question":"それで、この中央公園、中小企業センターも含めて、にぎわいゾーンが考えに入っているわけです。よい使い方をされています。防災に関しての備蓄倉庫もあるし、それから、ヘリポートもあるということでは、それらのことをしっかりと継承しながら、含めて考える、当然考えていると思いますけれども、現状を含めて、どういうふうな方向性でにぎわいゾーンを創出していこうとしているのかお聞かせください。","respondent":"泉広町事業調整担当課長","answer":"しながわ中央公園も含めましたにぎわいの創出のご質問です。今ございましたしながわ中央公園、非常に地域の方から親しまれているというところは、区としてもしっかり認識しています。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３６５ページ、空き家等対策事業、３３７ページ、人孔蓋枠等整備工事、時間があれば、３４３ページ、治水対策推進助成事業についてお伺いいたします。最初に、３６５ページ、空き家等対策事業についてお伺いいたします。多少重複するところもあるかもしれませんけれども、質問をします。今のことは理解したのですけれども、空き家の５４０戸のうち、いわゆるごみ屋敷と呼ばれる戸数を教えてください。","respondent":"川原住宅課長","answer":"数として、８月末現在で約６５０戸弱です。不適正管理状態というものは、そのうち１割に満ちておりません。約５９戸、改善も含めて、指導の上、適正管理に至ったものが５９０戸という形です。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問","question":"失礼しました。認識不足で申し訳ございません。いわゆるごみ屋敷と言われるところが、今、５９戸ということでしたね。そこで、例えば、同じ敷地内に４棟あって、１棟がまだご家族が暮らしていて、それも管理不全に値するところ。空き家が３棟あったときに、同じ敷地内に４棟あったときは、カウントとして、どういうカウントをとるのか教えてください。","respondent":"川原住宅課長","answer":"失礼いたしました。２個目にご質問いただきましたものに関しましては、それは、それぞれの１棟ずつのカウントですので、空き家であれば、空き家が３棟、非居住家屋であれば１棟という形で、別でカウントをしています。","id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それはいろいろと自治体によって当然やり方が違うのは私も理解しているのですけれども、やはり私が思っているのが、空き家、所有者が当然いるわけではないですか。そうすると、やはり個人情報が当然あるわけだから、それは区の職員の方がやらなければいけないものなのかなと私はそういうふうに思っているのですけれども、それで間違いないか確認をさせてください。","respondent":"川原住宅課長","answer":"委員のご質疑にありました個人情報に係る部分は区の職員の管理になるかというご質問です。委員のご指摘のとおりです。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。続きまして、３３７ページ、人孔蓋枠等整備工事についてお伺いいたします。これは、人孔蓋、いわゆるマンホールなのですけれども、品川区でデザインマンホールが、現在、区内に８か所あると私は認識しているのですが、まず、その確認と、それと併せて、今、マンホールカードは、道路課が所管なのだけれども、しながわ観光協会でマンホールカードを配布をしているかと思います。","respondent":"森道路課長","answer":"デザインマンホールにつきましては、委員ご指摘のとおり、８種類を設置しておりまして、そのうち２種類をマンホールカードとして配布しています。","id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"確認","question":"８か所の設置場所があるということで、その８か所が、大井町が２か所、八潮団地の近くのところと、ホッケー競技場のところ、あと、武蔵小山、大崎、天王洲、品川橋になっていますけれども、そうすると、品川を巡るには、ほかの場所は、もう多分ないのか、設置場所ができれば、今のところ、マンホールを設置するところがあるのかどうか確認させてください。","respondent":"森道路課長","answer":"今、例を挙げていただきました箇所について設置をしております。具体的に、ここに設置をしようというところはございませんけれども、歩道上にどうしても設置をする必要がありますが、そういったところの適地があれば、積極的に整備をすることも考えていきたいと思います。","id":"exchange-143"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、これは所管が違うのですけれども、これから新庁舎に向けて、いろいろこれをやると思うので、例えば、エントランスとか、マンホールに似たようなものを設置するとか、大井町のこれからに向けて、それも１つのにぎわいの創出にもなると思いますので、ぜひこれは要望とします。よろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。３３３ページ、交通安全啓発費になるでしょうか。交通安全のほうで、区内の交差点の危険箇所について、区民の方からご要望をいただいて、それに対して素早い対応をしていただいています。花海道が併設される、そして学校通学路との関係、その辺りの安全対策を学校との連携をしっかりしていただきたいのですが、いかがでしょうか。ここまでお願いします。","respondent":"山下交通安全担当課長、大友公園課長、森道路課長","answer":"ただ、高齢者ですとか子ども、障害者の方が通る状況があるのであれば、それは所管する警察のほうで判断した上で秒数の調整を行っているところですので。引き続き、防砂効果を保ちながら、観戦がしやすい手法を検討してまいりたいと考えているところです。勝島人道橋の説明会は、９月２６日に行いましたけれども、５３名の方からご参加いただきましてご意見をいただきました。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"このトイレは、何室あって、バリアフリートイレはどれぐらいあるのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレトラックについてのご質問です。こちらは、来年の２月末に納車予定ということで、今、準備を進めているところです。トイレトラックにつきましては、個室のトイレが５部屋ついてあります。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"トヨタ自動車がつくったモバイルトイレです。このようなものが能登で活躍して、小さいお子さん、足の不自由な方、そして車椅子の方がお使いになって大変役に立ったというふうなことを伺いました。今年、豊田市などで１０台、そして来年も４台、１０台と購入がありますが、このようなモバイルトイレ、機動性に富んでおりますので、このようなものを導入するということはいかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"現在は、２２自治体で助けあいジャパンからトイレトラックを導入しているという状況です。そういった災害派遣トイレネットワークを活用して、被災地に派遣、品川が被災したときは受援を受ける、そういった体制を組んでいるところです。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"私からは、３３５ページ、道路維持費、３３７ページ、道路改良費、３７１ページ、貯水槽等維持管理費について順不同で伺います。その上で、区内に１,８００基以上の防火水槽があるというふうなご答弁をされています。区内にある防火水槽ですけれども、これは区が所有するものはどの程度あるのか、区が所有していないとしたら誰が所有しているのか、また、管理は誰がどのように行っているのか伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"防火水槽についてのご質問です。委員おっしゃられたとおり、区内に１,８００基以上の防火水槽が設置しています。品川区といたしまして所有管理しているものは、そのうちの約３００基になってあります。それ以外のものは、消防であったり、民間が所有管理しているという状況です。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"そういった状況で、結構民間が所有されていたり、消防が所有されていたりというところがあるかと思います。２枚ありまして、１枚目のほうは、また次の質問で出てくるところなので、２枚目のほうの防火水槽の標識というものを見ていただきたいのですけれども、これを見ていただいて、水槽がここにあるということが分かるでしょうかというところなのです。この点について、区としてどのようにお考えか伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"このように、ほかにも同じようなものがあるかもしれませんので、地域の方からお声をいただいたときは、消防署としっかり情報共有しながら対応してまいりたいというふうに考えてあります。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"２回も見に行っていただいたということで、感謝申し上げます。今のところ、ゲートが閉まっている点については、どう考えればよいか伺えればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"ゲートが閉まっているですけれど、今回、私有地の中に防火水槽を設置しているという状況ですので、そういったところは、東京消防庁と施設管理者のほうで、今後、どのような対応がいいかということを、また話を詰めていくのかなというふうに思っております。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"私が事務所を構えているエリアでも、この間初めて聞いてびっくりしたのですけれども、１ｍぐらいの距離に、商店街の街路灯と区の街路灯があって、両方点いているというのは、これはもったいないのではないかなというふうに思いまして、この辺り、商店街の街路灯のほうが、せっかくお金をかけて華やかなものをつくっておりますので、例えば。","respondent":"森道路課長","answer":"道路課でも、商店街灯と街路灯が近接してあるというところは幾つかあるというふうに認識しております。経緯はそれぞれの場所であると思うのですけれども、基本的には、後から商店街灯がつくられた。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問・要望","question":"そこは省エネの観点からも検討していただければなというふうに思います。もう１個、道路の関係で、先ほど、委員長の許可を得て写真をアップロードさせていただきました１枚目のほうなのですけれども、時間がないので、最後は要望だけになってしまうかもしれませんが、１枚目の写真、これは区民の方からご提供いただいた写真です。かなり道路に水が溢れている状況を見ていただけるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"私は、３６７ページ、防災対策総合推進費についてお聞きします。先ほどから、今も、お話が出ましたが、トイレトラック。災害時に、このようなトイレトラックのような設備は必要だと思うのですが、いかがでしょうか。小さいお子さんは、仮設トイレでは嫌だ、学校にあるマンホールトイレでは嫌だ、そして、暗い、そこは電気を通せばなるのでしょうが、もうそういう時代ではないのではないでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"やはりトイレの衛生環境が悪化すると、最悪の場合は、災害関連死につながることもありますので、トイレも含めて避難所の生活衛生環境の改善は重要な課題だというふうに認識しています。そういった重要性も含めて、そういった災害用のトイレ、様々区は備蓄しています。","id":"exchange-153"},{"speaker":"須貝委員","kind":"意見","question":"私としては、必要性を訴えているのですが、ただし、利用能力を考えると、１台では１,２００回分ぐらいしかなく、すなわち、１,２００人分しか利用できないというふうにうたわれています。仮に、ある避難所に１,２００人が避難していたとします。これ、１基や２基あってもどうしようもない。そういうことも考えるべきだと思うのですが、その辺について、ご見解をお聞かせください。","respondent":"羽鳥防災体制整備担当課長","answer":"そういったところで、現状、各自治体、導入しているところも、それぞれ１台ずつということになっています。助け合いの輪が今後広がっていく、そういったことが重要なのかなというふうに考えてあります。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、助けられるのですか。そして、品川区だけ集中して２０基でも３０基、いや、５０基でも持ってきてくれるのですか。違うでしょう。こういうことを考えたら、品川区もしっかりそういうことを見据えて、被災民のまた強い要望でもあるこういうトイレトラックのような設備を備えて、なおかつ、１,２００人分、１,２００回分しか使えなかったら、そこでもう使えないのですよ、トイレトラック。困るのです。","respondent":"羽鳥防災体制整備担当課長","answer":"実際に派遣ができるのか、輸送できるのかですけれど、まず、災害時、緊急輸送道路は優先的に道路計画がされます。緊急車両等、あと支援物資の輸送の車両等が通れるように対策はとられるものということで認識しています。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"やはり現実を見て、本当にそのようなことが可能なら、防災対策はそんなに要らないのではないですか。それはぜひ考えてほしいと思います。そうではないでしょう。そういうことを支援することが先ではないですか。私は、閉じ込められて、では、この方たち、体は大丈夫なのですか。それが確実にどこかで止まって、そして人を救出できるということを最優先にやるべきだと思うのですが、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"居住者がお住まいになっているところの安全性の確保といったところですので、まずは、ご自身のマンションがどういったような設備になっているのか、災害時にどういうことになるのか。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"今、管理組合とおっしゃいましたけれども、地震時管制運転装置搭載助成を東京都でしていますよね。そうしたら、こういうことを積極的に教えるのは区ではないのですか。でも、その後は、やはり品川区で、そういう都から国からの、国土交通省の指示があったら、それをやはりきちんと明確に持ち主にまず教える、指導するということが、区としての立場だと思うのですが、いかがですか。","respondent":"平原防災課長","answer":"国や都からの指示というようなところではございません。それぞれの事業という形でやっているものだと思ってありますので、まず、東京都が事業を推進するに当たっては、東京都が積極的にまず周知広報すべきものというふうに考えてあります。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"こうやってエレベーターが、例えば１,０００台、２,０００台止まったら、消防署も、それからエレベーター会社も対応できないのです。どうしようもないです。そこに救援に行くのですか。行く人もいない。そうではないでしょう。それで、こういう助成制度もあります、皆さん、どうぞ使ってください、そうしないと、多くの人が命に関わります、何かあったら大変です。もう一度ご見解をお聞かせください。","respondent":"平原防災課長","answer":"言わば最後の手段というふうに思ってあります。そういう中で、マンション防災全体というもので、エレベーターだけではありません。ほかのものも多々あります。そういったところをしっかりと考えていただくといったところが重要かなというふうに区の立場では考えてあります。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、しっかりやはり普及啓発を図って、こういう安全装置を一刻も早く皆さんにつけていただくように、普及啓発のために、推進、そして指導していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３５３ページ、品川駅南地域周辺まちづくり事業について伺いたいと思います。この品川駅南地域周辺まちづくり事業、いわゆる再開発事業ですけれども、大変広大な範囲での再開発で、反対する住民もいますし、また、この計画を詳しく知らない住民も多くいる中で進んでいます。幾つかまとめて数字を伺いたいと思います。地権者数、土地所有権利者、借地権者、そして計画に関わる世帯数を伺います。","respondent":"大石まちづくり立体化担当課長","answer":"品川浦周辺地区の再開発事業という形で、今ご質問をいただいたところです。現在、地域では、地区を３地区に分けまして準備組合が設立されている状況です。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これだけの住民を巻き込んで進められていく計画になります。広大な範囲ですので、先ほど課長も言いました地区を分けて進められていまして、南街区、北街区、西街区となっていますが、それぞれの事業面積を街区別で教えていただきたい。合わせた総面積も教えてください。準備組合も立ち上がっていますので、準備組合加入者数も教えてください。","respondent":"大石まちづくり立体化担当課長","answer":"今お問合せいただきました事業面積、いわゆる今検討している面積になりますが、まず、品川浦の北側、品川駅寄りの北地区につきましては、約６haとなっています。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に１３.５haということで広範なのですけれども、街区別に開発協力企業も入っております。それぞれ、これも街区別に企業名を伺いたいと思います。それと、総事業費、あと補助金がどれぐらい入るのか、見込みでも想定でもいいので教えていただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"次の総事業費、補助金額というご質問ですが、現在、各準備組合により、まちづくり検討が行われている状況でございまして、まだ事業化されている段階ではございません。このため、総事業費、補助金等も、見込みといえども現時点では未定です。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に今、皆さんもおっしゃっていましたけれども、名立たる大企業がメモが取れないほど群がっているなという状況がすごく分かったと思います。それで、ここに人道橋、今は架かっていないですけれども、これができていることと、あと、この辺の道路の架け替えなどもあるのかなというように見てとれるのですけれども、この新たな人道橋の建設や道路の架け替えがあるのでしょうか。伺います。","respondent":"大石まちづくり立体化担当課長","answer":"都市計画道路の付け替えというか、再編というご質問ですが、現在、検討が進められている地区内には、今、委員おっしゃられたとおり、補助１４９号線と、補助１６２号線という２本の都市計画道路があります。","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この１３.５ha、そして、これだけの今言っていただいた企業が入り、そして道路も架け替えて、人道橋も新設されると、もう莫大な税金、１,０００億円を超えるのではないかと私たちは思っておりますけれども、それだけの事業になります。これが大きな問題だと思っています。準備組合に入っていない権利者に、区から情報を出すべきだと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"準備組合に加入していない方への情報発信の在り方というご質問だと思いますけれども、市街地再開発事業、現在、検討されている情報につきましては、やはり準備組合の情報資産となってございまして、最終的に準備組合が情報を発出するしないかというところは。","id":"exchange-164"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対をしていても地権者なのです。なので、平等に情報は入れるべきだと思います。とにかく情報が欲しい、そして、反対する区民にも寄り添ってほしい、無視しないで、進めないでほしいという声が本当に強く届いておりますので、ぜひ区の事業である品川駅南地域のまちづくり事業の情報を、区から地権者に出すように強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"お願いします。３６７ページの区内一斉防災訓練、３３３ページ、放置自転車対策事業で伺います。一般質問で、一斉防災訓練に関連して、避難所について、避難者受付簿のデジタル化というところで質問させていただきました。放置自転車対策事業のほうですが、放置自転車が減っているというようなお話も先ほど来ありました。","respondent":"平原防災課長、山下交通安全担当課長","answer":"避難所の受付における電子化ですけれども、現在、前回の定例会でご答弁させていただいたとおり、検討をしていくということで考えているところですが、具体的には、現状すぐできるところでは。防犯登録が付いていれば、警察に所有者照会をして、取りに来ない方につきましては通知書を送りまして、それでさらに取りに来られなかった方の自転車については。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"は進めるというところで非常にいいかなと。改めて確認ですが、紙で書かれた方については、どのように入力されていくのかというところと、また、ＳＮＳアプリを活用して登録をされた方については、具体的にどうやって登録されていくのかということについて、検討中ということなので、分かれば教えてください。その確認の方法、登録しましたよという確認の方法をどうするのか教えてください。","respondent":"平原防災課長、山下交通安全担当課長","answer":"単に紙で書く、その手間がなくなったといったところで、行列の縮減効果があるといったところです。被災者台帳に入力する際、現状では、マイナンバーを使わない限りでは、最終的には手入力という形になるというふうに認識しています。自転車駐輪場の利用料金もキャッシュレス化していますので、こちらのほうも今後に向けて検討していく必要はあるのかなと考えているところです。","id":"exchange-167"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３６９ページ、防災体制整備費、そして３３９ページ、橋梁管理費から伺ってまいります。災害時のトイレ問題について、本年３月の予算特別委員会、そして今回の歳入の款で繰り返し質問してまいりましたが、改めて本日も取り上げします。私たちも被災地にボランティアで行きました。誇りを感じます。そこで伺います。災害時のトイレ問題について、品川区はどう考えておられるのか、改めて教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"最悪の場合は、災害関連死につながってまいります。災害時のトイレ問題は非常に重要な課題であるというふうに認識しています。避難者の命や尊厳を守るためにも、災害時のトイレ対策について、品川区といたしましても取り組んでまいりたいというふうに考えてあります。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのときに私も質問させてもらったのですけれども、その際に、加藤篤さんという代表がおっしゃっていたのは、２０１６年の熊本地震の後に実施したアンケート調査では、地震発生後３時間で約４割、６時間で約７割の人がトイレに行きたくなったと。予算特別委員会、そして今回の歳入の款でも伺いました。併せて、実務的な意味でのトイレ対応の責任者の設置をお願いしたいと思いますが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"ただ、組織といたしましては、災害対策本部の物資調達課が対応することになってあります。その中で、しっかりトイレ対応ができるような体制はとってまいりたいというふうに考えてあります。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問","question":"橋梁管理費から青物横丁駅前交差点の歩道橋のバリアフリー化について、伺ってまいります。伺います。これまでの勉強会の実施状況について、まず、勉強会の名称、主催者、そして構成機関、これまでの実施回数と開催時期について教えてください。本件の品川区の管轄部署は、これまで都市計画課であったと思うのですけれども、少し変わったというふうに伺っておりますが、その理由について教えてください。","respondent":"櫻木地域交通政策課長","answer":"所管が変わった理由ですが、これまで都市計画課が担当していました「やさしいまちづくり事業」というものがあります。それが当課に移管されて、開発が絡まない鉄道駅のバリアフリー化については、当課が対応しているものです。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"直近では今年の７月に開かれていると。改めて、特に直近の７月の第３回目の中身、非常に期待をしたいと思うのですけれども、具体的に、どのようなボリュームの報告があり、何が検討されたのか、そして、どのようなことが決まったのか教えてください。","respondent":"櫻木地域交通政策課長","answer":"関係施設などのヒアリングを行い、具体的な中身にしていきたいという意向を示されているところです。勉強会への思いということですが、私も幾度となく現地を確認して、現状のままでは地域の皆様が非常に使いづらい不便な状況にあるという認識は改めて感じております。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご詳細に雰囲気も教えていただきました。１点だけ心配があります。もう少しですからということで。ただ、地域の方に聞いたという話は、私、聞かないものですから、ぜひ、少なくとも複数の選択肢を示していただいた上で、地域の方たち、これは施設の方だけではなくて、町会の方、町会の方が中心になると思いますけれども、そういう方だけではなくて、地域の方の声をしっかり聞いてください。","respondent":"櫻木地域交通政策課長","answer":"委員ご指摘のとおり、個別の施設の意見だけではなくて、地元の意見をまずはしっかりと聞いてほしい、説明してほしいということを区からは申し入れていきたいと考えています。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"確認","question":"私からは、成果報告書の４１ページ、地域交通検討経費と、防災全般より、備蓄、そして防災組織についてお聞きしたいと思います。地域交通検討経費につきましては、事務事業概要で、全体の執行率９２％、効率的に予算が執行されたことは確認いたしました。そうすると、シルバーパスの利用を含めると、約５４％。この数字をまずはどう評価しているのかお聞かせください。","respondent":"櫻木地域交通政策課長","answer":"区といたしましては、そのような状況変化や、福祉的な観点を踏まえつつ、コミュニティバスの継続や収支率について総合的に判断してまいりたいと考えています。","id":"exchange-173"},{"speaker":"まつざわ委員","kind":"質問","question":"このコミュニティバスの試行運行に加えて、ＡＩオンデマンド交通、グリーンスローモビリティ、多様なニーズに対応する新しい交通サービスの導入、これは昨年度の令和５年度から検討していくという部分でありますけれども、これが一体どういう検討がなされているのかお聞きします。ＡＩオンデマンドの交通導入によって、一体品川区にどのような効果が期待できるのか、それを教えてください。","respondent":"櫻木地域交通政策課長","answer":"まだ検討がまとまった段階ではございませんが、まとまり次第、速やかにスケジュール等をお示しできればと考えています。","id":"exchange-174"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要は、ＡＩオンデマンド交通は、コミュニティバス以外のところで考えていくと。そこは分かりました。認識しました。行政とか、いろいろな会社もそうですが、行政や会社、その会社の課題という感覚と、私たちが住んでいる感覚は、絶対にイコールではないので、例えば、そういった先の運行計画を立てる際にも、やはり地域住民は必ず計画の中に入れていただきたいと思いますけれども、ご見解をお聞かせください。","respondent":"櫻木地域交通政策課長","answer":"運行について、地域住民を含めて検討です。ＡＩオンデマンド交通を進める際には、あらかじめ地域の皆様にご説明をするとともに、その際にミーティングポイントの設置等のご要望等も伺えればと考えております。なかなか法規制等で難しいご要望等もあるかと思います。","id":"exchange-175"},{"speaker":"まつざわ委員","kind":"質問","question":"ぜひ地域と一緒に、すばらしいシステムを考えていきたいと思っています。次に、防災の中の備蓄についてお聞きしたいです。先ほどもありました、３日から７日間、１週間は備蓄をするようにしましょうと。これによって備蓄の積み増しが多分起こってくると思うのですが、区における備蓄の状況、今後の計画をお示しください。","respondent":"羽鳥防災体制整備担当課長","answer":"量的拡大の部分に関しまして、不足する部分は、区によるプッシュ型の支援であったり、民間事業者の協力などを得ながら対応してまいりたいというふうに考えてあります。","id":"exchange-176"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"足りない部分は協力して、事業所などでやっていただきたい。それでまた物資の話になりますと、先ほども出ました災害協定について、この災害協定も、結局、結ぶのは品川区だけではないですよね。そうすると、災害協定は結んでいますけれども、品川区だけではないから、すぐに支援につながらない場合も考えられると思うのですが、その辺りの見解をお聞かせください。","respondent":"平原防災課長","answer":"災害協定ですけれども、例えば、複数の自治体と締結しているもの、あるいは、広域自治体である東京都と基礎的自治体である品川区と結んでいるもの、あるいは、協定事業者が被災している場合などが考えられまして、直ちに協力を求めることができない場合もありますが。","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"複数の事業の計画を結んで協定を結ぶ、そういった協定をしっかり結んでいることが分かって安心しております。最後ですが、先日、ＭＸテレビ「激論サミット」を拝見させていただきました。これ、森澤区長が出ていまして、戸越銀座町会、また戸越二丁目の町会の皆様が、地域防災の連携について議論を行っていました。そこで、この新しい共助というものに対する区の考え方を教えていただきたい。","respondent":"平原防災課長","answer":"災害時の共助というものですけれども、災害が発生した後は公助が届きづらいということで、共助の役割が非常に重要だというふうに私ども認識しております。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ難しい、つながりとつながりのないところをつなげるきっかけ、これはぜひ行政でもまずやっていただきたいと考えています。我々も行政に任せっきりすることではなく、やはり一緒にできることは全力で取り組んでいきたいと思います。それを踏まえれば、新しい自助、また新しい共助、新しい公助、これをともに考えていきたいと思います。本日は、長い時間お疲れさまでした。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-179"},{"speaker":"石田（し）委員","kind":"確認","question":"こんな時間なので手短にしますが、１点確認させてください。委員会運営についてです。前回の予算委員会でも問題となりました委員会の成立について、改めて確認させてください。各会派、出席者は半数以上と聞いています。私の認識どおりで間違いがないかを確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6857#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":123078,"voices":412}},{"id":"r06-20241010-5","meetingId":"r06-cm10","date":"2024年10月10日","dateIso":"2024-10-10","committee":"総務委員会","time":"午後 １時１８分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査および予定表２、報告事項を行います。 第８６号議案、令和６年度品川区一般会計補正予算","agenda":"議案審査および予定表２、報告事項を行います。 第８６号議案、令和６年度品川区一般会計補正予算","exchanges":[{"speaker":"西本委員","kind":"質問","question":"時間がないから前倒しというのは分からないではないのですが、順番からいえば、本会議が終わってから設置をするというのが、専決処分でない以上は、そういう流れになるべきではないのかと思うのですが、まず、その１点。それから、事前ポスター、たくさん貼ってありますけれども、それの何が駄目で、何がいいのかというのを教えてください。","respondent":"今井選挙管理委員会事務局長","answer":"ですので、公示日１５日の段階で、いわゆる個人ポスターと言われるような、個人の候補者名を掲載しているもののポスターについては一斉に撤去していただくということを、先ほどの１５日の候補者の事前説明会の中でも、選挙管理委員会としても徹底してまいりたいと考えております。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"事情はよく分かります。これ、事情は分かるにしても、流れは流れなので、よく分かっていらっしゃると思うので、そこはなるべく順序を経てやっていただきたいということを言わせていただきたいと思います。今、２連が貼ってあるし、１連というか、個人のを貼っているのはあると思うのですけれども、それは全部、選挙に入るまでに撤去していただくという認識でよろしいですか。","respondent":"今井選挙管理委員会事務局長","answer":"先ほどのポスターの件ですけれども、今、２連ポスターにつきましては、基本的には公示の後に、候補者の氏名が入っているものにつきましては、ご指摘のとおり、いわゆる掲示板、いわゆる選挙活動に伴う選挙ポスターにつきましては。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"剥がさなくていいと思う。公平性に欠けてしまいますので、ぜひそれはよろしくお願いしたいと思います。なければありがたいのですけれども、結構巧妙にＳＮＳを使う陣営が多いですから、それはやはり公平ではないと思いますので、選挙管理委員会は注意喚起だけですから。取り締まることはできないので、十分その権限は分かっておりますが、ぜひ注意喚起をやっていただきたいと思いますが、いかがでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"取締りは今おっしゃっていただいたように警察という形で、また警察のほうも選挙取締本部が設置されると思いますので、連携して対応していきたいと考えています。","id":"exchange-003"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今回のこの補正予算に関連いたしまして、これまで投票支援カードの件を要望させていただいておりました。そしてまた、チェックシートのチェック項目だけではなくて、そこに該当しない支援もお願いできるように、記述欄を設けてほしいということを要望させていただいておりましたが、その点、改善があるのか、教えていただきたいと思います。","respondent":"今井選挙管理委員会事務局長","answer":"今後も、投票支援カードとともに、今回、投票用紙の枠内に書きやすくする補助具の導入を検討しておりますので、今後も、高齢者の方、障害者の方に使いやすく、または選挙の投票所で投票しやすい環境を整備していきたいと考えています。","id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"賛成ですが、先ほどもお願いしましたが、平等で透明性のある選挙になりますようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/131056?Template=document&Id=6843#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":8930,"voices":28}},{"id":"r06-20241010-10","meetingId":"r06-cm10","date":"2024年10月10日","dateIso":"2024-10-10","committee":"議会運営委員会","time":"午後 ２時２５分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/116834?Template=document&Id=6841#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":881,"voices":8}},{"id":"r06-20241011-4","meetingId":"r06-c-settlement","date":"2024年10月11日","dateIso":"2024-10-11","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件抜き出しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯新妻委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯新妻委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"おはようあります。本日も１日、どうぞよろしくお願いいたします。私からは、４０１ページ、就学時健康診断、３７９ページ、区教員経費、３９９ページ、給食運営費についてお伺いします。就学時健康診断について、こちらの取組についてお知らせください。","respondent":"柏木学務課長","answer":"就学時健診ですが、こちらは１年生になる前に、その子の健康状態を確認するために実施しておるものになります。こちらのほうは学校保健安全法に定められておりまして、教育委員会は実施をしなければいけないものになってあります。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"学校保健安全法の規定により、実施されていると理解をしております。昨年度はいつ頃実施されたのか、また、診断をされた人数等をお伺いいたします。","respondent":"柏木学務課長","answer":"実施につきましては、例年１０月から１１月の上旬にかけて実施をしているものになります。対象者は大体３,０００名となっています。","id":"exchange-002"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。就学時健康診断の中で、歯科健康診査も同じ人数ということでよろしいでしょうか。","respondent":"柏木学務課長","answer":"就学時健診につきましては、その健診の中で、内科、歯科、耳鼻科、眼科の健診を行っておりますので、同じ人数です。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"令和５年度の城南地区の調査では、品川区において、就学時の歯科健康診査の歯科医師の手当は、現在１人当たり１万４,０００円となっております。目黒区は１人１万６,５００円、世田谷区は１万９,０００円、また、大田区では２万８,４００円、こちらにプラスして１人５０円掛ける人数となっておりました。この他区の現状は把握されておりましたでしょうか。","respondent":"柏木学務課長","answer":"他区の状況ですが、教育委員会のほうでも把握はしています。現在の健診の謝礼ですが、大体平成１３年度から今の金額のままとなっています。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問・要望","question":"平成１３年度からと確認が取れました。学校歯科医の先生方にもお話を伺いましたが、以前よりも児童・生徒数が増えておりますし、健診では年齢的にも緊張してしまうお子様等、ふだんの診察よりも様々配慮することが多く、診査の拘束時間も長時間となっているとのことで、現状の健診に見合った報酬を望んでおられます。区のご見解をお伺いします。","respondent":"柏木学務課長","answer":"委員からもございましたが、就学人口の増加、あとコロナ禍以降、就学時健診を生まれ月で分けてやるなどということで、以前よりも健診に関わる時間が延びてあります。そのようなことから、現在、謝礼の改定については検討をしています。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問・要望","question":"就学時健診では、内科医、眼科医、耳鼻科医も健診をしているとのことですので、こちらも見直しが必要であれば、要望といたします。次に、教育経費についてお伺いします。教員不足の原因の１つは、学校現場の多忙化、長時間勤務などの苛酷な労働環境が背景にあります。そこでお伺いします。令和５年度、令和６年度の品川区内の公立小学校、中学校、義務教育学校の教員の配置についてお知らせください。","respondent":"中谷指導課長","answer":"ご指摘いただいた教員不足というところについては、年度初めについては、比較的、ちょうど変わり目というところがありますので、深刻な不足が起こるということはないのですけれども、１０名弱ぐらいというところなのですが、年度途中に産休。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"そこで教員不足の改善として、年度途中の欠員補充、こちらの強化が重要だと考えております。地域の学校にも話を伺いましたが、やはり、ご説明あったとおり、年度途中での産休・育休、また、病欠も非常に多いと聞いております。欠員の補充には大変苦労しているとの声もありますが、区のご見解をお伺いします。","respondent":"中谷指導課長","answer":"ただ、それだけでもなかなか厳しいところがありますので、区としても、ホームページで必要な校種、教科についてご案内を随時させていただいたり、大学のほうには、１６大学に近隣のところでアクセスさせていただきまして。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問","question":"やはり産休・育休、区でも増加しているということで、文教委員会でも話が出たようですが、こちら最短で１か月で免許を出せる臨時免許状制度、このようなものがあるとお伺いしていますけれども、こちらについてお知らせください。","respondent":"中谷指導課長","answer":"臨時免許状ですけれども、例えばその教えなければいけない学校種の免許をその時点で持っていらっしゃらない方においても、その学校で教えることが期待されている教科の専門性が、これまでのご経歴の中で確認することができれば、現在ですと。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問","question":"ぜひこちらの制度を活用して、進めていただければと思います。続いて、品川区の固有教員についてお伺いします。現状の教員数と配置されている学校数を教えてください。","respondent":"中谷指導課長","answer":"申し上げます。教員数については２８名となっており、それぞれの配置校で活躍いただいているというようなところになっております。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問","question":"２８名。教員不足の改善には、やはり区独自採用の拡充、また、品川区のことをよく分かっている固有教員を、各学校に最低で１人でも配置できることが望ましいと考えますが、区のご見解をお伺いいたします。","respondent":"中谷指導課長","answer":"一部の学校で、市民科等の推進に課題が見られる学校も見受けられておりまして、品川区の教育の牽引役がますます必要であると考えており、段階的な増員によって、将来的には各校に配置するなどの検討をしています。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、給食運営費についてお伺いします。森澤区長は、目玉事業の１つとして、令和５年４月から区立学校の給食費無償化に取り組まれました。東京都は、令和６年度、子育て世帯の負担を軽減するため学校給食費の保護者負担軽減を行う区市町村に対して、その費用の２分の１の補助を始めました。こちらの補助金交付の申請をされているとは思いますが、お伺いします。","respondent":"柏木学務課長","answer":"東京都の補助の件ですが、こちらのほう、品川区でも申請をしています。申請した金額につきましては、約６億３,７００万円です。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"先月会派では、第一日野小学校に学校給食の様子を視察に伺い、給食の試食をさせていただきました。大関校長にもお伺いしたところ、夏休み明けの９月には、登校を促す対策として、毎週子どもたちに人気のメニューを出している、不登校の子どもも給食だけは食べて帰るなど、給食は子どもたちの心のよりどころでもあるのではないでしょうか。かく言う私も、品川区の給食に育てていただいた１人です。","respondent":"森澤区長","answer":"子どもの食の支援、非常に重要だと思っています。給食は必ず食べるものでありますので、しっかりとこれからも子どもの食の支援を行ってまいりたいと思っています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"おはようあります。私からは、３８３ページの市民科・各教科充実経費に関連して、防災教育についてお伺いしていきたいと思います。本年度の予算特別委員会では、理事者から、このしながわ防災ジュニアプロジェクトに言及があり、関係課とも連携をしながら、中学生への防災教育の充実に努めていきたいとありましたが、学校現場ではどのようにこの教材を活用されていくのか、お聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在防災課のほうで中学生向けの教材を作成しております。次年度、各校においては、年間避難訓練を年１１回位置づけておりますが、そうした避難訓練の実施に合わせて教材を活用することを想定しています。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ進めていただければと思います。内容も、地震・津波・火災編、風水害編、自助・共助・公助編で分かれて、中学生が主体的に考えて、何ができるのか促す充実した内容だと感じましたが、品川区の防災プロジェクトに関して、所管は防災課ですけれども、教育委員会はどのように関わって連携を取られているのか、お聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在教材の構成のほうに入っておりまして、教育委員会、教育総合支援センターのほうにも情報提供いただきながら、紙面の内容などといったところは、こちらのほうでも確認をさせていただいているところです。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"確認","question":"さらに興味を持てる、充実した内容になれるように、進めていただければと思います。小学生から高校生まで、令和４年からタブレットで閲覧できるようになった防災ノートも充実した内容ですが、このはまっ子のプロジェクトのほうも確認させていただきました。現在品川区内の小中学校で行われているトイレ問題を意識啓発するような取組、訓練、現状をもし把握されていれば教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"能登半島でかなりクローズアップされましたので、そうした事例も踏まえながら、各校での指導の充実に努めてまいりたいと考えております。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"質問","question":"こういった事実を伝えていくことで、子どもたちの認識も変わっていくと思いますし、なかなかセンシティブでクローズアップされなかった課題でありますが、教育として、災害教育として、こういったところをさらに伝えていく必要があると思いますけれども、ここについての認識についてお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ですから、小学生、中学生、発達段階に応じて、そういった効果的な教材の活用ができればとも考えております。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"今防災ノートの件でお伺いしましたけれども、私も防災ノートについては全て目を通していまして、語り継ぎのところやその体験など、そういったところは非常に心に残る、感銘を受けるところがあると思いますが、このトイレ問題についてはなかなか触れられていないというところがあるので、今後この部分について進めていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"今回のトイレトレーラーにつきましても、実物を見るということは非常に大事だと思いますので、機会がありましたら、各学校の授業で、出前授業を進めていければと考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、３７７ページのクラブ・部活動等経費、３７９ページの修学旅行費、３８１ページのいじめ防止対策費、３８７ページの発達障害教育支援員配置、学校地域連携推進経費について伺います。いじめ防止対策について伺います。今年１月から、区長部局においていじめ相談窓口が開設されました。","respondent":"丸谷教育総合支援センター長","answer":"４月から月１回のペースで定例会議を行い、そこでいじめ重大事態の共有であったり、今後どうしていくか、区長部局側で受けた相談の事案についての共有、また、専門部署が立ち上がって、第三者性ということで、求める保護者には非常に有効な窓口となっていると捉えています。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどご答弁の中で、専門部署が立ち上がり、第三者性を求める保護者にはよいとありました。そこで伺います。しかし、最近体制が整ったとのことを伺っております。現在の相談体制と、その運用状況についてお教えいただけますでしょうか。","respondent":"石井コンプライアンス推進担当課長","answer":"これまでは専門職非常勤のいじめ専門相談員の配置であったため、どちらかというと区側の対応について相談を求めるものではございましたけれども、今年８月より、弁護士資格を持つ会計年度任用職員のコンプライアンス支援指導員を配置いたしました。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問","question":"デイケンやいじめＤアンケートは選択型で、周囲の生徒には気づかれずに入力ができ、知らせることができる仕組みのようです。いじめ予防の取組をこのようにデジタルで行うと、簡単にできて、すぐに把握や対策ができ、また瞬時に共有ができる、そして分析もできる、効率的、効果的でとてもよいです。効果についてはいかがでしょうか。お教えください。","respondent":"丸谷教育総合支援センター長","answer":"いじめＤアンケートにおきましては、被害申告をする児童・生徒が思ったよりも多く、全体の２割から３割程度が被害申告をしております。例えば軽くたたかれたなど、そういった自分がやられたということです。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問","question":"件数は多くなりましたが、より把握が進んで初期段階で発見ができ、初期対応につながっているということと理解しました。それぞれとてもよいと考えます。これらのソフトはどこの企業がやっているのでしょうか。どのような経緯でこれを導入に至ったのでしょうか。課題があればお教えください。","respondent":"丸谷教育総合支援センター長","answer":"昨年度、いじめの重大事態が複数生じており、未然防止の取組の強化を検討していたところ、ＮＨＫスペシャルで大阪府吹田市のいじめ予防プログラムは取り上げられておりました。同様の取組を本区にも取り入れたいと考え、プロポーザルを実施、事業者を決定いたしました。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"とてもよいと思います。課題のシステム上の改善は、適正な効果検証を前提に、惜しまず投資していただくことを要望いたします。我が会派の大倉議員が一般質問などでもおっしゃっていましたが、学校Ｗｉ－Ｆｉ環境の改善・向上について、ＰＴＡや保護者の皆様からご要望をいただいておりますので、私からも迅速なご対応を要望し、次の質問に参ります。次に、学校地域連携について伺います。ご意見を伺います。","respondent":"中谷指導課長","answer":"実績につきましては、次回のコーディネーター連絡会で、各校の優良事例の共有を目的とした報告のお時間を設定して行う予定です。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問・要望","question":"共有と横展開、その支援をよろしくお願いいたします。こういった取組をゼロからやることは、誰にでも簡単にできるものではないと考えます。町会・自治会との橋渡しについては、つながりがない学校地域は、地域活動課と連携して進めていただきたいと考えます。これらは要望といたします。現在課題はありますでしょうか、お考えをお聞かせください。","respondent":"中谷指導課長","answer":"コーディネーターにつきましては、全校でそれぞれご尽力いただいております。将来的に、今やっていらっしゃる方の後継ぎとなる人材を輩出できるようにしていくことが課題です。","id":"exchange-023"},{"speaker":"山本委員","kind":"意見","question":"理解いたしました。先日、９月２６日に開催された品川コミュニティ・スクール、学校支援ボランティア養成講座に参加をいたしました。多くのボランティアに意欲的な方がいらっしゃって、ミニワークショップなどを通じ、様々な学びや気づきがありました。このご参加いただいた方々が、将来のコーディネーターの後継者になるのではないかと思います。講座内容、参加者人数、実施後の感想をお聞かせください。","respondent":"中谷指導課長","answer":"学校支援ボランティア養成講座についてですが、地域の方に社会貢献や学校の力になっていただき、子どもたちの成長をサポートしていただくことを目的として、昨年度から企画、実施をしている講座になっております。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"私も参加した皆様にご協力いただくことで、学校と地域の連携が前に進むのではと感じました。次に、発達障害教育支援員について伺います。昨年度の決算特別委員会で介助員等についてご質問させていただきましたが、今年度から新しく発達障害教育支援員が配置となりました。人数を含め、前年の同様制度と比較して状況をお教えください。","respondent":"唐澤特別支援教育担当課長","answer":"委託から派遣としたことで、学校からの直接指示が可能になりました。介助員については、名称を学校生活支援員として、今年度も継続しているところです。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問","question":"先日、ある小学校の学校公開に２日間伺いました。２日目、支援員の方がいらっしゃらなかったのですが、教師の方は立ち歩きや様々な言葉に対して、とても丁寧に対応されていました。しかし、先ほどお聞きした配置は、１クラスに１人ではなく、１校に１人です。個々の学校の状況によるとは思いますが、学校の要求に応えるための支援体制の拡充が必要ではないかと考えますけれども、いかがでしょうか。","respondent":"唐澤特別支援教育担当課長","answer":"学校との連絡体制や研修体制を充実していく中で、支援員の質の向上にも努めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"人材の確保については、別の機会でご説明します。次に、修学旅行費について伺います。地域の祭りに伺った際、ある区民の方から、つらい話、悲しい話を聞きました。周りの生徒もかける言葉がなく、とてもかわいそうで見ていられなかったとのことでした。現在行われている区内中学生の修学旅行に関して、内容、１人当たりの費用および総額、参加率をお教えください。","respondent":"柏木学務課長","answer":"修学旅行のお問合せです。区立学校の修学旅行ですが、９年生で実施し、令和６年度は全校とも２泊３日で奈良、京都に行っております。費用ですが、令和５年度の実績で、１人当たりの費用は平均で約６万５,０００円、全校の総額は約１億１,０００万円と把握しています。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"分かりました。参加の状況についてある学校に問い合わせたところ、ほとんどの生徒が参加をしているとのことでした。子育て家庭の負担軽減のため、給食費、教材費の無償化は進めていただいておりますが、さらに前に進め、修学旅行費の無償化を進めるということはいかがでしょうか。葛飾区が２０２５年度から無償化の予定です。無償化を進めれば、先ほどのような事態はなくなります。お考えをお聞かせください。","respondent":"柏木学務課長","answer":"本来は国が実施するものと考えておりますが、さらなる保護者の負担軽減、無償化については、ご提案の修学旅行も含めまして、今後の予算編成作業等の中で、考え方を整理していきたいと考えています。","id":"exchange-028"},{"speaker":"山本委員","kind":"提案","question":"クラブ・部活動指導員経費に関連し、部活動地域移行について伺います。これまでもご質問していますが、地域の皆様や部活動の保護者の方々からご意見を伺う中で、幾つかご提案がありますので申し上げます。２点目は、部活動指導員に対する研修制度の整備です。当会派の大倉議員からも先日の一般質問等でご要望がありましたが、出欠などの連絡が担当教師や関係者の負担になっていると聞いています。","respondent":"中谷指導課長","answer":"指導者の確保につきましては、民間委託、部活動指導員、どちらの形態であったとしても、品川の地元に根差した方が子どもたちへの指導に関わっていただくことで、持続可能な活動が担保できると考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"３８１ページ、いじめ対策、３８３ページ、学力定着度調査、３９９ページ、学校給食無償化について伺います。義務教育無償化は本来なら国がやるべき仕事ですが、区は、実際に都も動かして、半分ですけれども、補助金も下りるようになりました。改めて伺いたいことは、給食無償化を区立や特別支援学校以外に通う小・中学生へも拡大するときではないかと思いますけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"教育委員会といたしましては、学校に係る経費につきましては、学校設置者が検討するものと考えておりまして、品川区が設置者ではない学校については、現時点では拡大は考えてございません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"と言いながら、特別支援学校には広げているわけですから。紹介しましたけれども、朝鮮学校はもともと給食費には補助がなく、給食はほぼオモニ給食という名前で、自助、共助で提供している状況だと伺いました。給食無償化の対象にしてほしいと切に訴えられました。せめて、この支援の必要性が高い朝鮮学校をはじめ、各種学校には急いで給食費無償化の対象を広げるべきではないでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"各種学校への給食費の拡大ですが、まず繰り返しになりますけれども、学校に係る経費については学校設置者が検討するものと考えています。決して朝鮮学校等を差別しているものではございません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"先ほど言ったのですけれども、やっているではないですか、特別支援学校には。設置者ではないのにやっているわけです。だから、何というか、朝鮮学校に出さない理由を言うことは分かるのですけれども、全くもう質問に答えていないということで困ってしまうのですが、もう一度お願いします。","respondent":"柏木学務課長","answer":"そして特別支援学校につきましては、学校に補助をしているわけではございません。あくまでも区の就学相談等で、区の学校で就学が困難なことから特別支援学校に通っていると、そのような経緯がございまして、そのようなお子さんの家庭に補助をしているというものになります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"今まで言った答弁しか言わないということは、本当になあという感じですけれども、答えてほしいのです、私は。聞いたことには。でもちょっと時間がないので次に行きます。昨年度は１４件と、７月の文教委員会で報告がありました。品川区で初めて認定されたいじめ重大事態は、令和２年、２０２０年度だったかと思いますけれども、令和２年度、令和３年度、令和４年度のいじめ重大事態の件数も教えてください。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の認定の年度についてのお問合せです。令和４年度の扱いで３件ということで、いじめ自体は令和２年に起こっているものですけれども、認定時期としては令和４年ということで、令和４年に３件という形でホームページでも公表しています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"同種の事態の再発防止を講じることというものを目的にしています。ちょっと伺いたいのですけれども、当事者、保護者の意向は最優先されるべきものですが、これでは、品川区の教育のどこに課題があるのか、議会は議論を深めることができません。そうでないと品川区の教育はよくなりません、いじめを防ぐことはできませんと思うのですけれども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"こちら、被害に遭われた児童・生徒、保護者のお気持ちに最大限尊重した形での判断ですので、ご了承いただければと思います。ガイドラインに沿って可能な限り公表するということは我々も考えておりまして、保護者等にご了承いただければ公表する考えではあります。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に学力テストについて伺いますけれども、あるベテランの教師の方に学力定着度調査についてお話を伺いました。やらされ感があってとても負担だと。私もそのほうがいいのではないかと思うのですが、ちょっと伺いますけれども、現場ではこのように、もう必要もないし負担だと捉えられているこの学力定着度調査、３,８９４万円、これもうやめるべきなのではないでしょうか。どうでしょうか。","respondent":"中谷指導課長","answer":"教育委員会としましても、教科の目標が達成できているかどうかということを定点で見させていただきまして、こういったものを施策に活かしていきたいと思っていますし、各学校につきましては、やはり自分の学校の課題と解決策を明確にするということが非常に大事ですので。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった現場のこともありますし、あと学校と子どもと教師を点数の獲得競争で輪切りにして競わせるという、このような重大問題もありますので、ぜひ中止していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。私からは、３８９ページ、図書館運営費に関連して、また３８３ページ、プログラミング学習、３７２ページ、教育費全般で、関連してＡＩシンギュラリティーと教育について質問をします。図書館のほうなのですけれども、品川区立図書館というホームページを見まして、そこで品川区地域資料のページというものがあります。","respondent":"河内品川図書館長","answer":"リンクにつきまして、大変失礼いたしました。リンクをいたしましたホームページの閉鎖などが考えられる状況です。図書館本文も、全体も含めまして、すぐに確認、対応いたします。貴重なご指摘ありがとうございました。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ対応していただきたいと思います。ということは、この品川人物伝というページはもう存在しないというということなのでしょうか。その辺り教えてください。","respondent":"河内品川図書館長","answer":"ちょっと所管が違う部署のホームページですが、現在は閉鎖してないというように認識しています。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"ちょっと所管が違うということなのですけれども、ぜひ品川人物伝というページをこれからもう１回つくり直すのかどうかはさておき、ぜひこの品川ゆかりの人物というものは、やはり品川区民の方が、自分の住んでいる品川区への愛着、関心、それこそ都市ブランディングにつながるものだと思いますので、この品川ゆかりの人物という、その人物というところに焦点を当てて、ぜひ取り上げて、品川区としてのＰＲ。","respondent":"河内品川図書館長","answer":"こういったものを併せまして、地域の皆様にきちんとお伝えすることによりまして、地域の愛着度を深めるとともに、あわせまして、ホームページの中では、ここに紹介している資料につきましては、所蔵資料の一部ですというご紹介の下、来館など、ご利用などの促進にもつなげ。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。続いてプログラミング学習に移りますけれども、様々、今現在品川区の学校ではプログラミング学習をやっておられるかと思いますが、その成果と、また課題などありますでしょうか。その辺りお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"現行の学習指導要領で定められているプログラミング学習についてです。現在学習指導要領に例示されている５年生算数の図形や、６年生理科の電気の性質の単元をはじめ、市民科でもプログラミング教育を行っているところです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"それと、先ほどゆきた委員からもご質問ありましたけれども、防災の教育ということで、学校現場では防災の教育もやられているかと思います。もちろんそのゲームで、まず取っかかりとして楽しみながらやっていただく、そして本当にリアルな訓練で、そうした知識を活かして体験していただくということが、これも１つ、今後重要になってくるかなと思っているのですけれども、その辺りいかがお考えでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"防災教育の１つとしてマインクラフト等を活用するといったことですけれども、現在様々な教材が出されているかと思います。子どもたちの実態に応じて、有効な教材を活用できればと考えております。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、今の当たり前はそうではなくなっていく、そして指数関数的に技術の伸びは起きてきますので、今までの１０年とこれからの１０年、かなり違ってくるかと思います。一方、例えばプレシンギュラリティーですと、５年後などになってしまうのですけれども、現在中学１年生のお子さんがこれから社会に出ていくときどうなっていくのか、このＡＩの教育への影響、どのようにお考えなのか。","respondent":"中谷指導課長","answer":"２０３０年に予測されている予測困難で不確実、複雑で曖昧なＶＵＣＡな時代と言われています。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"予測困難な時代ですけれども、教育もそれに合わせて、ぜひ取り組んでいっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"せらく委員","kind":"質問","question":"３８７ページ、不登校児童・生徒支援事業、学校地域連携推進経費、３８１ページ、教職員支援経費から質問をします。先ほどコミュニティ・スクールですてきなエピソードをお話しいただいた後で恐縮なのですけれども、コミュニティ・スクール、学校全体として令和５年度は何回ほど授業をやられたかお聞きします。新しいテーマは、令和５年度に何テーマほど取り入れたか教えてください。","respondent":"中谷指導課長","answer":"というのも、先ほど申し上げたとおり、ボランティアの担い手の方が非常に多く輩出できているというところがありますので、こういった力を活用しながら、引き続きやってまいりたいと考えています。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。こちらもコミュニティ・スクールで実施したというように聞いているのですけれども、こちらは具体的な数字、何校で何回というところは教えていただけますでしょうか。それはいつ頃、何年前ぐらいに何年生で行われていたか、お分かりであれば教えてください。","respondent":"丸谷教育総合支援センター長","answer":"ライフジャケットの体験活動ですけれども、コロナ以前に複数の学校で実施したということは把握しているのですが、具体的な学校名、学校数がこちらでお調べできなくて、ただ、過去３年を遡ってみますと、令和４年度に小学校１校で実施しているということが分かりました。","id":"exchange-045"},{"speaker":"せらく委員","kind":"質問・要望","question":"コロナ以前に行われていたことと、令和４年、小学校６年生で行われていたということでした。品川区の子どもたちが安全にアクティビティーを楽しめる知識の普及をぜひお願いしたいと思うのですけれども、今後いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今後の見通しについてですけれども、次年度以降、こうしたライフジャケットの体験を取り入れてみたいという学校も複数出てきておりまして、外部講師との連携ということで、学校地域コーディネーターの活躍も見込めるかなというように捉えております。","id":"exchange-046"},{"speaker":"せらく委員","kind":"質問","question":"ぜひよろしくお願いいたします。次に、不登校児童・生徒支援についての質問に移ります。令和５年度の状況をお知らせください。そのうち、児童センターで過ごしている人数を把握していますでしょうか。もしいらっしゃいましたら、児童センターで過ごす不登校の子どもたちにはどのようなフォローやサポートをしているか伺います。","respondent":"丸谷教育総合支援センター長","answer":"具体的な支援についてですけれども、１つは児童センター、居場所というところでご利用いただいているというように把握をしていますが、学校と家庭と児童センターが連携をすることで、子どもの安全な居場所ということの確保に努めているところです。","id":"exchange-047"},{"speaker":"せらく委員","kind":"確認","question":"分かりました。令和６年度の現在の状況を教えてくださいまして、ありがとうあります。こちらメディアで見たのですけれども、北区では、私立に通う子どもも含めて、不登校の児童・生徒を児童センターの一角で受入れを開設したということを確認いたしました。校外別室という位置づけだそうです。今年度の品川区の支援の拡大についてのご所感と、児童センターで支援を始めた北区の取組についてご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"北区の取組につきましては、児童センターということでまた所管が変わってしまうのですけれども、こうした取組も不登校支援の１つだというように捉えております。","id":"exchange-048"},{"speaker":"せらく委員","kind":"確認","question":"今年度の支援について効果を感じているというようなことでした。次の質問に移ります。教職員支援経費については、教員の働き方改革に品川区は取り組んでいると思うのですけれども、こちらは勤務時間外の電話委託をしているというように確認しました。勤務時間外の電話対応はどのくらいありましたでしょうか。お知らせください。","respondent":"中谷指導課長","answer":"回数に関しては、かなり、各学校によっても違うところあるかと思いますが、基本的には毎日使われているというところになります。","id":"exchange-049"},{"speaker":"せらく委員","kind":"提案","question":"毎日使われているということでした。教職員の負担軽減についてもしっかり考えてまいりたいと思っておりまして、ちょっとこの後テレワークの取組状況をお聞きしたいなと思ったのですけれども、まだ具体的な提案も私もないところですので、本日は取り組みたいという思いをお伝えさせていただきまして、終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３７７ページ、クラブ・部活動等経費、３８１ページ、人権尊重教育推進経費、いじめ防止対策費、３８３ページ、ルネサンス推進事業、３８７ページ特別支援教育費、幼稚園運営費についてお伺いいたします。品川区においても、これらの課題を早急に対応していただきたいと要望いたしますが、区教育委員会の検討状況をお伺いいたします。小・中学校における現状と課題を確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"スクールソーシャルワーカーについてですけれども、現在、学校支援チームＨＥＡＲＴＳの中で勤務をしており、学校への活用周知のほか、人材の拡充、ＳＳＷの資質向上のための研修の実施等に努めております。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひよろしくお願いをいたします。２点目なのですけれども、いじめ防止対策費についてお伺いいたします。総務費の質問の続きなのですけれども、総務課と連携しながら実際に起きてしまったいじめの事例等から、情報モラル教育の強化へとつなげていただきたいのですが、いじめの根本解決について区教育委員会側のご見解をお聞かせください。さらに情報モラル教育の現状をご説明ください。","respondent":"丸谷教育総合支援センター長","answer":"各学校では、ＧＩＧＡワークブックとうきょうを活用したり、外部講師を呼んだセーフティ教室を実施して、情報モラル教育の充実に努めております。","id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目にクラブ・部活動等経費、特別支援教育費についてお伺いいたします。総務の続きです。先ほどほかの委員からも質問がありましたが、研修についてです。外部指導員の方々にも、寂しさや孤独を抱える生徒たちの現状を理解していただき、承認欲求を満たしたい気持ち、本音が伝えられないなどの子どもたちを受け止めていただきたいと思っていますが、区教育委員会のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会では、例年年度当初に部活動指導者研修を実施し、指導技術のみならず、児童・生徒への励まし、承認等の必要性などについても学んでおります。民間委託事業者も含めて、こうした研修を行っているところです。","id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がなくなってしまいましたが、子どもたちに関わる様々な方々に対して、先生方と同じ研修を受講していただくことは難しいかと思うのですけれども、職務内容に合わせて研修をさらに充実させていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"３８７ページ、不登校児童・生徒支援事業、３８８ページ、図書館費から読書計画について伺います。令和５年度の不登校児童・生徒数は、先ほどせらく委員の質問で伺いました。そのうち区内施設に通っていない、ほかの支援機関にもつながっておらず、家から出ることが難しい子どもの数を区は把握しておられるでしょうか。私は結構いらっしゃるのではないかと考えています。お伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールやフリースクール等の外部機関につながっていない児童・生徒数、昨年度ですけれども、小学生で８５人、中学生で１３０人おりました。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問","question":"中学生で約３割、小学生で約４.４割がつながっていないことになります。そこで、今年度から始まったものでありますが、都の進めるメタバースの現状と参加人数、他区の導入状況を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"メタバース空間を活用した支援事業ですけれども、９月末現在で５０名の登録があります。こちら東京都のバーチャルラーニングプラットフォームを活用しておりまして、今年度、品川区も含めて２８自治体で導入しているというように把握しています。","id":"exchange-056"},{"speaker":"西村委員","kind":"質問","question":"私は度々このテーマを取り上げさせていただいているのですが、家にとどまる子にも居場所をというものが私の本当に強い思いであります。このメタバースの中で、どのような授業が繰り広げられているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"こちらは３Ｄ空間を用いまして、そこで児童・生徒同士の交流や、支援員との交流ができるような仕組みになってあります。オンラインスクールを実施しておりまして、週に３日程度、そうした学習活動も行っているところです。","id":"exchange-057"},{"speaker":"西村委員","kind":"質問","question":"参加人数がなかなか難しいということで、いろいろとご努力いただいているのですが、子どもたちが入りたいと思えるような空間になっているのかな、どうかなと思っておりました。１点伺いたいのですが、そのメタバースという居場所は都がつくっておりますけれども、中に入れば、そういったオンラインスクールや品川区独自の取組がある程度できるという認識でよろしいのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"バーチャル空間にログインするところに１つハードルがあるのではないかというような認識でおります。１学期の間に３名程度、９月に入ってから５名程度利用していただいているところなのですけれども、東京都の空間ではありますが、中では区独自の取組ができます。","id":"exchange-058"},{"speaker":"西村委員","kind":"質問・要望","question":"もうぜひ、どんどん子どもたちが入りたいと思えるようなゲーム大会など、入り口を広げてあげてほしいなと思います。この戸田市が２年前から始めるオンライン学習は、民間のＮＰＯ団体に委託をしまして、グループワークを中心に子どもたちが元気よく発表する声が行き交っていると伺っておりました。そこで１点要望させていただきたいのですが、このオンラインの中で教育相談ができないかなと考えています。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒がオンライン上で相談できるような、このバーチャル空間で相談できるような仕組みということで、マイスクールにいる心理士やＨＥＡＲＴＳの心理士等もログインすることが可能ですので、支援の充実につなげていきたいと考えております。","id":"exchange-059"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひお願いします。要望ばかりで申し訳ありませんが、もう１点、アクションプランを策定している大田区の学びの多様化学校、不登校特例校に視察に伺いました。この不登校生徒・児童への取組に際しまして、行動計画、また不登校対策アクションプランを今後策定する予定はあるかを伺います。","respondent":"丸谷教育総合支援センター長","answer":"現在、品川区の教育振興基本計画を策定しています。そうした基本計画に基づきまして、不登校支援の計画についても進めていきたいと考えております。","id":"exchange-060"},{"speaker":"西村委員","kind":"質問・要望","question":"教育ビジョンからは大変区の熱い思いも感じ取っております。ぜひこの不登校支援の強化は必須であると思いますので、早期にお願いをしたいと思います。次に、子ども読書計画ですけれども、品川区子ども読書活動推進計画の進捗と主な取組、その中で目玉といいますか、新たな特色があればお聞かせをいただきたいと思います。","respondent":"河内品川図書館長","answer":"こういったものを受けまして、誰にでも、誰でもという点が、特に重要と、特色と考えているところです。","id":"exchange-061"},{"speaker":"西村委員","kind":"意見","question":"集団学習をするお子さんも見かけられる中、図書館はどうしても息苦しいと子どもたちの声が聞かれています。例えば児童センターにティーンズ館があるように、図書館のティーンズ館やティーンズコーナーの強化をお願いしたいと思います。１日勉学に励む生徒が軽食を取れるようなスペースなどもいいなと考えていますが、区のお考えをお聞かせください。","respondent":"河内品川図書館長","answer":"その中で学生にも非常に図書館を利用していただきたいというところはあるのですが、やはり学生、２人以上の方でご利用の方も多く、やはりそういった静寂度の認識のレベル差も感じているところです。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３７７ページ、プール指導員経費、３８１ページ、学級風土調査、この２点からお伺いしたいと思います。２項目一括で質問します。プール指導員経費に関連して、学校プールの管理についてお聞きしたいと思います。昨年川崎市のほうで、学校で教員がプールの操作を誤って、３日間水を出しっ放しにしてしまったという、こうした事案がありました。","respondent":"柏木学務課長、中谷指導課長","answer":"教育委員会といたしましても、学校のプールの管理については課題と捉えておりますので、今後検討をしていきたいと考えています。それはやはり先輩が大変多くて、後輩が少ないというような組織であったと思います。今はその逆の環境というところにおいては、上司が若手教員にケア的な視点を持って声をかけていくというようなことが必要となる時代かなと考えています。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"プールの管理については、民間事業者も活用するといったことが通知をされているということですので、そうしますと、民間事業者を活用してという体制を考えていらっしゃるのか、それとも学校で管理をするという現状をそのままするとして、国で示されているというか、事例として言われているものが、民間事業者に委託ということと、あと自動で給水を止めるためのシステムの導入。","respondent":"柏木学務課長、中谷指導課長","answer":"民間委託の考え方や自動で水を止めるなどという、どちらにするとか、ほかの方法にするかはまだ決まっていないところです。自動に水を止める装置につきましては、まだ全校ではございませんが、順次各校に導入をしています。こういったところで、教員側としては、校長先生から示された学校経営方針に基づいて、自身の役割は何か、自分が何をやっていきたいか、こういったことを積極的に考え、そして校長先生に直接言える場となっています。","id":"exchange-064"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は、３８７ページ、教科書採択事務についてお伺いいたします。さて、今年は４年に一度の中学校教科書の採択の年であり、今年３月２２日に文部科学省の検定を通過した教科書が、区内の２か所でも展示されました。自分の子どもたちはどのような教科書で学ぶのだろうと関心を持った方々が足を運ばれたと思います。","respondent":"丸谷教育総合支援センター長","answer":"例えば、多くの教科書にＳＤＧｓの目標の記載があり、目的を持って学ぶことができそうだと思ったですとか、生徒の意欲や先生たちの教えやすさの負担を考えてよりよいものを選んでくださいですとか、また、会場に関することで、展示会場表示が１階にしかなく。","id":"exchange-065"},{"speaker":"おぎの委員","kind":"意見","question":"非常に多くの方が関心を寄せているなと思いました。内容については公開を目的にしていないということで、こちらのほうは了承いたしました。一方で、教育委員会のほうでは、調査研究会の調査研究結果を基に、調査検討委員会を経て、教育委員会での採択が行われたと思いますが、今年の調査検討委員会と採択に関する教育委員会の開催期間と会議の回数をそれぞれお答えください。","respondent":"丸谷教育総合支援センター長","answer":"失礼いたしました。調査検討委員会は、第１回が５月３０日に開催されまして、全部で６回、７月２２日の第６回までございました。それに併せて調査研究会も開いておりますけれども、第１回、５月３０日を行いまして、最終は７月１２日までに調査研究を終わらせております。","id":"exchange-066"},{"speaker":"おぎの委員","kind":"意見","question":"回数を重ねてしっかりと審議されたことだと思います。ただ、日程を考えますと、先ほどのアンケートによる区民からの意見を取り入れることができないなと思いますが、区民からの意見はどの程度反映されているのかお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示の、まず目的ですが、保護者等、広く都民に教科書を公開することでございまして、採択に直接活かす目的とはなっておりません。採択権者の判断と責任について文部科学省からも通知があり、教育委員が責任を持って採択事務を行っているところです。","id":"exchange-067"},{"speaker":"おぎの委員","kind":"質問","question":"このアンケートを設置した意味があまり反映されないのだとなりますと、この箱の意味自体何だったのかなと思います。教科書を見て熱心に、一生懸命意見を書かれた方もいらっしゃると思いますが、そういった方々の思いや費やした時間が無駄になるような形だけのアンケートでしたら、設置する意味がないと思いますけれども、このアンケートの発行については、どう思いますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"いただいた意見につきましては、採択事務が終わりました９月に入ってから、教育委員会会議の中で意見の共有をしています。アンケートの趣旨、目的につきまして、区民の方に分かりやすいような表示に次回以降気をつけていきたいと考えております。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"確認","question":"今回は日本文教出版が採択されましたが、教育委員会のホームページで発表されています主な採択理由は、各ページの下の欄外に問いが掲載されており、生徒が今何を学習しているのかを確認できる、見開きページで年表と地図が掲載されており生徒が理解しやすい、年表が各ページの右に掲載されており今どの時代を学習しているのか把握できると、教科書の構造やレイアウトが採択の主な理由になっており。","respondent":"丸谷教育総合支援センター長","answer":"社会科の歴史的分野につきましては、委員にご紹介いただいた３点記載していますけれども、審議の中では内容についても触れられておりまして、例えば子どもたちが学習の課題、問題について向き合うことができるなど、そういった内容の審議というものもしっかりとされて。","id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"こちら、今日のこの審議の基となります調査研究会の調査項目について、最後にお伺いいたします。調査研究会は調査項目にのっとって調査研究結果をまとめていると思いますが、この調査項目自体はどのように決められているのでしょうか。これは毎回変わるのでしょうか。紙幣にのっとって載っている人物は国の顔です。調査項目自体も時代背景に合わせて変えていくべきではと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学習指導要領が変わるときにこうした基準についても見直して、変更しているものです。紙幣に載っている３人についてですけれども、それ以外のことで判断して採択しています。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区の現状として、教職員の病気で休職される方の数、令和元年１８人から令和５年では３６人と、年々増加していると議事録で確認をさせていただきました。そのため、本日は教職員の負担軽減を求めた趣旨の質疑となります。その点から２点質問をします。メンタルサポートの充実の観点から、同会派吉田ゆみこ議員の一般質問では、相談窓口の拡充、また周知強化の要望がありました。","respondent":"中谷指導課長","answer":"スクール・サポート・スタッフは全校配置、エデュケーションアシスタントについては、副担任相当で小学校の低学年や３年生についていただく役割ですが、今年度からスタートした都の補助事業となっておりまして、試行実施として２校配置をしております。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この点についていかがでしょうかということが１点です。エデュケーションアシスタント、２校から開始をしてくださっているということで、現場の方に意見をお伺いしました。内容を読ませていただきます。学年会、特別支援教育部会にも参加をしていて、共に教育活動をしていて大変ありがたい事業、全ての学校にぜひ配置をしてほしいというようなご要望です。","respondent":"中谷指導課長","answer":"そのようなことも検討していきたいと考えています。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひこの内容については、都の予算のほかにも、区でも独自に足りない、その２学年分だったり、ほかの学年へも拡充していただけるように、こちらについては重ねての要望とさせていただきまして、次の質問へと移行します。次は図書館運営費についてです。品川区アンケート、不読率等調べていただいておりますので、こちらの結果について簡潔にお答えください。","respondent":"河内品川図書館長","answer":"本年度７月に調査した結果ですが、５年生、８年生を対象としております。５年生が１０.０％、８年生が３１.２％です。ちなみに不読率ですが、定義といたしましては、調査直近１か月の間に全く本を読んでいない割合です。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"確認","question":"このティーンズ世代への取組というところがすごく重要になってくるのだなと、先ほど西村委員の質疑の中からも確認をさせていただきました。そのようなことを考えていくと、この静かにするものが図書館だという考えも、少し改めて考え直す必要があるのかなと思いますが、その点についていかがでしょうか。","respondent":"河内品川図書館長","answer":"こういった意識があまりにも定着し過ぎた結果というように認識はしておりますが、一方で、こういったところは住民の意識の型、それから構造、つくり込みなどによりまして、対応できるのではないかと考えているところです。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"意見","question":"デジタルが日常の中に非常に現在浸透しております。図書という時間について、さらに拡大できるようにお願いしたいと思いますが、そのデジタルの点についてもお考えをお聞かせください。","respondent":"河内品川図書館長","answer":"デジタルの活用です。主にまずは大きな点といたしますと、障害をお持ちの方への対応力はデジタルが有用というところがありますが、一方で、先ほど言いましたティーンズの方、デジタルの進展がますます加速している状況です。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私、すごく本が好きなので、あとカフェも好きなので、カフェかける図書というようなところができると理想だなと考えています。様々課題もあると思うので、適宜策定委員会等も資料を毎回拝見していますが、その中でもぜひ検討を進めていただきたいと要望します。こちらについては、学びの多様化学校の設置について、まず区としてどのようなお考えがあるのかというところを率直に１点お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"本区においてはまだ設置はありませんけれども、国の動向や他区の状況を踏まえながら、検討というか、必要性について考えていきたいと考えております。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問・要望","question":"文部科学省の手引というところが改訂されていたので、確認をさせていただきました。こちらは要望とします。品川区でもぜひ、不登校指導、今力を入れてくださっていると思いますけれども、今若干いろいろなところにあるというような形を１個にまとめるというところを改めて考え直す機会かなと思いますので、こちらについて要望とさせていただきまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"中塚委員","kind":"提案","question":"３７７ページの就学事務費に関連して、修学旅行や林間学校の無償化、また、部落解放同盟の機関紙、解放新聞について、品川区による校長先生への配付について、それぞれ伺いたいと思います。つまりは、教育委員会事務局が教育委員会定例会に予算案を提案する際に、この修学旅行などの無償化を提案する予定だということでよいのか伺いたいと思います。","respondent":"柏木学務課長","answer":"予算案に修学旅行の無償化を盛り込むかですけれども、修学旅行に限らず、今様々なものを検討していますので、予算編成の中でそこを整理していきたいと考えているところです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"提案","question":"９月１１日、森澤区長の区長記者会見で、記者との質疑の中で、修学旅行への無償化の質問があり、区長は、義務教育は無償化との観点から検討していきたいと説明がありました。つまり、教育委員の了解を得られれば、修学旅行などの無償化が実現するという段階なのか、改めて教育委員会定例会にその提案をする考えなのか、方向性をしっかり示してください。","respondent":"柏木学務課長","answer":"現時点で、すぐ修学旅行の予算を出すかどうかということは、現時点では決まっていないです。あくまでも、その考え方を今後整理するです。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"解放新聞全国版は月３回、解放新聞東京版は月１回、つまり、毎週のように、品川区より校長先生に配付されていることが、総務費の質疑で明らかになりました。教育の独立性に関わって伺いますが、各校長先生へ品川区が解放新聞を毎週配付しておりますけれども、これは教育委員会の各教育委員や各校長先生は了解していることなのか、誰が了解しているのか伺いたいと思います。","respondent":"舩木庶務課長","answer":"こちらは品川区の管理職職員として、身につけておかなければならない正しい知識、今のご指摘は人権に関するものですが、そういった部分に関し、研修等も行っておりますけれども、そういった研修、単発的な研修のみならず、こういった繰り返し。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"つまり、教育委員や各校長先生は了解はしていないということでよいのか、もう１回伺いたいと思います。この中で品川区は、つまり首長は、教育行政に対して、誰の了解も得ずに各校長に解放新聞を配付し続けているのか、改めて伺いたいと思います。こうした解放新聞の一方的な送付、送りつけは、教育への不当な介入に当たるのではないかと思いますが、その点どのようにお考えでしょうか。","respondent":"舩木庶務課長","answer":"教育委員会の独立性や政治的中立性というところに関しては、特に学校教育の中身に何かこういった、何か政治的な思いを取り入れてくださいということの取扱いではないというように捉えておりますので、区長部局のほうというご指摘ですけれども。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問","question":"いずれにしても承認は得られていない、了解は得られていないということですが、品川区が区の資料を送ることは何か分かる気はするのです。例えば森澤区長のプレス発表とか、予算とか。問題は、解放新聞を購入して送りつけているということなのです。一方的に区が送りつけている、受け取ったほうも教育に取り入れているわけではない、これはただ無駄遣いではないでしょうか。","respondent":"舩木庶務課長","answer":"逆に言えば必要性があるから、このような対応を取っているというように認識しておりますので、取扱いについて、送りつけているというよりは、いろいろなそのような知識を身につける方法としては、研修であったり、機関紙の情報提供をもって、過去の事例のみならず。","id":"exchange-082"},{"speaker":"中塚委員","kind":"質問","question":"ですから、先ほど課長が、学校教育に取り入れているわけではないとお話がありました。では、どこに必要性があるのでしょうか。","respondent":"舩木庶務課長","answer":"それを、いわゆる実際の教育の指導ですとか、そのような学校の教育の中身に特定の偏った思いなどというところ、それは総務省の解説でも、そのようなことは決してあってはならないということは記載されておりますけれども、そのようなことと、今回の、繰り返しになりますけれども。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"１年中。配付を教育委員会事務局が実態として了解しているというのであれば、それはそれで大問題だと思いますし、直ちに配付は断るべきだと私は思います。いずれにしても、長きにわたって黙認されてきた、続けてきた、こうしたあしき実態は、直ちにやめるよう求めたいと思いますし、教育委員会に対しては配付を断るべきだと思いますけれども、最後にいかがでしょうか。","respondent":"舩木庶務課長","answer":"このことが委員ご指摘のことには当たらないとは考えておりますが、取扱いにつきましては、必要に応じて関係所管課とも確認を取りながら、引き続き適切に対応してまいりたいと考えます。","id":"exchange-084"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３８３ページ特色ある教育活動に関連をしまして、偉人教育についてお伺いをいたします。偉人教育と言いますと、なかなか耳慣れない言葉だと思います。偉人の言葉、格言、人生を学ぶことで、生きる上でのたくさんの気づきがあったと思いますが、この学校教育から偉人教育がなくなってしまった理由について教えていただければと思います。","respondent":"中谷指導課長","answer":"偉人を扱う教育活動ということですけれども、現在社会科で歴史上の人物に視点を当てた学びをはじめといたしまして、そのほかの教科においても様々な方が教科書に掲載されておりまして、ねらいはそれぞれ異なるのですけれども、単に知識を学ぶだけでなく、その方の生き方など。","id":"exchange-085"},{"speaker":"こしば委員","kind":"質問・要望","question":"今、課長からお話がありました、決して偉人結局はなくなっていないという認識で、私も認識を改めさせていただきたいと思います。その一つが、２階のデッキから校門のほうを見ますと、そのそばに二宮金次郎像が建っておりました。そこでお聞きします。この二宮金次郎像、学校ではどのように捉えておられるのでしょうか。子どもたちにこの二宮金次郎像をどのように教えておられるのか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"例えば校長による朝礼での講話であったりとか、こうした市民科の授業の中で、二宮金次郎についての先人の生き方というか、そういうところで学ぶということで取上げがあろうかと考えています。","id":"exchange-086"},{"speaker":"こしば委員","kind":"質問","question":"５年生から７年生にかけて、この二宮金次郎像を様々な場面で教えておられるということ認識いたしました。品川区でも多くの偉人がいらっしゃいます。２階に上りますと、このモース博士の書斎をモデルにしたような図書室がございました。伊藤博文公も歴史上の偉人の一人に数えられると思いますが、学校教育の中でこの伊藤博文公をどのように捉え、子どもたちに教えていますでしょうか。","respondent":"中谷指導課長","answer":"地域の中での偉人の取扱いというところですけれども、今お話のありました伊藤博文、板垣退助のお墓を拝見するための訪問ということで、小学校３年生の社会科見学の取組として今年度行っております。","id":"exchange-087"},{"speaker":"こしば委員","kind":"質問・要望","question":"偉人ですから、必ずしもこの品川区と縁のない偉人もたくさんいらっしゃいます。品川区の学校では、授業で副読本を活用することもあるとのことです。その中で偉人の人生や、また偉人の言葉を集めた格言集、そういったものの副読本を取り入れることで、子どもたちに偉人教育を通じて人の生き方、また人生の志を考える機会をぜひお与えいただきたいと考えておりますが、見解をお伺いいたします。","respondent":"中谷指導課長","answer":"今、電子データを各学校で見ることができるような形になっておりまして、例えばフローレンス・ナイチンゲール、津田梅子など、それぞれの現段階で載っているもので総計しましても、１０人の偉人が紹介されているものを活用しています。","id":"exchange-088"},{"speaker":"こしば委員","kind":"質問・要望","question":"そういったものも含めて、恐らく大多数がその市民科の中で扱われることが多いと思いますが、偉人は当然歴史、社会の分野ですので、またその辺りもぜひ幅広く展開をしていただきたいとお願いをしまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"お願いします。修学旅行費の無償化に関しては、今日午前中も様々なお話がありました。私自身も前回の予算特別委員会において、修学旅行費の無償化を提案させていただいておりました。その点を踏まえて質問なのですけれども、昨今物価高によって、ホテル代ですとか交通費、食事代が上昇しているかと思うのですが、修学旅行の保護者の負担というのは、現在どのように推移していますでしょうか。","respondent":"柏木学務課長","answer":"修学旅行費の保護者の負担ですが、経年をちょっと追っているわけではないのですが、令和４年度と令和５年度で比較すると５,０００円ほど上がってあります。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"こういった状況も考えると、やはりなるべく無償化にしていくべきではないかと思いますし、これは５,０００円上がっていって、教職員の方たちもいろいろなところを切り詰めたりしていると思うのです。これは要望になります。その修学旅行費に関連してお伺いしたいのですけれども、教職員の修学旅行の下見についてなのですけれども、これは何名まで公費負担が出るのか、お教えください。","respondent":"中谷指導課長","answer":"修学旅行の教職員の下見ですけれども、旅行者は原則として１人としています。状況によっては１人ではなく、複数で行くように校長が判断する場合もあります。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。できればやはり複数名で行かれたほうがいいと思いますし、その場合、全額公費で出していただきたいと思います。その点はいかがでしょうか。","respondent":"中谷指導課長","answer":"もう一つが宿泊費になるのですけれども、こちらのほうが定額によるお支払いということになっておりまして、東京都の条例のほうに従って進めているものになるのですが、例えば管理職でない教員が下見に行きたいというところで。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり教職員に負担がかかる場合もあると思いますので、この点も含めて負担がないようにということで要望します。今、管理職というところでお話があったので、校長先生に関してお伺いします。校長の修学旅行の下見というのは、公費負担の線引きというのはどのようになっていますでしょうか。","respondent":"中谷指導課長","answer":"先ほどの答弁の、教員に対して出す１万１,０００円というのは１夜というところでご認識いただければと思っています。それ以外の例えば校長先生などというところで申し上げますと、１万５,０００円の宿泊料定額というところになります。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"確認","question":"そういったときに、では下見に実際校長先生が行ってみて、子どもにとって学習に非常にいいかどうか判断しようと思ったときに、自腹で行かなくてはいけないということになると思うのですけれども、ちょっとそこを今確認させてください。いかがでしょうか。","respondent":"中谷指導課長","answer":"下見とは何かというところになるのですけれども、例えば実際に子どもたちが活動する取組に合わせて、班行動したりすることを想定して電車の時刻表を確認したり、宿泊場所内の動線を確認したりして。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。１つ気になったのが、この動画の中で、例えばスクール・サポート・スタッフですとか学校地域コーディネーター、副校長の補佐みたいな、そういうほかの区にはない、品川区の教員のそういったサポート体制の充実というようなところが触れられていなくて、こういった区の特色をぜひ前面に押し出していただきたいと思うのですが、その点いかがでしょうか。","respondent":"中谷指導課長","answer":"その中に教員が担わなくてもよい業務を進めるスタッフがたくさんいるというような、そういうところでお声もいただくみたいな動画ができれば、より品川区が非常に人的体制も充実する中で、独自の教育を進めているということが伝わるのかなと思いますので。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"意見","question":"ぜひともお願いいたします。最後、時間がないのですけれども、学校支援コーディネーターなのですが、実はこれ、スクール・サポート・スタッフは、前年度で５０円時給が上がったのですけれども、実は上がっていないのですよね。今、賃金が逆転してしまっているので、ぜひその辺の改善をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"ようやく来年あたりには東京都のほうで予算を取ったりして工事の段取りも決まって、元の空調がしっかり効くような形になると伺ったのですけれども、こういった空調の故障が何年にもわたって、夏の猛暑の学校の状況に悪い影響を与えるというようなことがあってはいけないなという思いで、この区立小・中学校の空調の点検の状況、それから、仮に不具合等が発生した場合の修繕の実施。","respondent":"荒木学校施設担当課長","answer":"これに加えまして、専門の委託業者に保守点検も委託をしておりまして、日常的な維持点検も実施をしております。この維持点検の中で急な不具合等が発生すれば、区のほうでしっかりと工事を発注して、即座に対応するという対応を取っているところです。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"３８１ページの教員支援経費なのですけれども、学校教員の働き方改革ということで、今、学校にはたくさんのいろいろな方々のサポートがありますという中で、今年度からですか、副校長補佐というものが配置をされました。","respondent":"中谷指導課長","answer":"所属職員への指導助言の時間が増えましたかという副校長への質問に対して、増えましたと９割が回答してくださっているということがありますので、こういった事業で、子どもと直接関わる教員への指導助言の時間というのができまして。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"もう少しできるのであればお願いしてもいい部分というのはあったりするのではないかというようにも思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"ですので、そういったところを最大限活用することで、副校長が毎日いろいろなことを頼まれる中で、補佐の方が一部でもやってくれるというところの安心感だと思いますので、こういったことを続けていきたいと思っています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。いろいろメリットがあるというようなことはネット等でも読ませていただきましたけれども、品川区は今年度、既に理科の教員が１人区内の中学校から転任されて、小学校のほうで教科担任制をされていると。このことについての区の評価、今その教科担任の方をどういった評価をされているか、お伺いいたします。","respondent":"中谷指導課長","answer":"やはりその働き方改革という意味では、本校における教職員の働き方の改善の効果というところも狙っていきたいと思っているので、ここに関しては現時点では検証中というところになっております。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。１つお伺いしたいのは、１名という人数は、どういった背景でここの採用の定員が１名なのかということと、あと品川区には義務教育学校がもともとあって、そういう意味ではこういった小学校からの教科担任制みたいなことが、ある程度自然発生的にあった部分があるかと思いますが、そういった知見も生かして今後の教科担任制に向けての区の見解を伺いたいと思います。","respondent":"中谷指導課長","answer":"今後の将来的なところなのですけれども、２校２教科の成果と課題を整理しまして、その内容を生かす形で東京都教育委員会と連携しながら、加配をさらに拡大することを前提に検討していきたいと考えています。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひよい結果に至るように進めていただきたいと思います。それにあたって、端末の仕様をどういったものにするかというところでの共通仕様というものを今検討されているのか、どういう状況なのかというのを聞きたいのと、この端末の更新は都が中心だとは思いますけれども、今後どのようなスケジュールでなされていくのか、現状をお聞きしたいと思います。","respondent":"柏木学務課長","answer":"なので、そちらの価格を含めて検討しています。もう一点、スケジュールですが、端末は来年度末、令和８年３月で切れますので、その４月から新しく使えるような形で、来年度から順次進めていきたいと考えています。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３７２ページから始まる教育費に関わって、義務教育の無償化を求めて伺います。森澤区長はこの学用品の無償化に踏み出した会見で、憲法２６条を引き合いに出し、意思を発表しました。憲法２６条には、義務教育は無償とすると書かれています。だからこそ、この義務教育を無償化すべきだと考えます。品川区はこの教育の発展で利益を得るのは誰だと思っているのか伺います。","respondent":"柏木学務課長","answer":"誰の利益になるかということですけれども、最終的には子どもたちの利益になってくるものと考えています。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"最終的には子どもたちということですけれども、そこの個人の問題だけでなくて、やはりそうしたことが社会を発展させていくという認識はお持ちなのかどうか伺います。","respondent":"柏木学務課長","answer":"無償化するにあたって、子育て世代の負担を軽減して、子育てしやすい環境を整備するということを掲げて実施していますので、当然社会に対してもそういうことが還元されるものと考えています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"社会に還元されるということが、やはり重要だと私は思います。そうした中で、一義的にはやはり国が実施をしていくべきものだと思います。この間、区もそうした考えだと述べている中で、義務教育の無償化への財源を国や都に求めるべきだと思いますけれども、この間求めてきたのかどうか伺いたいと思います。","respondent":"柏木学務課長","answer":"特別区の教育長会、または区長会等から、そういう財源については要望を出しています。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"区長会などでも出してきているということですので、ぜひそうしたことも引き続き求めていただいて、区のできるところから無償化に向けて進めていっていただきたいと思います。制服や義務教育学校、小・中一貫校の標準服や体操着など、授業等で利用するものは無償化すべきだと思いますが、いかがでしょうか。義務教育学校、小・中一貫校の標準服は、必ず着用しなければならないものなのかどうか伺います。","respondent":"柏木学務課長","answer":"標準服、体操着等の無償化ですが、午前中にも答弁いたしましたけれども、今後の保護者の負担軽減・無償化につきましては、予算編成作業の中で考え方については整理をしていきたいと考えています。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"無償化に向けては予算編成の中でということですけれども、こうした制服についても検討の中に入っているのかどうか、伺いたいと思います。それと、標準服の着用は、八潮学園では着ていない方もいるということですか。そうした中で、やはり負担がさらに重くなるということになりますので、小学校についてはこの標準服をやめるべきではないかということも思うのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"初めに標準服の無償化についても検討に入っているかですが、一つの選択肢としては入ってあります。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"制服などの無償化も一つの選択肢ということですので、ぜひ検討を進めていただいて、実現していただけたらと思います。服を選ぶ自由も保障しながら、負担軽減をしていくようにしていただきたいと思います。やはり教育課程の中で行われている修学旅行、その教育的意義は何か、伺いたいと思います。そして、無償化に踏み出していただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"修学旅行の意義ですけれども、本区でありますと関西方面が多くありますけれども、日本にあります歴史や文化に触れながら日本の歴史に触れるというところで、大きな意義があると考えております。修学旅行の無償化につきましては、今後、予算編成の作業の中で整理をしていきたいと考えています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育的意義もあるということですので、この修学旅行、ほかにも制服も含めて本当に義務教育の完全無償化で、経済力に関係なくやはり教育を保障する。そして子どもたちの人格発展にも寄与するように、義務教育の無償化を実施していただきたいと求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、３７５ページＰＴＡ関係費、３９３ページ学校ＩＣＴ活用経費、３９９ページ学校給食費無償化について、お伺いします。初めに学校給食無償化ですが、令和５年度を通じて無償化をしていただきました。これを区教育委員会としてどのように評価をされているのか。どのようなお声をいただいているのか、お聞かせください。","respondent":"柏木学務課長","answer":"どのように捉えているかという部分ですが、給食費の負担を軽減する、今までで言いますと年間で平均ですと６万円ぐらい保護者の方から負担いただいていたと。その部分が軽減できているという部分で、家庭の負担はその部分が減っている。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そうですよね。約６万円の負担が親御ごさんたちになくなってきたと。これは本来は国がやるべきです。私も進めていただきたいし、本当はこれも国でやることだから、我々国民民主党は国政選挙において公約としても掲げ、取り組んでいるところであります。けれども国が動かないから、私も区にお願いするしかないので、ぜひその実現に向けて取り組んでいただければと要望して、この件は終わりにします。","respondent":"舩木庶務課長","answer":"今、委員のご指摘のとおり、様々な時代の移り変わりとともに、ＰＴＡの活動のあり方も変わってきているということは認識しております。","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこでも、いわゆる加入のあり方だったり、いわゆるＰＴＡ会費の徴収の仕方だったり、こういったものについても改善を求めるというような陳情だったと思いますが、ぜひそういった様々な課題があるというのは認識していただいて、区教育委員会でできること、もちろん学校、そしてＰＴＡ、それぞれができることというのはあると思いますけれども。","respondent":"舩木庶務課長","answer":"例えば参画のあり方も、オンラインでＰＴＡの打合せをするとか、必ずしも時間を取ってどこかに集まらなくてはいけないとかいうことではなく、その辺はいろいろ様々工夫ができる余地があると思いますので、そのあたりについてはどういったあり方が好ましいかというところは。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"タブレット端末の導入をお願いしていたときに、私がなぜタブレット端末を使ったらいいかという一つの例として挙げたのが、例えば体育の授業で、今までは自分の跳び箱を跳ぶ姿というのはどうしても見ることができなかったのだけれども、タブレット端末を使うと録画をして、それを見て、何が駄目だったかというのを的確に指導することができるようになるのですよということで。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちが楽しく体を動かす、スポーツに親しむということは大変意味のあることだと、大切なことだと考えております。生成ＡＩの力も借りながら、そういった教育に生かせるようなものを取り入れられればと思います。","id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。３７７ページプール指導員経費、それと時間があれば、３９１ページ地区図書館運営費についてお尋ねをさせてもらいます。最初に３７７ページ、プール指導員経費についてお伺いします。本当に今年の夏はとにかくすごい猛暑で、小・中学校のプール授業が次々に中止になったとお聞きしております。","respondent":"丸谷教育総合支援センター長","answer":"残りの２割につきましても、２時間続きの授業が１回程度中止せざるを得なかったという程度で、何とか授業の組替え等で実施できたと把握しております。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問","question":"このプールの授業は、先生方も本当に大変なご苦労もあったかと思います。それで改めてお聞きしますけれども、このプールの授業の意義について、ご説明をお願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"中学校でも、記録の向上や競争の楽しさ・喜びを味わい、水泳の特性や成り立ち、技術の名称、行い方、その運動に関連して高まる体力などを理解するとともに、泳法を身につけるということで、そういった目的が示されているところです。","id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"意見","question":"今のご説明があったように、陸上のスポーツと違って、やはり水泳というのは、本当に水泳系の授業は丸きり異なる重要性は、私もそのように思っております。それで、現在区ではプール授業において何に注意をし、何を準備しながら実施を行っているのかをご説明願います。","respondent":"丸谷教育総合支援センター長","answer":"おおむね足して５０度を下回ったときは、寒過ぎて入れないという判断をするのですけれども、例えば暑さ指数が３１を超えると、これはもう熱中症のおそれがあるということで原則禁止をしているということで、その日の暑さ指数をしっかり測って実施を行っているところです。","id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは日本スポーツ振興センターが災害共済給付を行った件数のうち、プールでの熱中症の発生件数、すみません大分前なのですけれども、２０１３年から１７年にかけて１７９件という報告があります。屋外だけではなく、屋内でもその整備が進んでいるとお聞きしております。現在、品川区のプール授業を安全に進めるための今後の方針をお示しください。","respondent":"丸谷教育総合支援センター長","answer":"今ご案内いただいたような汗が分からない、のどの渇きに気づきにくいというところはおっしゃるとおりですので、そういったことも現在周知をしているところです。そういったものをしっかりと学校には注意喚起しながら、安全な水泳指導に努めてまいりたいと考えております。","id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは源氏前小学校だけではなくて、例えばこれまで委員のほうからも、歳入のところでいろいろ質問もありましたけれども、上部からのミストによる散水とか、あるいは手動で開く簡易テントの設置とか、そういうのもこれから必要なのではないかと私は思っておりますけれども、設計・施工の段階で、そういう工事はこれからでも間に合うと思うので。","respondent":"荒木学校施設担当課長","answer":"しかしながら今後の熱中症対策というところもありますので、来年度以降、源氏前小学校だとか城南第二小学校以外の既存校舎の平置プールへの設置も含めて、何か対策が取れないかというところを試験的に検討してまいりたいと考えています。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本当に児童・生徒の泳力をつけるためにこのプール指導は非常に大切なものだと考えていますので、ぜひとも暑さ対策、これはぜひよろしくお願いをいたします。本当に安全で楽しく水泳で身体能力を磨いて、特に着衣泳とかそういうものもやっていると思うのです。水の事故を未然に防ぐためにもプール授業は大変有意義な授業だと思いますので、発展を希望して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、３７５ページ文化財保存活用事業に関連して、少し広がりますけれども質問します。品川区は言うまでもなく歴史的資源が豊富で、その宝庫だと考えています。この歴史的資源を観光ですとか地域のにぎわいに生かすことも重要な施策ですし、また、私はぜひ教育にも利用していただきたいという思いで、少し質問をします。この９か所が選ばれた理由をお聞かせいただきたいと思います。","respondent":"舩木庶務課長","answer":"これは貴重な歴史的文化財をしっかりと守っていく、継承していくです。ただ、しかしながらこういった文化の日の３連休のところには一般に公開をし、そして皆さんに知っていただく、歴史を感じていただくといったところの試みです。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"その違いがどうこうではないのですけれども、今回の３日間を通じての公開ということでありますが、またオープンされているところは通年で積極的に区民の皆様への情報発信をぜひしていただきたいのと、１１月２、３、４日ということなので、土・日・月で祭日であります。今回のこの３日間の中で、学校への招待・紹介というのはあるのでしょうか。","respondent":"舩木庶務課長","answer":"委員のご指摘のとおり、より知っていただく方法はどのような方法があるかということ、いろいろな史跡巡りとか、子どもたちをターゲットにしたイベントといいますか、そういった取組も行っておりますが。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"申し訳ございません、不勉強で全部見ていないので、どういう方が対象だったのかということは改めてそこは学んだ上で別の機会でお伺いをしていきたいと思いますが、既に先ほどのお話のように、土佐藩の下屋敷が浜川中学校のところにあったということで、高知県との交流があったりとかというお話もありました。","respondent":"中谷指導課長","answer":"そういった中で、ぜひこの会のほうにも入っていただくことを少しアプローチしてみようかなと、今のお話を伺って思いましたので、またそういう交流の輪を広げながら、教育委員会職員同士での懇親会というのも毎年やらせていただいておりますので。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"その交流会は、光市はこれから一貫校を立ち上げるということなので、今後の話ではありますが、先輩としても、また伊藤公を通じてお互いの切磋琢磨につなげていただきたいと思います。一番はやはり『学問ノススメ』、当時も大ベストセラーになった『学問ノススメ』を著した方で、日本を代表する教育者であります。特に地元の第三日野小学校を中心にお願いしたいと思いますが、ご意見をお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"福澤諭吉の学習についてなのですけれども、現在市民科の３、４年生の教科書の中で、人物紹介をしています。","id":"exchange-123"},{"speaker":"田中委員","kind":"意見","question":"私が先ほども言いましたように、それを子どもの教育だけではなくて、大人のいわゆる生涯教育といったことも含めて広く、またその年代も小学校だけではなく、教育の題材としては最高の題材だと思いますので、中学校をはじめしっかり積極的にお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"３８１ページ、生徒指導対策経費から伺います。ご答弁では、２０２３年からは郵送での提出、電話・メール・オンラインでの提出ができるようになったと伺いました。私が質問したのは、質問の仕方が悪かったのかもしれないですけれども、生徒指導提要の１０５ページに書かれているような事例をイメージしたのですけれども、品川区はこの東京都教育委員会が示してきた調査内容で、適切と判断したのでしょうか。","respondent":"中谷指導課長","answer":"これに関しては品川区だけでなく、都内全地区、同じ項目で取っておりまして、それが東京都教育委員会の立場から考えると共通項目で取るという必要性を感じて、このような形になったのかと受け止めています。","id":"exchange-125"},{"speaker":"吉田委員","kind":"質問","question":"確かにセクハラ・性暴力がそれほど横行しているのであれば、しっかり調査をすべきだと思います。東京都教育委員会が示してきたということも理解しているのですけれども、品川区として、ではそれはもう少しこういう項目を増やすべきだというような意見を言えるはずだと理解していたのですけれども、それは違うのでしょうか。","respondent":"中谷指導課長","answer":"おっしゃるとおり、体罰等はなくなっておらず、根絶を目指して取り組むべき重要なものだと捉えております。","id":"exchange-126"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ品川区の教育委員会からの問題意識を、東京都教育委員会にしっかり伝えていただきたいと思います。ぜひその辺については保護者を通して、この調査は体罰等に関する調査でもあるのだということをしっかり伝えていただきたいと思うのですけれども、お考えを伺います。","respondent":"中谷指導課長","answer":"すべての学校から、管理職が中心となりまして、保護者の皆様に対してしっかりとしたこういう調査をやる、そしてどういった調査なのかといったことも含めて、お手紙が主流かと考えていますが、必ず周知をしてからお子さんたちに行うというような手立てを取っておりますので。","id":"exchange-127"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは強く要望しておきます。もう一つが学校環境整備費で、これは香りの害のことを伺います。香りの害を苦手とする子どもたちへの配慮を求めて、生活者ネットワークは質問を繰り返してまいりました。あまりいいきっかけではなかったのですけれども、コロナ禍で感染防止の視点から自前の給食着を持ってきてよいことになった学校があったと伺いましたが、それは継続しているのか確認させてください。","respondent":"柏木学務課長","answer":"給食の白衣の個人の持参についてですが、学校のほうで個別に対応していますが、コロナが５類になったから、そういうのをやめたという話は聞いてございません。","id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"しかし、本当に苦しんでいる人にとっては配慮では足りない、禁止を求めたいというのが本当のところです。最近では、化学物質過敏症または環境過敏症などと呼ばれて、合理的配慮が求められるようになりました。ぜひこの品川区においても、皆さんよかったら参加していただきたいと思うのですけれども、この点についての香りの害についての問題意識をどのようにお考えか、伺いたいと思います。","respondent":"柏木学務課長","answer":"令和４年３月に厚生労働省のほうから、科学的根拠に基づくシックハウス症候群に関する相談マニュアル（改訂新版）の再周知についてということで通知がございましたので、こちらのほうも学校のほうに周知し、化学物質過敏症について啓発をしています。","id":"exchange-129"},{"speaker":"吉田委員","kind":"質問・要望","question":"前に伺ったときは、ポスターはデータで送られてきて、それをプリントアウトして張ってくださいみたいな感じだったのですけれども、教育委員会としてそれぞれの学校に配っていると理解してよろしいのでしょうか。先ほどの不適切指導についても全国的な調査活動が始まろうとしておりますので、その点についてもご協力いただきたいと思いますが、そういう検討の余地があるかどうか、ちょっとお答えください。","respondent":"舩木庶務課長","answer":"区の教育委員会の後援のあり方につきましては、区との関係性であるとかいろいろ要件がありますので、そういったところに適合するかどうかについては、検討ということになるかと思います。","id":"exchange-130"},{"speaker":"吉田委員","kind":"質問","question":"なかなか力量がなくて、そういう大々的なほかの自治体みたいなイベントを開けないのですけれども、もしそのときにはぜひご検討をお願いします。それから、調査活動についてもご説明に伺いますので、ぜひご協力・ご検討くださいますようお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"若林委員","kind":"確認","question":"３７８ページの教育指導費になると思います。就学時健診の１年前に、主に言語・知的発達を確認するための検診の実施が保健所を中心に検討をされている現状があります。今後、教育、そして福祉との連携を図って一緒に検討されていくという答弁がありました。これについて一つちょっとお聞きしたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"その前の年にこの検診が行われるというような形になっておりますので、内容というよりかは、やはり連携することが肝要かと考えていますので、引き続き関係部局と連携していければと考えています。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問","question":"ぜひ特別支援とか、またマイスクール等に携わっておられる方々のお声をしっかりとここで一回集約をして、そして保健所と、また福祉との検討会というのでしょうか、協議会というのでしょうか。そこに臨んでいただいて、協議がされた後にはまた現場にフィードバックしていただいて、子どもたちにとって有益となるような１年前の検診になるように切に希望いたしますが、ご答弁をお願いしたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"我々で実施する就学相談の１年前に情報が分かるという形であれば、その間、保護者の方がいろいろ検討する時間というものも出ますでしょうし、または療育につながることもあるかと考えられます。","id":"exchange-133"},{"speaker":"若林委員","kind":"確認","question":"３９５ページの学校環境整備関連について、何点か伺います。信頼をして私たちは報告を受けていいのかということの確認。これは令和１０年度の完了計画で、４年間で３３個、割り返すと年で８個計画的にやっていくと理解をするのですが、それでいいのかどうかという確認と、併せて年に８個であるとすれば、改築と未改築の学校数というのはどのような計画の下にされるのか、これについても確認をします。","respondent":"荒木学校施設担当課長","answer":"残りが３０校という状況です。令和１０年度までに完了するというなかなか高い目標は示しているのですけれども、今後も計画的にしっかりと改修を進めてまいりたいと考えております。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"人工芝のほうは、当然地域の方々の声を大事にしていただきたいと思います。ＬＥＤ化については、ちょっと今ご答弁が不明確な部分が、これは事務事業評価を基に質問していますので、もう少し明確な答弁があるかなと思いましたけれども、今後またぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問・要望","question":"３７８ページの教育指導費についてお尋ねします。品川区の教育施策の歴史を見ると、まず教育改革プラン２１というのがありました。これによってたくさんの改革がなされたのですね。最近はどうかと。でも、これは本来は国がやるべきことだと私も思います。２,０００億円ちょっとですね。教育長、ぜひお答えいただきたいのですが、これからの品川区の教育、子どもたちをどうしていかれたいと思いますか。","respondent":"舩木庶務課長","answer":"こういった、今教育委員会にある教育目標や基本方針をどのように具現化していくかということを体系的に示していくものですが、具体的な学校教育にどのように生かしていくかについては、本計画が策定後にいろいろと進めていくところですけれども。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"私は教育長に答弁を願いたかったのです。これから品川区の教育、子どもたちをどうしていくのですかということ、それから、財源は限られますので、予算立てをどう考えているのですかということ、どのような考え方でこれからこの予算を立てていくのかをお答えいただきたいとお願いしたいのですが、いかがですか、教育長。","respondent":"伊崎教育長","answer":"ただいま庶務課長のほうから、今年度教育振興基本計画の策定準備をしているということをご説明させていただきました。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、特に教育ですから、こうあるべきという、強い思いというのがないと今出ました品川区教育振興基本計画というのが検討されているというのをお聞きしましたけれども、これは国の動きがあってではないですか。それが全部ベースになっているのではないですか。これは施設を問わず就学前教育なのではないのですかということ非常に疑問を思いますので、この２つについての考えをお聞きしたいと思います。","respondent":"唐澤特別支援教育担当課長、中谷指導課長","answer":"誰一人取り残さないという視点ですが、特別支援教育担当のみで語れるものではございませんが、発達障害教育支援員の配置や、お子さんの状況に応じた学級の新設、また、お話にありました医療的ケアの対応につきましては。特に架け橋期である５歳児から１年生の２年間の教育の工夫と充実というところが重点だと考えていますので、今、少しずつそういったことが、まず集まる組織をつくるということで。","id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ今までやってきたことを十分に認識していただきたいと思います。そして、品川区ならでの教育をぜひ実現させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問","question":"よろしくお願いします。西本委員とちょっと似そうなのでびっくりしておりますが、３９７ページ学校運営費、校長先生の権限に触れていきたいと考えています。これは先ほど教育長にいろいろ話があったのだけれども、品川は今まで一言で、前教育長、前々教育長も含めて、では品川の子どもたちをどのように育てていくのですかと。変わっているのだったら何か違う言葉を言っていただければと思います。","respondent":"伊崎教育長","answer":"今、過去二十数年にわたる品川区の教育改革の歩みについてお話をいただきました。未来を創る力、未来を生きる力、未来を生き抜く力ということで、品川区は教育を進めてまいりました。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはそれで教育長のお話はしっかり受け止めます。それにはスピード感を持って、それは校長先生の権限でどうやっていくかということを、私はもっともっとある程度予算をつけてあげてやっていくべきだと考えていますが、もっと校長先生を信じてあげたほうがいいと私は個人的には思っています。だからそういう形のことをどのように捉えられていますかということを、ちょっとお聞きしたい。","respondent":"中谷指導課長","answer":"これが、実際例えば１つの１単位時間の授業でイベント的に終わるものではなくて、例えば専門家から教えていただいたら、それをしっかり学びが継続するようにカリキュラム・マネジメントのような形で。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一から全部の教育の時間をこうやってここに入れ込んでどうのと全部計画し直さないと、なかなかそうはいかないのです。だから、子どもたちのために、そういうことをもっとスピード感を持ってやっていただきたいということです。それは港区とよく言うけれども、そういうふうに海外だって何だってよくて、学校で子どもたちのためにここに行きたと言うのならば、私の考えはそこで制約だけは設けないでほしい。","respondent":"丸谷教育総合支援センター長","answer":"そうした学校の裁量というものは持たせているところです。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひそれはよろしくお願いします。もう一点は文化財の保護費をやりたかったのだけれども、文化財は無形文化財に５万円とかを頂いているけれども、これを継続するには相当皆さんの努力があって、なかなか今難しいのです。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。３９３ページ、教材教具等経費の中の教師用教科書、指導書購入についてお尋ねします。申し訳ありません。それで、決算額５,１４５万５,８１６円について、契約内容を伺います。契約の本数、複数の場合はそれぞれの金額も教えていただきたいと思います。６年度の契約も既に終えていると思います。１億４,７７５万６,０００円あります。よろしくお願いします。","respondent":"柏木学務課長","answer":"教師用教科書、指導書の購入についてですが、基本的には教員の分の教科書ですが、令和５年度につきましては不足数分の購入と、指導書も学級数の増加等に伴っての契約になります。すみません、契約の本数ですが、今すぐにはお答えできません。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません。では、契約本数は複数ということですか、確認します。それから、入札なのか随意なのかということをお尋ねします。それから、決定権者についてもお話がなかったのでお願いします。","respondent":"柏木学務課長","answer":"契約の本数につきましては、基本的には教科書と指導書が別の契約になってあります。決定権者につきましては、こちらは随意契約で所管の契約ができますので、学務課長となっています。令和６年度につきましても、同様に学務課長の決定で随意契約となっています。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、所管で契約をされたということなのですが、品川区の契約事務規則ですと、「議会の議決に付すべきものならびに」、これは４,０００万円以上ですが、「特に区長が指定するものについてはこの限りではない」ということです。なぜ議会に付さなかったのかということと、あと、契約を今幾つかに分けた、２本と言いましたが、それに分けたのでしょうか。","respondent":"柏木学務課長","answer":"今年度につきましても、主に小学校の教科書と指導書は契約を分けてありますが、指導書につきましては、現在、デジタルのものが非常に多くなってございまして、契約の規則の４,０００万円につきましては一般需用費になってございまして。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"契約相手も同一です。そして、随意契約であります。なぜそういうふうにお話しするかというと、令和５年度の決算が４,０００万円を超えています。ということで、４,０００万円を超えるということについては議決が必要だということをご存じだったのか、それともそうではなく、学務課の方々、あるいは課長、前々からやっていたのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"４,０００万円以上の物品の購入については議決が必要というのは、存じ上げてあります。ただ、今回のものにつきましてはデジタルの指導書になりますので、いわゆる一般需用費ではなく使用料の扱いになりますので、４,０００万円の対象外判断をしています。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"提案","question":"今、そういう判断をされたということですけれども、デジタル教科書は令和２年の１億３,０００万円の中にあるのでしょうか。令和２年、３年、４年と４,０００万円を全て超えているわけですよね。ということで、契約案件として提案していただいていません。この件について教育長の見解と、今後の対応をどのようにするか、お伺いします。","respondent":"柏木学務課長","answer":"デジタルの指導書につきましては、令和２年度もございましたが、こちらはいわゆるデジタル書籍の扱いですので、それは使用料という扱いになりますので、契約の規則に沿ったものと考えています。","id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"質問","question":"２３区のうち７区は年度内、第１回の定例会で、やはり地方自治法第９６条に違反するということでありましたので、実は別の議会では追認議案を提出し、追認議案が可決されています。これは特別監査になるかと思いますが、他自治体では定期監査で見つかって、随時監査を出したり特別監査をしていますが、いかがでしょうか。","respondent":"久保田企画経営部長","answer":"今、教科書の関係は学務課長が説明したとおりの契約ということで、我々も認識しています。その他の関係につきましては、今委員から指摘がありましたので、我々のほうでも経理課で確認をさせていただき、また改めて報告させていただきたいと思います。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"今日、もう修学旅行の話はみんなしているのですけれども、もちろん無償化していただけるのであればいいし、これからの質問は、多分無償化になってしまったらあまり意味がないのですが、無償化まではいかないとしても、その手前の就学援助の中のお話を少しお伺いしたいのですが、就学援助をしていただいています修学旅行費、これは年間でいつの段階で支給されるのか伺います。","respondent":"柏木学務課長","answer":"修学旅行費の支給ですけれども、こちらは修学旅行に行ったことが確認されて、それの後の直近の支払い月になってあります。ですので、１学期で行っている場合には７月の支給、２学期に行く場合については１２月の支給となっています。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、この修学旅行費についても前払いといいますか、先に払うという対応もあるのではないかと思いますというか、これは要望したいのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"就学援助の修学旅行費の前倒しについても、教育委員会としては検討しています。修学旅行の無償化のときも申し上げてありますが、予算編成の中で考えていきたいと考えています。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"なので、必ずしも区立の方たちだけを対象にしているのではない、もちろんサービスによって、施策によっては区立校に限定するということはあると思うのですが、そことの関係でマイスクールについて伺います。この点について、私立や国立の児童・生徒を対象にしてはいけないというふうな、対象にはならないというふうな国の法令、あるいは都の条例等の根拠があるのか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"しかしながら、本区において、区立学校の不登校児童・生徒数は昨年度７９９名、マイスクールに受け入れられたのが１０３名にとどまっておりまして、区立学校に在籍する児童・生徒への支援も十分に行われていない段階でございまして、そうしたことも考えると、私立学校を含め国立。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"そうすると、たしか前の午前中だかのご答弁で、マイスクールに行かれている利用率が少し下がっているというお話もあったかと思うのです。では、その場合に、都立、国立、私立の子どもたちがどうしたらいいのかということを考えたときに、区立以外の学校については、本来は所管が東京都ということになるかと思いますが、東京都のほうで教育支援センター、適応指導教室はあるのか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"我々のほうでは、東京都が設置する適応指導教室、教育支援センターの設置は確認できておりません。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問","question":"とするならば、やはり国立、都立、私立に行っている子どもたちが不登校になったときに、当区で言うところのマイスクールのようなものがないというところなのだと思います。こうした記載からも、やはりマイスクールの対象を区立学校に限る必要はないというか、そこは変えていっていただくのがいいのではないかと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"我々も文部科学省の通知についての認識はございまして、今年度、４教室目となるマイスクール西大井の開設をはじめ、校内別室指導支援員の配置等、事業を拡大しております。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"少しだけ時間が余りましたので、要望というわけではないのですが、これはきちんと言っておかないといけないのかなと思ったのが道路のことで、昨日写真をお見せして、荏原南公園の水が道路で冠水しているという写真を流させていただいたのですが、結局、私の時間管理の能力の中で、ご答弁をいただけなかった状態で終わったのですが、その後、課長に伺ったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"そういう教員も、結局東京都の教員ですから東京都から配置されてきます。そうすると断れないではないですか。こんなことをいつまでもやっていていいのでしょうか。後でお答えください。そして、小中一貫校である義務教育学校には、小学生と中学生が一緒に学んでいるため、小学校教諭免許と中学校教諭免許、専科は別ですが、この２つの免許が必要ですが、２つの免許を持った教員は集まっているのでしょうか。","respondent":"中谷指導課長","answer":"今そういった学校経営をしているわけですけれども、品川区としては、人事権の移譲ということで、かねてより東京都に対して移譲ができないかということも引き続きやっているところでありますので、これは継続していくというところになります。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"このままでいいのでしょうか。これは前もお聞きしましたが、結局、東京都の教員ですから、３年たったら出入り自由ですよね、先生方が。２つの免許を持っている人がそこで出てってしまう。こんなことをいつまでも繰り返していていいのでしょうか。やはりこういうシステムも、私は何か改善していかないとまずいかと思うのですが、その辺についてもう１回ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"品川区単独で何か制度を変えるということはなかなか難しく、これは、今、国の「当面は」というフレーズがずっと残っているという現状についてのご指摘かと考えていますけれども、これについては、先日行いました小中一貫全国連絡協議会の中でもやはり話題になっておりましたので。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"１８年たってなかなか正式に認可されないような状況、これは失敗するのですかね、このまま行ったら。先ほども言いましたね。そして、固有教員２８名の方は両方持つ人を採用している。私はできないと思うので、その辺はやはりきちんとこれから改善していってほしいと思います。もう公立に行かない、そういう子どもたちが多いように私は聞いているのですが、この数字は間違いないですか。教えてください。","respondent":"柏木学務課長","answer":"区立小学校を卒業し、私立の中学校に行かれる方のパーセンテージですけれども、委員のおっしゃる数字を若干上回っている感じです。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"このように公立学校が保護者や子どもたちから選ばれない実態について、本当にどう思われますかね。逆に、皆さんが公立学校に対しての、学校公開もあります。何か指導に対して不安とか、そういうことの表れでもあるのではないのですか。でも、実態、こんな数字を見ていたら、私たちは「何やっているのですか、教育委員会」というふうに言わざるを得ないのですが、その辺についてご見解をお聞かせください。","respondent":"中谷指導課長","answer":"もしも１つの種目を継続していれば、技術面での上達が高く期待できるということを直接おっしゃっていました。それから、２つ目が、７年生以上の中学生が小学生と一緒に、部活動だけではなくて、例えば学校行事や給食などを通じて直接交流ができる。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"幾つも出ています。そうしたら、親はどうですか。こんな小中一貫校で、こんな教員を都から言われたって、自分たちで育てた教員ではないのだから無理なのですよということを、やはり明確に手を挙げていかないと、品川区の教育制度は１８年たちましたが全然変わらないではないですか。だけど、しようがないではないですか、もうほかに駒がないのだから。ぜひそこはこれからも頑張ってほしいと思います。","respondent":"中谷指導課長","answer":"そこで、先ほどもお話しいただいたとおり、全国の中でも一番を取って進んでおりますので、来年に義務教育学校１０周年記念シンポジウムと題しまして、いま一度、義務教育学校の成果と課題も含めてきちんと整理をして。","id":"exchange-160"},{"speaker":"鈴木委員","kind":"質問・要望","question":"伺いたいのが、その会計年度任用職員の内訳を教えていただきたいと思います。それから、マイスクールとかＨＥＡＲＴＳ、そして、教育相談、特別支援教育の相談、また学校巡回、スクールカウンセラーなど、子どもたちや保護者にとって本当に重要な役割を担う部署であり、経験の蓄積も大事な専門職であるにもかかわらず、なぜ正規職員ではなくて全てが会計年度任用職員なのかについても伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"昨年度の人数にはなりますけれども、教育総合支援センターには心理士が２７名、スクールソーシャルワーカーが６名、また教育アドバイザーをはじめマイスクールの指導員等、教員免許を持っている方が１９名、東京都任用のスクールカウンセラーが５４名おります。","id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問","question":"大体手取りで２０万円ちょっとぐらいではないでしょうか。定期昇給もない。経験加算もない。何年経験を積んでも新人と同じ。さらに、１年雇用で、続けて働けるのかどうかというのが常に不安。会計年度任用職員のこういう状況ですので、これは待遇の改善が必要だと思いますが、区としてどう考えられているのか伺いたいと思います。待遇改善についての考え方です。","respondent":"宮尾人事課長","answer":"期末手当、勤勉手当、勤勉手当につきましても今年度から支給がされているというところで、一定程度、改善というものはなされているものと認識をしています。","id":"exchange-162"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、このアンケートからも、改善希望というのも取っているのですが、トップが賃金を上げてほしい、これは６割の方。それから、定期昇給をしてほしい、退職金が欲しい、継続雇用にしてほしい、いずれも３０数％の方が答えています。こういう会計年度任用職員の声、要望というのは届いているのか、それに対してどう捉えているのか伺いたいと思います。そのうちの１０人が訴訟を起こしています。","respondent":"宮尾人事課長、丸谷教育総合支援センター長","answer":"期末手当に引き続き、今年度から勤勉手当の支給も開始というところもありますので、そういったところも一定程度、処遇改善というのは図られているものと認識をしています。東京都のスクールカウンセラーが、品川区でも複数名入れ替わっているところではありますけれども、学校から、スクールカウンセラーの変更に伴い何か不都合があったというような報告は、こちらのほうには上がってきておりません。","id":"exchange-163"},{"speaker":"鈴木委員","kind":"質問・要望","question":"子どもを長く見続けている人が本当に解雇されて、それは子どもにとっても大きな影響があるのではないかなと思いますので、そこのところはぜひつかんでいただきたいと思います。教育総合支援センターでも実際、専門職の方で１年で解雇された方からの相談も受けています。こういう働く人の立場を考えて、品川区としても継続雇用ができる制度に改善すべきではないかと思うのですが、いかがでしょうか。","respondent":"宮尾人事課長","answer":"総務省の任用回数の上限を撤廃する通知に対しての対応です。もともと、先ほどの答弁もいたしましたけれども、品川区は、毎年職の必要性を検討して職を設置するという考えでやっておりますので、人によっては複数年、実際に雇用されていらっしゃる方がいるという現実があります。","id":"exchange-164"},{"speaker":"鈴木委員","kind":"質問・要望","question":"総務省もこういう形で出しているわけですから、私はこれをぜひとも真摯に区としても受け止めていただいて、ご検討いただいて、そして、継続雇用ができるようにということで強く求めておきたいと思います。これは、ぜひ推進計画をつくっていただきたいということで求めたいと思います。ぜひ区としてもこの推進計画をつくっていただきたいと求めたいのですが、いかがでしょうか。","respondent":"唐澤特別支援教育担当課長","answer":"特別支援教育の現状につきましては、長期基本計画、総合実施計画などに基づいて行っているところです。先ほどの答弁の中にもありましたとおり、まず方向性については、今後示される教育振興基本計画の中で示していきたいと考えております。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"お願いします。１校、手を挙げているけれども、受入れは１園だけという学校があったり、頑張って３園、うまく工夫をして対応していただいている学校もあるという中で、ぜひこれを進めていっていただくために、そういった受入れがうまくできるような環境の情報とか、工夫の仕方とかを共有していただいて、受入れが進んでいくようにしていただきたいと思いますが、いかがでしょうか。","respondent":"中谷指導課長、荒木学校施設担当課長","answer":"こういった取組が非常に有効、まずスタートとしてとても大事だと考えていますので、区内の学校、幼稚園、保育園に、こうした取組の拡大、促進を促していくために、研修をまた充実させていきたいと考えています。今後も学校改築が続きますので、子どもたちや地域の思い出づくりの一環として、工事期間中ならではの機会を提供できるように、今後検討してまいりたいと思います。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"保幼小の連携、いろいろ取り組んでいただいているのは分かっております。台場がすごくいい事例だということでお話をいただいたので、ぜひ広げていっていただいて、連携をしっかり、手を挙げられるところはぜひ受け入れていただければと思います。小学校のお別れ会の評価ということで、そういった会があれば支援していっていただきたいと考えています。","respondent":"柏木学務課長","answer":"校舎とのお別れのそういう紙代等ですけれども、特段そのために予算を、校舎を閉じるときに取っているということはございませんが、学校からそういうご相談があれば、学務課で相談には乗りたいと考えております。","id":"exchange-167"},{"speaker":"大倉委員","kind":"提案","question":"やはり学校のそういった校舎を思い出として残していくというのはすごい大事だと思っていまして、写真とかで撮って残していくという方法もあるかなと思うのですが、以前もご提案をさせていただきましたが、技術が進んでいる中で、ＶＲとか、今、デジタルツインなんて言われて同じものをデジタル上でという中で、ＶＲを使って学校の校舎をインドアビューなどで見られるようにしていくというのが。","respondent":"荒木学校施設担当課長","answer":"現在実施している学校改築時における歴史保存の取組について、ご説明します。改築校の校舎の昇降口付近に、校歴コーナーやメモリアルスペースといった場所を設けまして、地域や同窓会等の要望も伺いながら、歴代の記念品や卒業制作などを保管できるようにしております。","id":"exchange-168"},{"speaker":"大倉委員","kind":"意見","question":"そこに注釈を、クリックすればいついつの卒業生かとか、そういった文章、また動画も見られるようになりますので、そういったことをぜひ研究して、検討につなげていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"提案","question":"３７７ページ、就学支援費、款別審査最終日、本日も多くの質疑がありましたが、私からはベーシック・サービスの観点から、教育に係る費用の無償化について伺ってまいります。この重要な時期において、わが党は大衆福祉の原点を再確認するとともに、これまで築き上げてきた全世代型社会保障を基盤として、新たな「創造的福祉社会」の構築に挑みます。引用は以上です。改めて伺います。","respondent":"柏木学務課長","answer":"これを今の子どもの数でという試算になりますけれども、５年生ですと区内全体で約４,８００万円、６年生の移動教室で２,１００万円、７年生の移動教室で２,２００万円、修学旅行で１億１,０００万円余という形になるかと思います。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問・要望","question":"修学旅行費の就学援助が満額ではない、そして、修学旅行が終わってから振り込まれるので、経済的に困っている家庭の現実の暮らしに合っていないのではないでしょうか。最後にその手紙を森澤区長へ手渡され、受け取られた区長は、いただいたご要望をしっかり考えていきますと返していたと記憶しています。こちらも改めて伺います。いかがでしょうか。ぜひ無償化を要望いたしますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"移動教室、修学旅行、標準服等の無償化の件です。委員が言われたものにつきましては様々検討をしていますが、大変申し訳ございません、繰り返しの答弁になりますが、今後の予算編成の中で整備していきたいと考えています。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今日は統一したご答弁ということですが、ほぼ、全ての会派からそのような要望が出ておりますので、ぜひ検討を進めていただければと思います。そして、品川区の教育におけるベーシック・サービスとして、このミッシングリンク、最後の欠けている高等教育、大学授業料の無償化のピースをはめていただいて、品川区の教育の無償化を完成させていただきたいと思いますが、最後に森澤区長、いかがでしょうか。","respondent":"森澤区長","answer":"そういった中では、子どもの幸せな未来をしっかりと支えていく、自己実現を望む方向にしっかりと支えていくという意味で、奨学金をどういった形で実現できるのかということを、具体的に検討していきたいと感じているところであります。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"提案","question":"これからも、区民のウェルビーイング向上を目指して、私たちも様々な、議会としても提案をしますので、品川区からも新たなベーシック・サービスの形をつくっていただいて、その発信をお願いしたい。そのことをお願いいたしまして、本日６日目となります款別審査、私の質問を終わらせていただきます。誠にありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-173"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書の３７５ページ、ＰＴＡ関係費、そして、３８１ページ、生徒指導対策等経費、４０１ページの学校改築推進経費、そして、あと学校プール、順不同で伺います。学校プールですが、決算の初日、うちの会派の西村委員から質問がありました。学校プール指導での外部委託の検討の在り方についてです。これを踏まえて、もう一度ご答弁をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"夏季水泳についてですが、水泳連盟の方にも加わっていただいて、子どもの安全管理ですとか、指導、技能の向上を目指すという形で関わりをいただいているところです。","id":"exchange-174"},{"speaker":"まつざわ委員","kind":"確認","question":"テクニカルアドバイザーが教員を支えているというのを確認しました。今、夏季プールのお話もありました。夏休みは教育課程外ですね。半分ぐらいしかやっていなかったですね。そうすると、これは委託料が、たしか人件費なのかな、委託料が１,５００万円だと思ったのですが、例えば半分しか開催していないというと、この委託料の１,５００万円はどういうふうになっているのか、そこを確認させてください。","respondent":"柏木学務課長","answer":"それと、あとその派遣の際に、当日に急な中止の場合は、当然行く人はもう準備していますので、その部分については、その人の人件費は払わなければいけないと考えていますので、そこはスポーツ協会がきちんとと精算して実施しているという形になってあります。","id":"exchange-175"},{"speaker":"まつざわ委員","kind":"質問","question":"そうしますと、結局１,５００万円はお支払いしてやりますと。でも、中止、中止ではないというのは、多分当日でないとほぼほぼ分からないですね。当日が暑いとか雨が降らないとか分からないということは、結局それは、何と言えばいいですかね、やはり中止になろうが何だろうが、お金というのが発生するということですよね。そういうことですね。","respondent":"柏木学務課長","answer":"例えばもう何日かまでは台風が来るとか、そういうのが分かっていれば、もう事前に中止になりますので、そこら辺ではもうお金は発生しないということになりますが、先ほど言ったとおり、今日が暑くて駄目だったという場合については、お金は発生するという形になってあります。","id":"exchange-176"},{"speaker":"まつざわ委員","kind":"質問","question":"でも、これは結局、教育課程外でやるプールの授業であれば、例えばこういう、何というのですかね、夏季プールに関する授業こそ、要は温水プールがある学校でまとめてやったり、例えばスポーツクラブもお願いしてやったり、そういった発想はこの夏季プールには私は該当するのではないかなと思うのですが、そうすれば別に夏季にこだわることもなく。","respondent":"丸谷教育総合支援センター長","answer":"それには教員による引率ですとか、暑い中を今度、移動しなければいけないというような様々な課題もありますので、そうしたことがクリアされれば、実現の可能性も出てくるという認識でおります。","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"授業内の学校プールというのは８０％できているとセンター長からお話がありました。でも、それもカウントされてしまうと多分８０％となるので、やはりしっかり泳いで水の危険を学ぶという教育は大事なので、ぜひ検討していただきたいと思っています。品川区でもこの学校改築というのが進んでいますが、現在までにどのように進んできたのか、またどれだけ改築していない学校が残っているのか、教えてください。","respondent":"荒木学校施設担当課長","answer":"区内における改築の実施状況です。現在までに改築に着手した学校が、小学校、中学校、義務教育学校も含めまして２７校あります。進捗状況といたしましては、４６校中２７校ということで、５９％の改築に着手したという状況です。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"５９％、まだ半分ぐらいですね。そうすると、地域バランスというのはどういうふうに考えるのかなというのは、少し私の思うところがありますので、地域バランスというところで、またいろいろと検討していただきたいと思っています。そうすると、まだこれから今後２５年ですかね、２０年ぐらいかかりますよね。多分、改築が１校２校と考えて、１年１校という……、１年１校でもないか。","respondent":"荒木学校施設担当課長","answer":"今後の学校改築のビジョンですが、現段階では総合実施計画に基づき、１年１校というペースで着手をしています。その際に、委員ご指摘のとおり、将来の児童数減というところも当然訪れるものと考えております。","id":"exchange-179"},{"speaker":"まつざわ委員","kind":"質問","question":"しっかり考えていただいて安心しました。学校改築で、先日、品川建設防災協議会の方の工事見学会、城南第二小学校の工事の見学会に行って改めて思ったのですが、これも工事が６年ぐらいですか、かかってしまうのですね。それで、最近の工期の状況、あと、また工期がどうして長くなってきたのか、またこういう説明会で、保護者から工期が長いことについて心配する声などがあったのか、教えてください。","respondent":"荒木学校施設担当課長","answer":"大きくは３点かなと、私のほうでは認識をしております。１点目は、校舎の規模がやはり過去に比較して大きくなってきていることです。これは、就学人口増への対応や、特別支援教育の充実化などに対応するためです。２つ目は、建設業働き方改革の推進が進められていることです。","id":"exchange-180"},{"speaker":"まつざわ委員","kind":"質問","question":"だから、もう遅刻すると先生に言いなさいよと言っても、先生に言うとやはり怒られるから言いたくないと言って、もう全力で走っていって、うちだけかなと思っていたのですが、周りの保護者に聞いてもそういう生徒が非常に多くて、やはり安心・安全の部分が心配かなと思ったのですが、こういうときというのはどういう対応をしたらいいのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"課題としては認識いたしました。学校には情報提供するとともに、ぜひ保護者の方から各学校、顧問にお問合せをいただいて、改善に努めていければと思います。","id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6859#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":117794,"voices":401}},{"id":"r06-20241021-4","meetingId":"r06-c-settlement","date":"2024年10月21日","dateIso":"2024-10-21","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"初めに、品川区における令和５年度決算について質問いたします。本決算は、森澤区長が令和４年１２月にご就任され、「新時代のしながわ」スタート元年として、区民の幸せのために各施策を展開してきた結果であります。特別区税収など歳入決算額の推移と併せて、令和５年度決算に対する区の評価についてお聞かせください。","respondent":"久保田企画経営部長","answer":"地域経済の活性化に対しましても、物価高騰対策として国の臨時交付金等を活用し、省エネルギー対策設備更新助成金の実施や、プレミアム付区内共通商品券の販売等により、事業者や区民生活を支援してきたところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"意見","question":"今、様々な施策をお聞かせいただいた元となります、令和５年度、区は４つのビジョンを掲げております。これらを各施策に落とし込み、積極的に展開してきたと認識しております。新規事業の実施に当たっての区の考え方、また財源の確保についてお聞かせください。","respondent":"久保田企画経営部長","answer":"新規事業の実施に当たっての区の考え方等ですけれども、令和５年度予算は、区民と共に進める新しい品川区政を実現するためのスタートの年と位置づけ、未来を見据えた積極予算を編成したところです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"新規事業と財源の確保についてお伺いさせていただいたのですが、様々、新規事業に関しまして実施していただいていることは理解しております。ただ、予算執行の過程においては、年度途中における不測の事態等により補正予算を組まれることもあるかと思います。どのような考え方の下に補正予算を編成されているのか、改めて区のお考えをお聞かせください。","respondent":"久保田企画経営部長","answer":"昨今は、様々な緊急事態・事象への対応が強く求められておりまして、我々としましても、こうした事態に対処するために補正予算を編成し、議会のご審議を頂きながら、区民の安全・安心を守るための施策を実現していく必要があると考えております。","id":"exchange-003"},{"speaker":"西村委員","kind":"確認","question":"様々、確認させていただきました。事業のスクラップの考え方について伺ってまいりたいと思います。一方で、特に長年続いている事業などは廃止することに様々なハードルがあり、現状では、ほとんどの自治体において積極的に進められていないと認識しています。初めに、区では事業のスクラップの必要性をどのように捉えているのか、伺いたいと思います。スクラップに向けた取組の状況についてお知らせください。","respondent":"久保田企画経営部長","answer":"事業のスクラップにつきましては、健全財政の維持につながるとともに、多様化する区民ニーズに対応するため、新規事業の立ち上げや必要な事業を継続的に行うことを可能とするなど、重要な取組であると認識しています。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"この事務事業評価の実施により、全事務事業を見直された結果として約２３億円が削減され、それを原資として、必要な事業・サービスに振り向けられたことは評価いたします。ここでお尋ねいたします。この削減された約２３億円については、どのような視点で算出されたものなのかをお知らせいただきたいと思います。どのように捻出していかれるのか、現状のお考えをお聞かせください。","respondent":"久保田企画経営部長","answer":"令和６年度におきましても、一般会計予算の１％、約２０億円を捻出することを目標として、全ての事務事業を対象に課題や改善点を洗い出し、事業の目的や成果、費用対効果、さらには区民ニーズなどを含めて各事業を分析・検証し、多角的・客観的に評価を行いまして。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"事務事業評価による予算削減の考え方については理解しております。事務事業評価も昨年度、約１０年ぶりの実施ということで、この間の社会情勢や区民ニーズも大きく変化してきております。廃止する事業や見直しする事業が一定以上あったことから、昨年度、２３億円の削減ができた。今年も２０億円の削減を目標とするということも理解はしております。その点、また見解をお聞かせいただきたいと思います。","respondent":"久保田企画経営部長","answer":"こうした限られた予算の中で効果的・効率的に施策を推進していくためには、役割を終えた事業などを大胆に見直していかなければならず、スクラップ・アンド・ビルドを継続的に実施し、新たな施策に財源を捻出し、振り向けていきたいと考えているところです。","id":"exchange-006"},{"speaker":"西村委員","kind":"提案","question":"様々、事業のスクラップについてお伺いしたいと思って伺ってまいりました。区は令和５年度において３つの無償化を進め、令和６年度においては学用品の無償化に取り組んでいます。こういった懸念を解消するために、ぜひ予算編成や事務事業評価にサンセット方式を取り入れてはいかがかとご提案いたします。サンセット方式の課題も含めて、区の考えをお聞かせください。","respondent":"久保田企画経営部長","answer":"今後の予算編成や事務事業評価を進めていく中で、他自治体の取組などを調査研究しつつ、検討していきたいと考えているところです。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問・要望","question":"物価高騰や自然災害の懸念など、先の見通しがしづらい時代において、区民ニーズに合わせた柔軟な施策を実施していくためにも、ぜひ全庁一丸となってスクラップ・アンド・ビルドを進めていただきたいと要望いたします。続きまして、款別でも質問させていただきました５歳児健診について伺います。区内の児童発達支援教室の方に伺わせていただきました。","respondent":"阿部健康推進部長","answer":"一方、３歳児健診の時点では発育・発達の個人差がまだ大きいため、集団における振る舞いや社会性などについて、子どもごとの支援の必要度の見極めがまだ困難であることが課題であると認識しております。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問","question":"せっかく総括の機会でありますので、今、母子保健について担当課から伺わせていただきましたが、課を越えての取組をお願いしたいと思います。横断的にという点におきましても、教育についても伺ってまいりたいと思いますが、５歳児健診は年中で実施しますので、就学相談は年長児となります。就学相談の課題、そして就学後の現在の課題があればお聞かせください。","respondent":"米田教育次長","answer":"就学相談は、今年度は５月から１１月までが受付期間となりまして、保護者からの申込み制となっております。就学時健診は１０月から１１月に実施しているため、そこから就学相談を進める場合、手続や検討を含め、期間が短くなる現状があります。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"先日の新聞で、保育園にて５歳児健診を実施する大田区の事例が掲載されました。区内事業者の方からも伺っております。こちらはこれから検討される段階ですので、要望とさせていただきたいと思います。次に、国際交流について伺ってまいりたいと思います。大変有意義な時間だったと伺っております。これまでの３０年の振り返り、そしてこれからの未来の３０年をどうつくっていくのかを伺います。","respondent":"柏原区長室長","answer":"今後ですけれども、さらなる国際交流の発展を目指しまして、様々な見地から検討いたしまして交流を促進いたし、異なる文化・価値観を超えて人間関係を構築する力を身につけた品川区の子どもたちが、世界へ羽ばたき、国際社会発展に寄与できるよう。","id":"exchange-010"},{"speaker":"西村委員","kind":"提案","question":"１９９３年にオークランド市と友好都市を締結してから３０年になります。各区立校から１名と、公募枠を設けていただいていると思います。子どもたちが８０人近く集まったと伺っております。ホッケーを通じた国際交流事業の強化を提案したことで実現した、オークランド市とのスポーツ交流は初めてとなります。語学だけではなく、文化、芸術、スポーツの交流も求めますが、区の見解を伺います。","respondent":"柏原区長室長","answer":"この事業の参加枠を増やしていくといったところですけれども、実施体制や経費のところ、また安全管理などもありますので、こういったことも踏まえまして、国際友好協会と共に総合的に検討してまいりたいと考えております。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"これまでの関わりと歴史があったからこそ、できていることだと考えます。少し難しい要望かもしれませんが、対象地を広げるということもご検討いただきたいと考えています。例えば、アジア圏の交流都市、タイ、ベトナム、シンガポールなどはビジネス的な交流が進んでいます。こちらもぜひご検討いただきたいと考えています。以上で終わります。ご答弁いただいてもよろしいですか。","respondent":"柏原区長室長","answer":"対象地を広げる検討といったところのご質問です。今、委員よりご紹介もございましたけれども、英語圏にとらわれないアジアの国々との交流というところもあろうかとあります。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に、子どもたちのこれからの国際交流、グローバルな子どもたちを育てていくということを考えると、いろいろな取組が国際交流で考えられると思いますので、文化、芸術、そしてスポーツと、ぜひとも様々な発想で取組をご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"澤田副委員長","kind":"質問","question":"私からは、西村委員に続きまして質問します。３５人のクラスであれば、三、四人ほどが在籍していることとなります。そこで伺います。教職員、保護者、当事者である児童などから、発達障害教育支援員が配置されてから寄せられているお声はありますでしょうか。区としてどのような成果があったとお考えなのか、また課題などもありましたらお聞かせください。","respondent":"米田教育次長","answer":"発達障害教育支援員全校配置後のお声ですが、副委員長からもご紹介のありましたとおり、１日７時間掛ける週５日の配置となりまして支援の時間が広がったこと、毎日配置されることで時間割や授業に応じて柔軟に対応できることなどが挙げられております。","id":"exchange-014"},{"speaker":"澤田副委員長","kind":"確認","question":"児童や教職員の先生方にとって大変よい効果が出ていること、また課題も含めて確認できました。今年度からは発達障害教育支援員が毎日１人入ってくださっていますが、１校に１人では足りないというお声も伺っております。派遣に関する情報の提供なども併せて行えば、よい循環が生まれるのではないでしょうか。そこでお伺いします。支援を行う人材の拡充の強化についてどのようにお考えでしょうか。","respondent":"米田教育次長","answer":"認知症サポーター養成講座のような仕組みについて、障害特性の理解や対応において有効なものであるかとも考えてありますので、今後の在り方につきましては、支援員を含めまして、区で実施している特別支援教育に係る施策などについて、引き続き。","id":"exchange-015"},{"speaker":"澤田副委員長","kind":"質問","question":"様々周知していただき、人材確保へもご努力されていることがよく分かりました。ここまでは、特別な支援を必要とする児童に対しての支援員についてお伺いしてきました。そこでお伺いします。児童に対して、発達障害をはじめとした障害についての理解教育は現状どのように行われていますでしょうか。理解教育の必要について、区としてはどのようにお考えでしょうか。お聞かせください。","respondent":"米田教育次長","answer":"発達障害を含め、他者の多様な個性を尊重し、互いに認め合うことは重要なことと認識しておりますので、引き続き、こうした事例を校長連絡会や特別支援教室連絡会等の機会で共有しながら、各学校での取組につなげてまいります。","id":"exchange-016"},{"speaker":"澤田副委員長","kind":"質問","question":"先ほどの西村委員の総括質疑にもありましたが、５歳児健診でまず気がつくことも大変重要でありますけれども、それとともに、受容するには、まず発達の特性について理解することが第一歩です。そこで伺います。本区には、発達障害児に特化したリーフレットなどはあるでしょうか。併せて、保護者に向けた発達障害児の理解についてどのようにお考えでしょうか。","respondent":"米田教育次長","answer":"今後、教育委員会で作成しております特別支援教育リーフレットをホームページに掲載するなど、引き続き、区民の方々への周知を行い、理解啓発に努めていくとともに、福祉・就学前施設等、関係部門との連携も図ってまいります。","id":"exchange-017"},{"speaker":"澤田副委員長","kind":"質問","question":"就学相談の説明会の回数・実施場所を増やし、より丁寧に対応してくださっているとのことでしたので、障害を前向きに受け入れられる保護者が増え、早期対応の機会につながり、生きづらさを少しでも軽減できる児童が増えることを願っています。発達障害に特化したリーフレットをご検討いただければと思いますが、いかがでしょうか。通称「しなぽけ」との連携についてなど、区のお考えをお聞かせください。","respondent":"米田教育次長","answer":"発達障害につきましては、今後も説明会や研修会などの機会を捉え、区民の方や教職員への理解啓発に努めてまいります。発達障害児に特化したリーフレットにつきましては、関係各課とも連携し、既存の刊行物の活用など、その作成の在り方について検討を行ってまいります。","id":"exchange-018"},{"speaker":"澤田副委員長","kind":"質問","question":"続きまして、先ほどの質問の中で触れましたしながわこどもぽけっとについてお聞きします。その要因としては、チラシを母子手帳配付時に配ったこと、内容の充実が功を奏しているのではないでしょうか。そこでお聞きします。回数増加の要因の区としての分析、またどのような年代の子どもを持つ保護者が多いのか、保護者からどのような声があるのか、現在のアプリの周知方法も具体的にお知らせください。","respondent":"佐藤子ども未来部長","answer":"これらの対応により、利用者の満足度が高まり、結果としてアクセス数の増加につながったものと分析しております。次に、利用する保護者の児童の年代ですが、登録されている児童の年齢層は、現在、未就学児７９％、小学生１８％、中学生以上２％となっております。","id":"exchange-019"},{"speaker":"澤田副委員長","kind":"意見","question":"様々周知を行っており、また大変多くの方が満足しており、必要な支援の情報なども提供されていることが分かりました。そこで、さらに公園の写真掲載や、子どもに人気の水遊びができるかどうか、砂場・駐車場の有無、ボール遊びが可能かどうか、近くにカフェやコンビニがあるかなど、さらに詳しく情報を増やすのも利便性向上につながると考えます。公園での水遊びを望む保護者の声も多く耳にしております。","respondent":"佐藤子ども未来部長","answer":"最後に、公園や遊具、近接情報の紹介などの充実につきましては、多くの子育て世帯が必要な情報の一つと考えますので、関係部署と連携しながら検討を進め、サービスのさらなる向上に努めてまいります。","id":"exchange-020"},{"speaker":"澤田副委員長","kind":"質問","question":"続きまして、「マイガーデン」農業体験についてお伺いします。品川区では平成１５年から「マイガーデン」が設置され、現在では大井町と西五反田に整備されています。大変好評と伺っており、今年度は「子ども青空農園」を第二庁舎で開催、また「マイガーデン」の３園目を検討されています。","respondent":"溝口防災まちづくり部長","answer":"「子ども青空農園」につきましては、庁舎のように大きな建物で、かつ一定の広さを有する屋上などが必要となり、今回は第二庁舎の屋上緑化スペースを活用するなどの工夫をすることで実施することができました。","id":"exchange-021"},{"speaker":"澤田副委員長","kind":"質問","question":"「マイガーデン」、「子ども青空農園」ともに大変好評であるということが、改めてお伺いできました。ただ、適地というのが難しい状況の中で、３園目を楽しみにしている方もたくさんいらっしゃいますけれども、４園目と続けて造っていただく上で、例えば区有施設の屋上を使っていただくということなど、お考えはいかがでしょうか。今後の方向性も含めてお聞かせください。","respondent":"久保田企画経営部長","answer":"区有施設の屋上に、青空の「マイガーデン」の設置ということのご質問ですけれども、区有施設の屋上には現在、空調設備の機器などというものがたくさん置かれているということで、なかなかそのようなものを活用するスペースが確保できないということ、それと安全管理上。","id":"exchange-022"},{"speaker":"澤田副委員長","kind":"質問","question":"以前、品川女子学院に「区民と議会の交流会議」でお伺いした際にも、お話しした生徒の皆さんは、「農業体験をしたい」、「野菜を育ててみたい」とおっしゃっていました。品川カブも育てております。学校によっては、稲についても育てて、それを自分たちで収穫して調理実習で食べてみたりというようなことも行っているとお聞きしています。併せて、屋上を活用している学校があるのかもお聞かせください。","respondent":"久保田企画経営部長、米田教育次長","answer":"その場合には、ただ屋上ということで限定ではなくて、いろいろな場所がありますので、新規施設を整備するですので、施設の構造や費用の面から総合的に判断して検討していかなければならないと考えているところです。区立学校における菜園の整備状況についてご質問いただきました。小学校と義務教育学校を中心に、全４６校中３２校で設置しております。設置場所は校庭内だけでなく、敷地の状況に応じて校舎屋上に設けている学校もあります。","id":"exchange-023"},{"speaker":"澤田副委員長","kind":"質問","question":"お伺いしたところ、全校でというわけではなく、いろいろな学校施設で、屋上やグラウンドを使って作物を栽培されているということでしたけれども、全校ではない中で、ぜひ品川区の小学生みんなに食育や、食べるものを育てるという喜びを理解していただくためにも、今後とも屋上活用なども含めてご検討いただければと思います。どうぞよろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"ゆきた委員","kind":"提案","question":"さて、耳マークが、コミュニケーションの配慮と理解を求めていくシンボルとして、聞こえない、聞こえにくい人たちを社会一般に広く知ってもらうため、１９７５年に名古屋市の難聴者の発案により制定され、全国各地で普及が進められていますが、一般人を対象とした内閣府の認知度調査では１２％であり、まだまだ知られていないのが現状です。ご見解を伺います。","respondent":"寺嶋福祉部長","answer":"本定例会の補正予算では、福祉部各窓口、それから在宅介護支援センター、支え愛・ほっとステーションに計３０台配置するほか、個人情報を扱う庁舎内の窓口への貸出し用に５台分の計上をしていますので、ご議決を頂きましたら速やかに設置を行い。","id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"厚生労働省によると、現在、難聴の患者数は約１,４３０万人、国民全体の約１０％といわれ、国立長寿医療センターによると、聴力レベル２５デシベル以上の難聴有病率は６５歳以上で急激に増加し、７５歳から７９歳では、男性７１.４％、女性６７.３％と報告されています。そこで、都の事業の説明をいただくとともに、両耳の補聴器が購入できるよう、費用助成の拡充を求めますが、区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"昨今の経済状況につきましては十分認識していますので、東京都の補助スキームとの相違点、具体的には所得要件等の違いがありますので、こちらとバランスを取りつつも、さらなる社会参加支援に向けて、拡充について検討を進めていきたいと考えております。","id":"exchange-026"},{"speaker":"ゆきた委員","kind":"提案","question":"バランスを取りつつとありましたが、ぜひ検討していただければと思います。２点目はベーシックサービスの観点から、さらなる教育費の無償化を求めて質問します。会派として、本年の予算特別委員会において、教育のベーシックサービスとして修学旅行費など校外での体験活動の費用の無償化を提案していましたので、この事業展開を高く評価しています。そこで、改めて伺います。","respondent":"米田教育次長","answer":"移動教室等の校外での体験活動に関しまして、各家庭での平均負担額および、無償化に当たっての必要額の見込みについてお答え申し上げます。","id":"exchange-027"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"金額のそれぞれの確認ができました。款別審査では、我が会派からの質問で、子ども食堂フォーラムで読み上げられた１人の少女の区長への手紙の内容を通して、体験活動への参加や標準服、いわゆる制服の購入に、経済的に困難を伴うご家庭があることをお伝えしました。中学校・義務教育学校の標準服、いわゆる制服も教育のベーシックサービスにほかならず、標準服代金の無償化を要望しますが、ご所見を伺います。","respondent":"米田教育次長","answer":"修学旅行費や標準服代等、さらなる無償化とのご提案につきましては、今後の予算編成作業の中で考え方を整理し、検討を進めてまいります。","id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"予算編成の整理の中で、ぜひ検討を進めていただければと思います。そこで、子どもの未来の育成のため、改めてベーシックサービスの考え方とウェルビーイングの関係について、どうお考えか伺います。教育段階におけるベーシックサービスを完成させる所得制限のない高等教育、大学と授業料の無償化である、品川区独自の給付型奨学金の創設を求めますが、ご所見を伺います。","respondent":"佐藤子ども未来部長","answer":"区独自の大学生向け奨学金の実施につきましては、子どもの幸せな未来、自己実現をしっかり支えていく、そういった意味として、どういった形で実現できるのか、所得制限によらない奨学金の在り方について具体的に検討していきたいと考えております。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ区民の幸せの実現のために、前向きに検討していただければと思います。最後に防災対策として、耐風診断について質問します。耐風診断とは、建物、特に屋根が強風に耐えられるかどうか、耐風性能を評価するための診断であり、近年、強風による災害が増加しているため、国では建物の安全性確保のために、屋根の耐風診断および耐風改修に関する事業を実施していると認識しています。","respondent":"鈴木都市環境部長","answer":"この被害を受けまして、令和４年度より、屋根の耐風診断および改修補助事業が国より開始され、区としましても、強風による住宅屋根の被害防止に効果があるものと認識しています。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"提案","question":"品川区でも一定の被害があることを確認しました。さて、５年前、千葉県を中心に甚大な被害のあった台風１５号では、記録的な暴風で８万棟の被害がありました。そこで、品川区において風害による被害を減災するためにも、国の補助事業を活用した耐風診断・耐風改修助成の実施を提案します。併せて耐風診断、耐風改修の周知について求めますが、区の見解を伺います。","respondent":"鈴木都市環境部長","answer":"区では現在、屋根の安全化に関する直接的な事業は実施していないところですが、一方、瓦屋根を含む老朽木造住宅の耐震化や不燃化を、現在、強力に推し進めているところです。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"質問","question":"近年増加する風水害に対して、ぜひ前向きに進めていただければと思います。これで私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"ゆきた委員に引き続き、品川区議会公明党の総括質疑を行います。初めに、豪雨による水害対策について伺います。都は令和５年１２月に東京都豪雨対策基本方針を改定し、気候変動による豪雨の激甚化に対応するため、目標降雨を１時間７５mmの浸水被害防止から１０mm引き上げ、８５mmに改めました。品川区では都の改定を踏まえ、令和６年度に品川区総合治水対策推進計画の改定作業を開始しています。","respondent":"溝口防災まちづくり部長","answer":"流域対策につきましては、民間、公共、各施設の幼稚園内に貯留浸透施設を整備することで、時間１０mm相当分の雨水の河川や下水道への流出を減らし、浸水被害の軽減に資する取組であり。","id":"exchange-033"},{"speaker":"塚本委員","kind":"提案","question":"今ご答弁いただきました、６mmの目標についてもほぼ達成しているというところで、これはすばらしい、区としての成果だと思いますけれども、その中でも７割が民間の対応によって達成されているというところをお伺いいたしました。そして、さらなる民間の協力が得られるような施策展開を検討すべきと考えます。区の見解を伺います。","respondent":"溝口防災まちづくり部長","answer":"今年度より新たなプロジェクトが開始されているところです。区といたしましても、今年度、都の取組について情報収集し、活用を図るとともに、様々な場面を捉えまして民間の取組をＰＲするなど、民間の協力を一層得られるよう検討を行っていきたいと考えているところです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後の下水道における浸水対策について、区の考えを伺います。地盤改良が必要になった土地に住居を新築する際の区民の負担について、区として実態を把握し、負担軽減策を講ずるよう求めます。区の見解を伺います。近年の豪雨の激甚化に伴い、浸水被害のリスクが高まっていますけれども、避難情報緊急通知コールの登録対象地域の見直しについて区の見解を伺います。","respondent":"溝口防災まちづくり部長、鈴木都市環境部長","answer":"区といたしましても、都の打ち出した時間８５mm降雨への対応として、これからも下水道事業を受託したり、貯留浸透施設を整備するなどの、時間１０mm降雨相当分の流域対策を促進したり、様々な対策を実施していくことで。しかしながら、区建築課等の窓口において、近隣の支持地盤データの提供や助言・アドバイスの実施など、区としましては引き続き、必要な支援を行ってまいります。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"高齢者・障害者福祉の人材確保について伺います。福祉人材の人手不足は深刻です。外国人にとって日本語の試験は大きな壁であり、介護のスキルは申し分なくても、試験にパスできずに帰国せざるを得ない事態を避けるため、区として日本語習得も含めた資格試験合格のための支援策を求めます。事業所の負担を軽減する支援策について、区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"外国人雇用を進める上では、こういったあたりの支援が大変重要だと考えておりますので、こちらの点につきましても検討課題として認識しています。","id":"exchange-036"},{"speaker":"塚本委員","kind":"提案","question":"やはり様々、外国人の方の力を借りながら、区内事業者が介護事業所としての人材を確保しているというところが分かったと思いますので、今提案したことについての検討課題ということでございましたけれども、着実に成果の上がるような形を進めていただきたいと思いますので、よろしくお願いいたします。これまで品川介護福祉専門学校で外国人が入学した実績についてお知らせください。区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"この両面を鑑みまして、現在、区と介護学校との間で外国人留学生の受入れ策について意見交換を行っているところです。そのような学生を支援する団体の聞き取り等も始めておりますので、どのような取組が可能であるか、引き続き情報収集に努めていきたいと考えています。","id":"exchange-037"},{"speaker":"塚本委員","kind":"提案","question":"品川区では、年１回の同行援護従事者養成講座を開催しています。週２０時間を超える同行援護従事者に、都が補助している１万円に加えて、今年度から区が１万円の上乗せ補助をしています。同行援護の資格取得のための研修は約２万円の費用がかかりますが、区内介護事業所で働く介護士に対し、同行援護研修費を補助し、同行援護従事者を増やす試みを提案します。区の見解を伺います。","respondent":"寺嶋福祉部長","answer":"実際の支援の仕方も含めてなのですけれども、資格取得そのものも大変重要なのですが、実際に取得した資格を使ってサービスにつなげていただくということが最も重要だと考えておりますので、どのような支援をすることが一番効果的であるのか。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"アピアランスケア事業について伺います。現在、都内では１０の医療施設、全国では５０を超える医療機関で導入され、既にこの治療を受けた区民もいます。専用キャップを助成対象品に加えるよう求めます。助成上限額と申請回数についても、都の上限額１０万円と２回まで申請可能としていることを最大限に活用し、拡充するよう求めます。それぞれ、区の見解を伺います。","respondent":"阿部健康推進部長","answer":"現在のところ、助成の拡充を求める声は届いておりませんけれども、１人の方が複数品目を購入するケースなどもありますので、申請者のニーズをよく酌み取った上で、支援の拡充について検討してまいります。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"令和６年都議会第３回定例会の公明党代表質問で、アピアランスケア事業の対象を、がん治療に伴うものだけでなく、片目失明者などにも対象拡大するよう求めたのに対し、都からは、外見が変化してもその人らしく生活が送れるよう取組を推進していくと、前向きな答弁がありました。機を逸せず、区としてアピアランスケア事業の対象者拡大を検討するよう求めます。区の見解を伺います。","respondent":"阿部健康推進部長","answer":"しかしながら、一方、がん以外の疾患におきましても、エピテーゼ等、アピアランスケアを必要とする方への支援の必要性については、区も認識しております。今後、都や他区の動向を注視しつつ、支援の拡充については検討してまいります。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問","question":"しながわ未来（無所属・立憲・ネット）会派を代表しまして、松永よしひろ副委員長と共に総括質疑を行わせていただきます。令和５年度の決算では、医療連携推進費は健康課、災害時応急物資確保費は防災課が所管しておりました。その事業の概要について教えてください。今年度、地域医療連携課が新設され、この２つの事業が移管されたと伺いました。さらに、地域医療連携課の目的についても併せて伺います。","respondent":"遠藤健康推進部次長","answer":"地域医療連携課の設立の経緯ですが、大きく２つございまして、１つは、コロナ禍の対応を総括する趣旨で検証いたしました、新型コロナウイルス感染症対応の検証と、健康危機管理体制の基盤整備検討報告書の中において。","id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問","question":"様々ご説明ありがとうあります。日本看護協会、２０２１年看護職員実態調査の結果によると、新型コロナウイルス感染症の感染拡大に伴って受けた影響として、８割近くが自身への感染の恐怖や不安を感じ、次いで職場・労働環境の悪化、自分自身に対する差別や偏見、子どもが通う学校・保育園への休校の対応などが挙げられ、長引く感染症対策で心身に疲労が深まる様子が伺えました。そこでお伺いいたします。","respondent":"遠藤健康推進部次長","answer":"現在といたしましては、いわゆる連携して取り組む事項、それから情報交換、それからそれぞれの要望や相談事項など、基本的には制限を設けずにざっくばらんに話していこうという形でやっておりまして、それぞれ１回ずつ開催を既に行っておりまして、医師会につきましては、この後。","id":"exchange-042"},{"speaker":"ひがし委員","kind":"質問","question":"地域医療連携課ができたことによって、今までより密に会議等で話が進められると認識いたしました。そこでお伺いします。地域医療におけるＩＣＴ活用についての区の考えを教えてください。医師会では、令和５年度から東京都の在宅医療推進強化事業の助成を受け、相談窓口の設置に加え、２４時間診療体制の構築など、在宅医療推進に向けての取組を行ってくれております。","respondent":"遠藤健康推進部次長","answer":"来年度までは補助金を使って医師会で進めるという形になりますけれども、今後につきまして、区としてはそれについてどのような形で関わっていけるかというのは、話を聞いて検討していくような形になろうかと思っているところです。","id":"exchange-043"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは要望とします。年齢が判明している１万５,６８１人のうち、６０歳以上の高齢者は６６.１％を占めています。災害関連死の死者２,６８８人のうち、６６歳以上が２,３９６人と、全体の８９.１％を占める。障害者の死亡率については、総人口に対する死亡率が１.０３％であったのに対し、障害者の死亡率は２.０６％と約２倍であったそうです。","respondent":"寺嶋福祉部長、遠藤健康推進部次長","answer":"個別避難計画の状況ですが、まず障害者からご説明しますけれども、対象者は、身体障害者手帳１級から３級、愛の手帳１度から２度の方。作成している方ということですが、日頃から支援をしている相談支援員の方が作成に当たっております。こちらも最初、窓口でアンケートを取りまして、その中から希望者という形になりまして、昨年からの実施で最終的には５０件の作成が行われたところです。","id":"exchange-044"},{"speaker":"ひがし委員","kind":"確認","question":"状況について把握することができました。前回確認したときよりも大分進捗が進んでいると実感しております。ただ、こちらの個別避難計画というのは、作成するだけが目的ではなく、こちらを活用するというところが次のステップになるのかなと実感しております。区の考えをお聞かせください。現在どのように進めているのでしょうか。こちらについても併せてお答えください。","respondent":"寺嶋福祉部長、滝澤災害対策担当部長","answer":"作成の段階で相談支援員、それからケアマネジャーがモニタリング等も行っておりますけれども、こういった段階で細かく避難方法などといったものについてもしっかり周知を図っていくことが必要だと考えております。いずれにしましても、災害弱者と言われます避難行動要支援者の支援体制を万全にできるよう、さらに検討を具体化していきたいと考えております。","id":"exchange-045"},{"speaker":"ひがし委員","kind":"質問・要望","question":"様々課題があるということについても把握させていただきました。しながわ防災学校に、私も地域の方と共に参加させていただいた経験があります。そのような課題についても、ぜひ区民の皆様と相談をしながら、そして福祉部とも連携をしながら進めていただきたいとお願いします。そちらをお願いさせていただきまして、私からの質問は以上で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"松永副委員長","kind":"質問","question":"初めに２０２５年問題について伺いたいと思います。そこで、深刻な問題とされるこの労働力について伺いたいと思います。本区では、２０２５年には６５歳以上の方がおよそ何人ぐらい予想されておりますでしょうか。そこで、なぜ６５歳以上について伺ったかといいますと、６５歳になりますと、やはり定年退職される方が多く、また、その人数の方がほぼ退職されるのはないかと危惧しております。","respondent":"川島地域振興部長","answer":"区としても、いわゆる人生１００年時代などと言われておりますが、そちらを見据えまして、ご指摘の６５歳以上の方でも、働く意思と能力のある方々には引き続き、生きがいと喜びを持って地域社会で活躍していただくことが望ましいと認識しています。","id":"exchange-047"},{"speaker":"松永副委員長","kind":"質問","question":"品川区の高齢化、６５歳以上ということです。６５歳の方は８万人ということでございまして、全体の２０.１％ということで、全国的にはかなり低いほうではないかと考えています。シルバー人材センターについて伺うのですけれども、現在、シルバーセンターに雇用として登録されている数について伺いたいと思います。そして、シルバーセンターの中でどのぐらいの職種があるのか、併せて伺いたいと思います。","respondent":"川島地域振興部長","answer":"職ということですが、センターで受注している主な就業内容としましては、軽作業分野、広報紙等の配布や内職作業など、それから技能分野、植木の剪定や畳の張り替えなど、事務・管理分野、施設管理業務、それから簡単な事務作業などがありまして。","id":"exchange-048"},{"speaker":"松永副委員長","kind":"質問・要望","question":"約２０種類ぐらいということで伺いました。実は先日、地域の方からご要望を受けまして、ＰＴＡの方も年々減ってきているという状況で、登下校の交通安全指導員の方が不足されているそうです。こうしたご要望にもぜひ応えていただきたいと考えていますので、これは要望で終わらせていただきたいと思います。次に、ドッグランについて伺いたいと思います。そこで、愛犬しつけ教室について伺います。","respondent":"溝口防災まちづくり部長","answer":"愛犬しつけ教室の実績といたしましては、令和３年度は１０回、１２５人、令和４年度は１４回、１５６人、令和５年度は１６回、１７８人の方にご参加いただいているところです。","id":"exchange-049"},{"speaker":"松永副委員長","kind":"質問・要望","question":"こうした人数と回数を確認させていただきました。これは年々増えているということを見て取れるかと思います。そこで今、実際、愛犬しつけ教室と併せて、現在、仮設のドッグランを試行実施しているかと思います。この状況についても、同じく回数と人数を、もし計算してあれば教えていただきたいと思います。","respondent":"溝口防災まちづくり部長","answer":"令和５年度から愛犬しつけ教室の開催に合わせまして、仮設のドッグランの試行実施をしています。令和５年度の実績といたしましては、しながわ中央公園、東品川海上公園、戸越公園の３公園で計８回、実施できているところです。","id":"exchange-050"},{"speaker":"松永副委員長","kind":"質問・要望","question":"仮設のドッグランの実績を理解いたしました。そこで、愛犬しつけ教室の利用者からアンケートを取っていただいているそうですが、主にどういった声が上げられておりますでしょうか。飼われている犬の頭数を考えますと、犬と遊べる場所については、まだまだ足りないかと感じております。併せて、恒久的なドッグランの設置を要望いたしますが、いかがでしょうか。それぞれお答えください。","respondent":"溝口防災まちづくり部長","answer":"ドッグランの整備につきましては引き続き、愛犬しつけ教室の利用者の声、またペットを連れていない公園利用者や周辺にお住まいの方といった方々の意見を広くお聞きしながら、ドッグランの設置に向けて、引き続き検討していきたいと考えているところです。","id":"exchange-051"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひ、こうした区民の声を実現していただきたいと思います。そう思われる方が増えてきていることを理解していただき、ぜひ今後、恒久的なドッグランの設置を要望し、次の質問に移りたいと思います。次に、ペット同行避難について伺います。そこで伺いますが、もし万が一、飼い主の安否が確認されず、ペットのみが発見された場合、区としてどのような対応をされているのでしょうか。併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"都の災害時における動物愛護管理対応マニュアルにおきまして、被災動物の保護は、東京都が東京都獣医師会、動物関係団体などと共同して設置し運営する動物救護本部が中心となって行い、東京都はこれを支援するということになっておりまして。","id":"exchange-052"},{"speaker":"松永副委員長","kind":"質問・要望","question":"そこで、避難所生活を送る中で、私たち人間も体調を崩すこともあります。そしてペットも同様に、ペット同行避難ができたとしても、その避難所においてペットが体調を崩した場合、区としてはそうした対応をどのようにされているのでしょうか。犬や猫を避難させた方たちへの受入れ体制は大丈夫なのでしょうか。併せて伺いたいと思います。","respondent":"滝澤災害対策担当部長","answer":"ペットの同行避難の際は、飼い主の方が必要な物資を持参するというものが基本になっておりますけれども、実際、災害が起きまして家屋等が全壊したような場合には、必要なペットの備蓄品などを持って来られない場合もありますので、併せてペット用の避難の備蓄の充実を含めて。","id":"exchange-053"},{"speaker":"松永副委員長","kind":"確認","question":"すみません。確認なのですが、先ほどの３４か所については全部、ペット受入れ可能ということだったのでしょうか。それで、備蓄についてもペット用品、例えばどういったものなのでしょうか。トイレやドッグフードといった食べ物等を含めて、大体どのぐらいなのでしょう。３日分なのか、人間と一緒なのか、もしあれでしたらお答えいただければと思います。","respondent":"滝澤災害対策担当部長","answer":"ペット用の備蓄品ですけれども、ペットのゲージやトイレシート、猫砂などを備蓄している状況でございまして、これは現在、ペットが、例えば犬であると区内に１万３,０００頭、猫もほぼ同数と見積もっておりますけれども、区民の避難も約２割が避難所に避難されるということで。","id":"exchange-054"},{"speaker":"松永副委員長","kind":"質問・要望","question":"そうした中で、やはり、ぜひペット同行避難をされる方は必死で助けを求めて来られておりますので、そうしたことも含めて、なるべく全ての方が受け入れられるような体制づくりをしていただきたいと思います。最後になります。そうしたところで質問なのですけれども、現在、この費用負担の軽減対策や、アスベスト調査・除却費用、目視調査について、それぞれ３年間の実績を伺いたいと思います。","respondent":"鈴木都市環境部長","answer":"アスベスト自体の除却助成につきましては、令和３年が１件、令和４年が２件、令和５年が１件。それから事前調査の派遣になりますが、こちらは令和３年が１件、令和４年以降では０件の状況です。","id":"exchange-055"},{"speaker":"松永副委員長","kind":"質問・要望","question":"いろいろ調査の実績を３年間伺いました。ホームページを見ますと、調査が６件ということなのです。そこで、本区において現在、解体や調査については免許があるかないか、そうした事業者についてどのような形でやられているのか、お知らせいただきたいと思います。２０２８年頃にはピークを迎えるかと思います。そうしたことも踏まえて、今後この助成についてどのように検討されていくのか、お知らせください。","respondent":"鈴木都市環境部長","answer":"助成制度の拡充につきましては、先ほど直近の３年の実績を紹介させていただきましたが、項目によっては予定件数に達しているものもありますが、これまでの実績を見ると、やはりまだまだ周知をしっかりしていって、予定件数まで事業者にしっかり使っていただきたいと思いますので。","id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひ、こうした補助金や件数を増やしていただきたいと考えていますので、どうぞよろしくお願いします。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問","question":"初めにマイナ保険証について伺います。品川区の国民健康保険でマイナ保険証に登録した人は４８％、半数以下です。さらに、実際に使っているのは９％。つまり、９割以上の人が使っていません。昨日の東京新聞１面で、「保険証を残してほしい」が国民の８割です。区としてその周知はどうするのか。周知する中身についても伺います。マイナ保険証に登録しなくても、医療にはこれまで同様かかれるのか、伺います。","respondent":"遠藤健康推進部次長","answer":"私からマイナ保険証に関して順次お答えいたします。初めに、１２月２日の保険証廃止後の対応です。","id":"exchange-058"},{"speaker":"鈴木委員","kind":"質問・要望","question":"共産党は、保険証は残すべきと主張しています。医療現場でも国民も、今の保険証を残すべきと強く求めています。それが行政の役割でもあると思います。保険証の期限が切れる前に資格確認書が送られて、それで医療にかかれることや、「マイナ保険証に登録した人でも取り消すことができます」と、これを周知していただきたいと思うのですが、周知するのか、またしないのであればその理由を伺います。","respondent":"遠藤健康推進部次長","answer":"先ほど、１１月に広報等でお知らせするという形でありますけれども、そちらも含めまして、一般的な事項の一つとして、そちらも周知を行う予定です。マイナ保険証の登録取消し等についても同様に考えているところです。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問・要望","question":"「マイナ保険証に登録していなくても医療にはかかれます」と、その周知の徹底について、改めて強く求めておきたいと思います。この調査結果をご覧になられていますでしょうか。医療現場が大混乱の実態をどう受け止められているか、伺います。資格確認書は暫定的なものであり、保険証とは根本的に違います。今からでも保険証廃止をやめるよう、国に求めていただきたいと思いますが、いかがでしょうか。","respondent":"遠藤健康推進部次長","answer":"こちらの結果につきましては様々あるかと思いますけれども、区といたしましては国により是正するものと考えておりますので、対応を注視していきたいと考えているところです。","id":"exchange-060"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それもぜひ見ていただきたい。国民の８割、そして医療現場の９割が反対しているのに、なぜこれほど強行するのか。今からでも保険証廃止の撤回を国に求めるよう改めて強く求めて、次の質問に移ります。次は、障害者グループホームの増設を求めて質問したいと思います。残り９人分で公約達成ということなのか伺います。これまで補助金を出して建設されたグループホームの数と、その年度についても伺います。","respondent":"寺嶋福祉部長","answer":"障害者グループホームの公約のご質問だと思いますけれども、まず令和３年度の１２８名という定員をベースに、もともとは令和６年度までに４８名分の定員増という実施計画の指標、これに対しまして令和８年度末までに１００名分の定員増に引き上げる。これが公約です。","id":"exchange-061"},{"speaker":"鈴木委員","kind":"確認","question":"残り９名分で公約達成ということなのか、確認させてください。グループホーム等施設入所者の６割、３２４人もの方が区外に入らざるを得ない状況です。このことに対して、区としてどう捉えているのか伺います。改善が必要だと思いますが、いかがでしょうか。そして、区内に戻りたいと希望している方の人数と、その受皿をどうつくるのかも伺います。","respondent":"寺嶋福祉部長","answer":"数字ですけれども、細かいのですけれども、直近で１名の定員増の届出がありましたので、残り８名ということになります。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"施設と併せて、区内に戻りたいと希望している方の人数を教えていただきたいと思います。最も求められている知的障害、身体障害、中・重度者、また医療的ケア対象のグループホームをどう整備していくのか。品川区としても、知的障害、中・重度者、そして医療的ケア者を対象としたグループホームについて、整備が必要な数は明らかになっているのか、それぞれ何人分と考えているのか伺います。","respondent":"寺嶋福祉部長","answer":"ご紹介の世田谷区も確認しましたけれども、医療的ケアについては想定数という形になっていると把握しております。身体障害のみという希望者は実態としてニーズが少ないということもありまして、現在は見込み数３１７名、うち精神障害が１２３名、このように見込んでおります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"整備が必要な数と、整備時期も明確に示した計画をぜひとも持っていただくように私は求めたいと思います。そのことについても改めて伺います。そして、その具体化のために、世田谷区のように区有地の洗い出し・活用とともに、民間物件の購入や借受け可能な土地建物の積極活用の検討も求めますが、いかがでしょうか。事業者の負担軽減についても具体的に検討を求めます。いかがでしょうか。","respondent":"寺嶋福祉部長","answer":"それから用地確保については、区有地の活用を含めた用地の確保、助成金等を活用した事業者の参入、この辺もしっかり進めていくとともに、重度者受入れをはじめとした事業者支援についても、これまで同様、引き続き検討を進めてまいります。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"民間任せでは、当事者・家族が求めるグループホームは足りないままだと私は思います。今回の一般質問で、共産党が１０年以上にわたって求め続けた、地域の総合相談窓口、地域包括支援センターを地域に設置することを検討することとなったことを歓迎します。期待を込めて質問します。関係者が、地域包括支援センターとはどうあるべきなのかの認識の共有がまず必要ではないかと思いますが、いかがでしょうか。","respondent":"寺嶋福祉部長","answer":"スケジュール感としましては、今年度第９期がスタートしたということになりまして、先ほど申し上げた地域包括支援センター運営協議会が毎年開催されますので、この中で１０期に向けて方向性を示せるように検討を進めたいと考えています。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１８年間にわたり地域に地域包括支援センターをつくらずに、保健師や社会福祉士を配置してこなかったひずみというのは、私は大きいと思っています。切り替えるに当たっては、体制も十分取っていただいて、区民にとって安心して暮らせる地域、頼れる包括センターの設置を求めて、安藤委員に代わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"私からは、羽田新ルート再開発について質問いたします。昨年、区が実施した区民アンケートでは、新ルートによる影響を尋ねています。幾つか声を紹介します。大気汚染。」 電波障害。」「携帯の通信障害がよくあるので対応を考えてほしい。改めて伺います。率直な感想はいかがでしょうか。それと、これだけの声が寄せられているわけですから、区として測定や調査を行うべきではないでしょうか。伺います。","respondent":"鈴木都市環境部長","answer":"昨年の区民アンケートで頂いたご意見は、区としては国に直接、自由意見も含め、全て届けているところです。区としましては今後も、区に寄せられた区民の声を直接国に届けるとともに、引き続き必要な取組の実施、区民負担の軽減を、国に対し強く求めてまいります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"被害の訴えが出ている生活の場所、品川区内の測定調査が必要だと思いますが、いかがでしょうか。区は、国のこの調査により、羽田新ルートは資産価値に影響がないと考えているのか、伺いたいと思います。電波障害については、電波障害を訴える声がこれだけ出ているわけです。私は、この声を受けて調査が行われるべきだと思うのですけれども、調査は行われる必要がないと考えているのか伺います。","respondent":"鈴木都市環境部長","answer":"引き続き、国に対し、大気環境調査の定期的な実施など、必要な取組の実施を求めていくです。資産価値につきましては、調査の結果の考察あるいは結果につきましては、実施主体の国において区民に丁寧に説明・周知が行われるべきものと考えております。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、調査を実施し、行政の責任を果たすよう、強く求めたいと思います。区長はつぶさに知っているのでしょうか。しかし、実際には何が起きているのでしょうか。改めて、この３つの街区それぞれの開発協力企業の名前を教えてください。それぞれの土地所有者、借地権者、マンション区分所有者の数と、開発地区面積、見込まれる事業費と補助金額も伺います。先ほどの羽田の質問と併せて答弁をお願いします。","respondent":"鈴木都市環境部長、鴇田都市整備推進担当部長","answer":"大臣からは、重いアンケートであり、しっかり受け止め、検討すると応じていただいたところです。今後も引き続き国に対し、区民への丁寧な説明・周知と、区民負担の軽減につながる取組を強く求めてまいります。総事業費、補助金額につきましては、現在、各準備組合によりまちづくり検討が行われている状況であるため、未定となっています。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"ただいまの答弁がありましたけれども、こちらは昨年４月の開発協議会のニュースに掲載された写真なのですが、下です。私は地権者の方から、準備組合に入らないと資料を渡さないと開発準備組合から言われたと伺いました。伺います。おかしいと思いますけれども、いかがでしょうか。権利を持つ住民には、加入の有無にかかわらず、準備組合は検討資料を渡すよう指導すべきです。いかがでしょうか。","respondent":"鴇田都市整備推進担当部長","answer":"各準備組合により検討されている内容の情報発信ですけれども、基本的には、情報を保持している主体である各準備組合が判断するものと考えています。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺います。これらの事例は真っ当な住民同士の話合いと言えるのでしょうか。区は準備組合に是正を指導すべきではないのか、伺います。このように、住民合意どころか、開発企業の横暴で住民の居住権・財産権・人権が侵されている実態に、住民からも、区長に直接話を聞いてほしい、この苦境の話を聞いてほしいという要望が届いています。私は当然の要望だと思います。区長、いかがでしょうか。","respondent":"鴇田都市整備推進担当部長","answer":"一方、一部の地権者より、区長に直接その実態を聞いてもらいたいという願いにつきましては、市街地再開発事業を所管しています都市環境部にて対応したいと考えています。その際に頂いた様々な意見につきましては適宜区長にもお伝えし、情報を共有していきたい。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長からの答弁がないのが非常に残念なのですけれども、区長に聞いてもらいたいという思いがありますので、ぜひ応えていただきたいと、改めて求めたいと思います。最後に、区が開発に反対する住民を、クレーマー、カスハラ扱いしている問題です。こちらをご覧ください。伺います。都市開発課は、なぜこちらの請願、議会に請願・陳情を出すことを、カスタマーハラスメントと捉えたのか伺います。","respondent":"鴇田都市整備推進担当部長","answer":"後段のカスタマーハラスメントの質問ですが、委員のご指摘は、昨年区で実施しました悪質クレームカスタマーハラスメントの状況調査と考えますが、本調査は悪質クレーム等の実態を把握するための調査であり、本調査については、長時間対応を要するなど。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"超高層開発は大きく見直すべきときに来ています。住民の暮らしと財産を守るのが区の役割だと強く申し上げて、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"藤原委員","kind":"質問・要望","question":"シェアサイクルを何回も要望してきましたけれども、それも実現されました。なぜあそこに喫煙所をつくらないといけないのでしょうか。そして、喫煙所を変えていく、場所ではなくて変えていくといっても、全然変わらないではないですか。これはどうなっているのですか。もう、場所も変更ということも考えて動いていかないといけないと思うのですが、いかがでしょうか。そのことについてもお伺いします。","respondent":"川島地域振興部長、柏原区長室長、鴇田都市整備推進担当部長、鈴木都市環境部長","answer":"喫煙所の場所ということですが、現在の喫煙者数に対応するには、あちらが、場所的な環境、それから人の動線からも最適な位置であるということで。移設等々のお話もありますけれども、先ほど地域振興部長からも答弁がありましたけれども、他のいろいろな施設といいますか、ものがありますので。引き続き、区は区民の自主的なまちづくり活動を支援するため、協議会に対し、活動費の一部を助成するとともに。整備手法とともに、課題の解決手法について、今後も検討を進めてまいります。","id":"exchange-074"},{"speaker":"藤原委員","kind":"質問・要望","question":"ずっと雑草だらけだから、やってほしいと。いわゆる危険度５です。それで、これは堀越副区長にお伺いしたいのですけど、堀越副区長と私は、北海道胆振東部地震の体験者ですよね。水回りが全部、変ではないですか。それもよく考えて、まちづくり、駅前ということを考えていただきたいと思いますが、いかがでしょうか。ホームドアの件も、ぜひ強く要望していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市環境部長、堀越副区長、柏原区長室長、溝口防災まちづくり部長","answer":"ただいまご紹介いただきましたが、西大井駅のトイレですが、設置された経緯をご説明いたしますと、西大井駅は昭和５９年に建設が開始されましたが。それで、そういったものを目にしまして、今、部長からも不燃化領域率を上げる答弁がございましたけれども、そういった中で。それで、委員がおっしゃるとおり、あそこの水道の管が、なかなか近くには通っていなくて、そこに水道管を通すとなると。西大井駅のホームドアの件についてお答えします。","id":"exchange-075"},{"speaker":"藤原委員","kind":"質問","question":"原踏切の先に伊藤公墓地があります。品川区の子どもたちに伊藤博文公ということでどういうふうに教育しているのか教えてください。それと、品川歴史館で一応、伊藤博文公の特集といいますか、イベントをやられたほうがいいと私は思うのです。そして、あそこの四つ角の信号機、伊藤博文公の墓所前というプレートがついています。それだけ私たちは伊藤博文公に強い思いがあるのですけれども、いかがでしょうか。","respondent":"米田教育次長、辻文化観光スポーツ振興部長","answer":"出身地の山口県光市の小学校とのリモート交流会も、併せて行っているところです。引き続き、地域ゆかりの人物や資源等の学習も含めまして、学校教育の充実を図ってまいります。引き続き、伊藤博文公に焦点を当てた展示の可能性を探りながら、歴史や資料の研究を進めてまいりたいと考えております。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、介護従事者の処遇改善についてお伺いします。４億４,６００万円、処遇改善をつけてくれて本当にありがとうあります。それと福祉部、役所の人員は大丈夫ですか。それと、あと、今、国は在宅支援を求めているにもかかわらず、在宅支援をしてくださいというのに、訪問介護の報酬が減るという、とんでもないことをやっていると思っています。その辺についてご答弁を頂きたいと思います。","respondent":"森澤区長、新井副区長、寺嶋福祉部長","answer":"そういったときにしっかりと区民の皆さんを支えられる品川区でありたいと考えていますので、しっかりと施策を進めていきたいと思います。頂いたご懸念について２点、ご説明させていただければと思います。訪問介護の基本報酬が下がったということなのですけれども、介護保険が国制度なのでということでの答弁で終わらせるつもりは全くございませんで。","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"品川改革連合の須貝行宏は、これから藤原委員から引き続いて総括質疑をします。１万品目以上の物価が上がっている現状です。教えてください。一方、事業主は借金を増やしながら経費節減をして経営を続けていますので、区も何かしらの支援をするべきだと私は思いますが、教えてください。そして、認識していたら支援の手をやはり今は差し伸べる時期ではないかと私は思うのですが、ご答弁をお願いいたします。","respondent":"川島地域振興部長","answer":"物価高騰などによる経済への影響は地域全体の課題であり、中小企業の資金繰り対策にとどまらず、今後の事業継続、それから持続的な成長に向けまして、経済環境の変化を踏まえた支援策が引き続き必要であると認識しています。","id":"exchange-078"},{"speaker":"須貝委員","kind":"質問","question":"非課税世帯には給付金の支援がされています。子育て支援も増えていますが、年収が４００万円以下の中・低所得者層にも支援が必要だと私は思います。お風呂屋や運送業には助成金支援がありましたが、他の産業には助成金がありません。そして、こんな不公平な対応でいいのでしょうか。お答えください。この現状では、所得が低い人ほど物価高騰の影響が多いと私は思いますが、ご答弁をお願いいたします。","respondent":"川島地域振興部長","answer":"かなり幅広に補助対象を設けておりまして、非常に使いやすい制度になったと考えていますので、こういったものも活用していただきながら、今後とも区内事業者の経営環境の変化に対応しまして、必要な支援を積極的に進めていきたいと考えております。","id":"exchange-079"},{"speaker":"須貝委員","kind":"意見","question":"部長の答弁がありましたが、設備資金、融資あっ旋、そうではないですよね。今、何とか、毎日毎日つないでいく。生活もつないでいく。そして経営もつないでいく。そして、大東市では市独自の施策として、物価高騰対策給付事業として、住民基本台帳から１１万８,０００人分を対象として行っています。品川区もそうです。今はその時期ではないかと思うのですが、もう一回ご答弁をお願いいたします。","respondent":"川島地域振興部長","answer":"委員と経済状況等の認識というのは同じでございまして、しっかりとした区としての対策ということで、今説明したとおりの事業を着実に進めていきたいと思っているところです。","id":"exchange-080"},{"speaker":"須貝委員","kind":"質問","question":"では次に、品川区の入札についてお聞きします。区では、区有施設の建設や改善計画を立てたら、その設計を行い、工事に係る予定価格を算出します。次に、入札予定価格の上限価格を決めて、入札に参加する業者にこの金額を公表します。１億円なら１億円まで提示できるからです。これが実態です。建築や修繕工事の場合は３社以上の業者から見積りを取り、より安く信用できる業者にお願いします。お答えください。","respondent":"久保田企画経営部長","answer":"私どもは、予定価格１００万円以上の発注につきましては、予定価格を公表しています。これは、契約事務の公平性・透明性の確保のほか、事業者等が職員から予定価格を聞き出そうとするような、いわゆる官製談合を未然に防止するということを目的として行っているといったものです。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"民間の業者では一切、予定価格を提示していませんが、これも同じように、自治体が官製談合防止とおっしゃいましたけど、教えなくても教えても、民間でも同じような状況だと思うのです。そうしたら、もうあらかじめ、片一方は１億円の予定価格なら１億円、片一方は９,９９９万９,９９９円を提示すればいい。おまけに、制限付一般競争入札の落札率は９７％から９９％と高率です。９９.９９％もあります。","respondent":"久保田企画経営部長","answer":"それと委員から、落札が随意で、もう事業者が決まっているのではないかというようなご指摘がありましたけれども、私どもとしましては、入札といった制度をきちんと執行しておりまして、そういった指摘は当たらないものと考えているところです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"先ほど部長のご答弁がありましたけれども、工事に参加できないなら、私は、入札の名簿から外すべきだと思うのです。分かっているのだから。それをわざわざ載せて、辞退、辞退、辞退と、我々に総務委員会で報告されます。だって、もともとやれないのではないですか。途中で気がついた。そうしたら、最後に残るのは１社だけ残る。それが１社入札ということですよね。お答えください。","respondent":"久保田企画経営部長","answer":"工事に最初、辞退するような事業者は参加させないようにすればいいのではないかというご質問ですけれども、どの事業者が辞退をするか我々は把握してございませんので、そういったことをすること自体ができないということと、やはり事業者に対しましては。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"そのぐらい各企業、自分の自己管理ができない、契約管理ができないようでは、そんな会社は危ないのではないですか。私はそう思います。でも、もし質の低下というお答えならば、では実際に質が低下したのでしょうか。そういう例が多々あるのですか。そして毎回毎回、きちんとした入札に対しても、後で適正な評価をしているのですか。私はそういうことまで考えるべきだと思うのですが、もう一度ご答弁ください。","respondent":"久保田企画経営部長","answer":"私は質の低下というようなお答えはしてございませんので、入札の機会を与えまして、きちんと公平性・透明性を担保していきたいということをご答弁させていただいたです。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"民間では、あまりそういうことはないのです。民間で入札するとき、辞退、辞退、辞退。こんな例はほとんどないです。私は、そこはやはりもう一度よく考えるべきではないかと思います。次に、ＪＶである企業共同体についてお聞きします。これが事実なら、何もしない、仕事をしないで支払いを受けていることになりますが、もしこれが本当ならおかしいと思うのですが、どうですか。お答えください。","respondent":"久保田企画経営部長","answer":"ＪＶの構成企業からは、管理事業者や主任技術者等が選任されまして、区と定例の会議や個別の打合せなどで、区の職員と一緒になって、やり取りをしているといったところもございまして、今、委員からご指摘のようなこと。","id":"exchange-085"},{"speaker":"須貝委員","kind":"意見","question":"落札率が９０％から９５％未満になった工事は談合の疑いがあると考えています。このように、品川区は落札率が、談合の疑いを持たれるような数値に入っていますので、すぐにでもこれは改善すべき数値ではないかと私は思うのですが、そして、公平公正な入札制度をつくれば、年間三十億円、五十億円という金額は生まれて予算を捻出できると私は思うのですが、その辺についてご見解をお聞かせください。","respondent":"久保田企画経営部長","answer":"そういったことを踏まえますと、品川区として公平公正な契約事務の手続を進めているところですので、そういったところを改善するといった予定もございません。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"落札率９５％。これは恐らく、民間でやったらどうなのですかね。こんな額で、先ほど申し上げました、９９.９９％で落札している。それで、９９.３％落札している。やはりこれは、私は考えてみるべきものだと思います。どうですか。そして、このような実態だったら、私はやはり、一般の人が見ても、これはおかしいと思うので、きちんと早く改善するべきだと思うのですが、ご見解をお聞かせください。","respondent":"久保田企画経営部長","answer":"手続上も、我々はきちんとした適正な手続を踏んで行ってありますので、改善する予定はございません。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"最初のところで、改めてなのですけれども、今回、再開して２年目というところになるのですが、先ほどの午前中の質疑で、今回の令和５年度の事務事業評価の所感に近いところは、もう既に出ておりますので、私からはこれからの見通しといいますか、中長期的な、今後どういうふうに事務事業評価を行っていくのか、あるいは財源捻出の、もう来年度については、ある程度、お示しいただいていますが。","respondent":"久保田企画経営部長","answer":"同様の方針の下、令和６年度も２０億円の財源捻出を目標にして事務事業評価を進めていきまして、そういった財源を活用しまして、区民の幸せにつながる、区民が真に必要とする区民サービスへと振り向け、「誰もが生きがいを感じ。","id":"exchange-088"},{"speaker":"松本委員","kind":"提案","question":"それであるならば、より行政の支援を求めている方たちに予算を振り向けるべきではないかということで、私は昨年の決算特別委員会で質疑をさせていただいたのですけれども、今日は長寿お祝い事業について、事務事業評価の中で検討させていただきたいと思います。安否確認なのです。執行率も効率性を確認する１つの指標ではありますが、本来は、よりコストや時間をかけずに同じ成果を得られないか。","respondent":"寺嶋福祉部長","answer":"最初に、長寿お祝い事業と安否確認との兼ね合いということですけれども、品川区で実施しております高齢者安否確認事業につきましては、救急代理通報システム、それから先ほどの長寿お祝い事業、それからその後。","id":"exchange-089"},{"speaker":"松本委員","kind":"質問","question":"そこで伺いたいのですが、女性委員の割合が低い審議会を、低いほうから３つ教えてください。そして、それぞれなぜ女性割合が低いのか、理由を伺います。都内には４０％をクリアしている自治体もありますが、そうした自治体でなぜ達成できたのかの分析は行われているのでしょうか。割合が低い審議会を所管する部署に対して、個別に数値目標を掲げるようにしてはどうかと思いますが、いかがでしょうか。","respondent":"柏原区長室長","answer":"ただ、今年度、新しい条例に基づきまして、行動計画の部分の見直しも今図っているところでございまして、この目標値についても、検討しているといったところになってあります。それから次に、審議会の中で女性の参加が少ないものを、低いほうからです。","id":"exchange-090"},{"speaker":"松本委員","kind":"提案","question":"本日は、有効性、効率性、あと評価基準の考え方、改善の考え方についてお伺いさせていただきました。事務事業評価が始まる前にも提案したところではあるのですけれども、この事務事業評価シートと、地方自治法第２３３条第５項の規定に基づく主要な施策の成果報告書は、やはり統合したほうが効率的ではないかと思いますが、最後にこの点をお伺いできればと思います。","respondent":"久保田企画経営部長","answer":"今すぐに統合ということには、いろいろと課題が多いと考えておりますので、地方自治法の規定等も踏まえながら、課題を検証しつつ、議会のご意見もお伺いしながら、引き続き検討していきたいと考えているところです。","id":"exchange-091"},{"speaker":"松本委員","kind":"質問・要望","question":"続きまして、防火水槽を中心とした震災対策について伺います。款別審査でも防火水槽について様々お伺いさせていただき、取り上げさせていただきました。そういうふうに考えるならば、防火水槽の設置・整備については、区が責任を持つということでよろしいでしょうか。伺います。そこで、区として各町会・自治会と連携して、各防火水槽の現状の確認、見回りを行ってはいかがかと思いますが、どうでしょうか。","respondent":"滝澤災害対策担当部長","answer":"一方、東京都の震災対策条例では、「知事は、地震による火災の拡大を防止するため、区市町村と連携を図りつつ、協力して消防水利の確保及び消防力の強化に努める」と定めておりまして、このため区では区の地域防災計画の中に。","id":"exchange-092","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"質問","question":"都は原則として４０m3以上の防火水槽を設置するという、４０m3で、以上と以下が両方入っていて、この４０m3をどこが担当しているのかというのが、微妙な書き方になっているというところもあって、この防火水槽の責任の所在というのはなかなか難しいところもあると思うのですが、それでも区も、重複してという形になるかもしれませんが、責任をお持ちだというところの認識で。","respondent":"滝澤災害対策担当部長","answer":"一方で区では、国土交通省の住宅市街地総合整備事業補助金や東京都防災密集地域総合整備事業補助金を活用して、木造密集地域における防災広場の整備に取り組んでおり、その中で防火水槽の設置を実施しているということで。","id":"exchange-093"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、まず事実としてお伺いしたいのですけれども、消火栓が使えないときに、これまでだったら消防水利というのは大体、対象となっている住宅から消防水利まで１００ｍとか１２０ｍという基準があったと思うのですが、これを、消火栓を除いて、その他の消防水利で距離との制限、距離との関係を見てきたときに、１００ｍ、１２０ｍというのを満たさない地域が出てくるのではないかと思いますが。","respondent":"滝澤災害対策担当部長","answer":"そのため、消防といたしましては、防火水槽の新設や増設を行う考えはございませんが、区としては、住民の不安払拭のために、必要に応じて消防と連携した対応を実施してまいりたいと考えているところです。","id":"exchange-094"},{"speaker":"松本委員","kind":"質問","question":"先ほど東京消防庁からは大丈夫だというふうなお話があったのですけれども、やはり基準で見ると消火栓を含めて整備計画が立てられているというところではないかと思うので、これから区として消火栓が使えない、ほかの自治体の中には消火栓がない状態でも満たしていける計画を立てているところがありますので、整備方針、整備計画を立てていただければと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"まつざわ委員","kind":"提案","question":"令和５年度決算は、森澤区長が就任後初めて編成した予算に基づくものであります。今回の決算特別委員会におきまして、区民の皆様や各種団体などから頂きました声をまとめ、会派の委員より指摘や政策提案を致しました。この指摘や提案が品川区の令和７年度予算事務事業に反映され、区政運営が区民福祉の一層の向上に寄与することを求め、品川区議会自民党・無所属の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"若林委員","kind":"提案","question":"令和５年度品川区一般会計は、歳入総額２,００５億円余で執行率９５％、実質収支は５９億円の黒字、財政健全化判断比率も良好と認められました。本決算特別委員会を通じ、ベーシックサービスの観点などから提案した教育関係費、介護、風水害対策の拡充をはじめ、会派からの意見・要望を真摯に受け止められ、今後の区政運営および来年度予算に反映されるよう求め、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"},{"speaker":"大倉委員","kind":"提案","question":"令和５年度の一般会計は、歳入総額約２０５億円、歳出総額約１,９４１億円、執行率が９５％となり、普通会計の実質収支も約５８億円を超える黒字となっており、財政健全化判断比率においても適正であり、健全財政を維持していることを確認いたしました。今後も時代に合わせた柔軟で迅速な対応を行い、区民生活と社会福祉向上に向け、施策を確実に実行していただくよう求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"その上、中止を求めるオンライン署名が過去最高５６万筆も提出されたにもかかわらず、１０月からインボイスを強行し、さらに国民を追い詰めました。区民の生活を守るため、地上に影響が出ないことを前提に始められたリニアの中止を国とＪＲ東海に求めるべきです。マイナ保険証はトラブル続き、９割以上が利用せず、医療機関も中止を求める。マイナ保険証への一本化はやめ、現行保険証の存続を求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川改革連合の令和５年度決算に対する意見表明を行います。令和５年度の一般会計、国民健康保険事業会計と後期高齢者医療、介護保険、災害復旧特別会計の各決算を認定します。買い控えや節約で消費が減少、中小企業は値上げできず、人手不足と資金難で融資返済もできず、廃業や倒産が増えているので、区は公平な支援に取り組んでいただきたい。羽田新飛行ルートの変更を国に働き続けていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"せらく委員","kind":"提案","question":"今回の決算特別委員会において、弊会派の各委員の質疑の中で指摘・提案した点について検討され、次年度の予算や今後の政策、事業に反映していただくよう要望するとともに、区が遂行する政策等については、全事業対象の事業評価による見直しを継続的に行い、区民のニーズに寄り添った質の高い施策を展開し、さらなる区民サービスの向上が図られることを求め、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6861#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":102437,"voices":234}}]);
